window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["nc"]={"id":"nc","num":5,"name":"Nutritional Counselling","area":"Counselling practice","lessons":[{"n":1,"title":"Nutrition Basics","kicker":"Lesson 1 of your course, built from Chapter 1 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l1-b1","chapter":"Ten ideas that run through the course","title":"Ten ideas that run through the course","teach":["Chapter 1 sets out ten nutrition principles that come up again at every life stage. Food is a basic human need. Food supplies energy, nutrients and other substances we need to grow and stay healthy. Nutrition problems start inside cells. Too little and too much of a nutrient can both cause harm, and the body has ways of coping with ups and downs in intake.","Malnutrition can come from a poor diet, from disease or genes, or from a mix of these. Some groups are at higher risk than others. Poor nutrition can help set up chronic disease. Healthy eating patterns are built on adequacy, variety and balance. And no single food is simply good or bad: what matters is how it fits into the whole diet."],"act":{"type":"choice","prompt":"A very active teenager who has already eaten well today has ice cream after practice. How does the chapter see this?","options":[{"label":"Ice cream is a bad food, so it should be avoided.","correct":false,"feedback":"The chapter's tenth principle is that there are no good or bad foods. It depends on the whole diet."},{"label":"It can fit well, because her nutrient needs are met and she needs the extra energy.","correct":true,"feedback":"Yes. The same food can fit one person's diet and not another's."},{"label":"Only foods labelled healthy should count toward her diet.","correct":false,"feedback":"Labels don't decide this. What matters is adequacy, variety and balance across the day."}]}},{"id":"l1-b2","chapter":"Nutrient intake standards","title":"Nutrient intake standards","teach":["The Dietary Reference Intakes (DRIs) are a set of standards. The Estimated Average Requirement (EAR) is the intake that meets the needs of half the healthy people in a group. It is used to judge whether a group's intake is adequate. The Recommended Dietary Allowance (RDA) is set higher, to cover nearly all healthy people (about 97–98%).","When there isn't enough evidence to set an RDA, an Adequate Intake (AI) is used. The Tolerable Upper Intake Level (UL) is the highest daily intake unlikely to cause harm. It is a safety limit, not a target. Nutrition labels use a separate set of reference amounts called Daily Values, and the % DV tells you how much of that amount one serving gives."],"act":{"type":"sort","prompt":"Match each standard with what it means.","categories":["EAR","RDA","AI","UL"],"items":[{"label":"Meets the needs of half the healthy people in a group","category":0,"feedback":"That is the Estimated Average Requirement."},{"label":"Covers nearly all healthy people","category":1,"feedback":"The RDA is set above the EAR to cover almost everyone."},{"label":"Used when there isn't enough evidence for an RDA","category":2,"feedback":"That is the Adequate Intake."},{"label":"Highest intake unlikely to cause harm","category":3,"feedback":"The Tolerable Upper Intake Level is a safety limit, not a goal."}]}},{"id":"l1-b3","chapter":"Counting calories from macronutrients","title":"Counting calories from macronutrients","teach":["Carbohydrate and protein give 4 Calories per gram, and fat gives 9. (Fibre gives about 2, and alcohol 7.) To find the Calories in a food, multiply the grams of each by its factor and add them up.","To find the share of Calories from one nutrient, divide its Calories by the total and multiply by 100. For adults, the Acceptable Macronutrient Distribution Ranges are 45–65% of Calories from carbohydrate, 10–35% from protein and 20–35% from fat. Sucrose (table sugar) is made of glucose and fructose."],"act":{"type":"number","prompt":"A snack has 30 g carbohydrate, 10 g protein and 10 g fat. How many Calories does it provide?","answer":250,"tolerance":0,"unit":"Calories","explanation":"30 × 4 = 120, 10 × 4 = 40 and 10 × 9 = 90. 120 + 40 + 90 = 250 Calories."}},{"id":"l1-b4","chapter":"Vitamins","title":"Vitamins","teach":["The B-complex vitamins and vitamin C dissolve in water. Vitamins A, D, E and K dissolve in fat (think DEKA). Apart from vitamin B12, the body's stores of water-soluble vitamins are small and run out within weeks to months when intake drops. Fat-soluble vitamins are stored in fat tissue, so a deficiency takes longer to show.","Vitamins C and E and beta-carotene (which the body turns into vitamin A) act as antioxidants. They help prevent or repair damage to cells from oxidation. Large doses from supplements, especially of vitamins A and D, can be toxic. Overdoses from food alone are very rare."],"act":{"type":"sort","prompt":"Sort each vitamin by how it dissolves.","categories":["Water-soluble","Fat-soluble"],"items":[{"label":"Vitamin C","category":0,"feedback":"Vitamin C dissolves in water."},{"label":"Thiamin (a B vitamin)","category":0,"feedback":"All the B-complex vitamins are water-soluble."},{"label":"Vitamin D","category":1,"feedback":"D is one of the fat-soluble vitamins: D, E, K and A."},{"label":"Vitamin K","category":1,"feedback":"K is fat-soluble and stored in body fat."}]}},{"id":"l1-b5","chapter":"Minerals, phytochemicals and water","title":"Minerals, phytochemicals and water","teach":["Minerals tend to bind with other substances, such as other minerals in supplements or fibre in food. Bound minerals can't be absorbed, so overall we absorb a smaller share of the minerals we eat than of the vitamins. Phytochemicals are substances in plants that aren't nutrients but may protect body processes and benefit health.","Adults are about 60–70% water. Water is the medium where most of the body's chemical reactions happen. It also plays a part in energy transformation, getting rid of wastes and controlling body temperature. Pale yellow urine in normal amounts is a sign of enough fluid."],"act":{"type":"choice","prompt":"Which of these is NOT a role of water described in the chapter?","options":[{"label":"Temperature regulation","correct":false,"feedback":"Controlling body temperature is one of water's roles."},{"label":"Excretion of wastes","correct":false,"feedback":"Water helps the body get rid of wastes."},{"label":"Regulating hunger hormones","correct":true,"feedback":"Right. The chapter lists reactions, energy transformation, waste removal and temperature control, but not this."}]}},{"id":"l1-b6","chapter":"Nutrient density and malnutrition","title":"Nutrient density and malnutrition","teach":["Nutrient-dense foods give plenty of nutrients for relatively few Calories. Examples are nonfat milk and yogurt, lean meat, dried beans, vegetables and fruit. Empty-calorie foods, like soft drinks and hard candy, give Calories with few nutrients. A diet made mostly of nutrient-dense foods is more likely to meet nutrient needs without going over energy needs.","Primary malnutrition comes from the diet itself, for example not having enough money for food. Secondary malnutrition is caused by a disease, surgery or medication that affects how the body uses nutrients."],"act":{"type":"sort","prompt":"Is each situation an example of primary or secondary malnutrition?","categories":["Primary (diet)","Secondary (disease, surgery or medication)"],"items":[{"label":"A family can't afford enough food at the end of the month.","category":0,"feedback":"The poor nutrition comes from the diet itself."},{"label":"Ongoing diarrhea keeps a person from absorbing nutrients.","category":1,"feedback":"A health condition causes the problem, so it is secondary."},{"label":"A student lives mostly on soft drinks and chips.","category":0,"feedback":"The cause is what she eats."},{"label":"Bleeding in the digestive tract leads to low iron.","category":1,"feedback":"The cause is a condition, not the diet."}]}},{"id":"l1-b7","chapter":"Reading labels and claims","title":"Reading labels and claims","teach":["Almost all foods with more than one ingredient must have a Nutrition Facts panel. The panel shows the serving size, nutrients such as fat, saturated fat, trans fat, cholesterol, sodium, carbohydrate, fibre, sugars and protein, and a % DV column. Labels also flag common allergens. The textbook uses the older U.S. label, on which vitamins A and C, calcium and iron were mandatory.","Enriched refined grains such as bread, cornmeal, crackers, flour tortillas and white rice must have thiamin, riboflavin, niacin and iron added back. Supplements have a Supplement Facts panel. They don't have to be proven safe and effective before they are sold, so their labels can't claim to treat, cure or prevent a disease."],"act":{"type":"choice","prompt":"Which claim would NOT be allowed on a supplement label?","options":[{"label":"“A good source of fibre”","correct":false,"feedback":"Standard nutrient content claims like this are allowed."},{"label":"“Cures joint pain”","correct":true,"feedback":"Right. Supplements can't claim to treat, cure or prevent a disease."},{"label":"“Calcium builds strong bones”","correct":false,"feedback":"Claims about how a nutrient supports the body are allowed."}]}},{"id":"l1-b8","chapter":"The life course and nutrition assessment","title":"The life course and nutrition assessment","teach":["Nutrition at one life stage affects health at the next. Poor nutrition in pregnancy can shape gene function for life, and iron deficiency in young children can affect learning later on. Everyone needs the same nutrients throughout life, but the amounts change with age, growth and development. There is no single best diet for everyone.","Assessing a person's nutrition has four parts: clinical (physical), dietary, anthropometric (body measurements) and biochemical (lab tests). You need all four. One measure, like normal weight or good iron levels, doesn't prove someone is well nourished."],"act":{"type":"sort","prompt":"Match each finding with the part of nutrition assessment it belongs to.","categories":["Clinical / physical","Dietary","Anthropometric","Biochemical"],"items":[{"label":"Pale skin and brittle nails noted during an exam","category":0,"feedback":"Physical signs are part of the clinical assessment."},{"label":"A 24-hour recall of everything eaten yesterday","category":1,"feedback":"Recalls and food records assess diet."},{"label":"Height, weight and waist measurement","category":2,"feedback":"Body measurements are anthropometric."},{"label":"Blood iron levels","category":3,"feedback":"Lab values are biochemical."}]}}],"flashcards":[{"front":"Estimated Average Requirement (EAR)","back":"The intake that meets the needs of half the healthy people in a group."},{"front":"Recommended Dietary Allowance (RDA)","back":"The intake that meets the needs of nearly all healthy people (about 97–98%)."},{"front":"Adequate Intake (AI)","back":"Used when there isn't enough evidence to set an EAR and RDA."},{"front":"Tolerable Upper Intake Level (UL)","back":"The highest daily intake unlikely to cause harm. A safety limit, not a target."},{"front":"Calories per gram","back":"Carbohydrate 4, protein 4, fat 9 (fibre about 2, alcohol 7)."},{"front":"Adult AMDRs","back":"Carbohydrate 45–65%, protein 10–35%, fat 20–35% of Calories."},{"front":"Sucrose","back":"Table sugar, made of glucose and fructose."},{"front":"Water-soluble vitamins","back":"The B-complex vitamins and vitamin C."},{"front":"Fat-soluble vitamins","back":"Vitamins A, D, E and K (DEKA). Stored in body fat, so deficiency is slower to appear."},{"front":"Antioxidant vitamins","back":"Vitamin C, vitamin E and beta-carotene."},{"front":"Phytochemicals","back":"Substances in plants that may protect body processes and benefit health."},{"front":"Nutrient-dense foods","back":"Foods with lots of nutrients and relatively few Calories."},{"front":"Primary vs. secondary malnutrition","back":"Primary comes from the diet. Secondary is caused by a disease, surgery or medication."},{"front":"Enriched grains must include…","back":"Thiamin, riboflavin, niacin and iron."},{"front":"Four parts of nutrition assessment","back":"Clinical/physical, dietary, anthropometric and biochemical."},{"front":"Roles of water","back":"Medium for chemical reactions, energy transformation, waste removal and temperature control."}],"quiz":[{"q":"The Estimated Average Requirement (EAR) means:","o":["an intake level that meets the nutrient needs of 98% of healthy people.","an intake value that meets the nutrient needs of half the healthy individuals in a group.","the upper limits of a nutrient compatible with health.","the nutrient intake standard for healthy people.","that this is a “tentative” RDA."],"a":1,"e":"Checked answer, not from an official key. Chapter 1 defines the EAR as meeting the needs of half the healthy people in a group."},{"q":"What two monosaccharides are found in sucrose (table sugar)?","o":["Glucose and lactose","Glucose and glucose","Glucose and maltose","Glucose and fructose"],"a":3,"e":"Checked answer, not from an official key. Sucrose is glucose joined to fructose."},{"q":"Which of the following statements about food labels is FALSE?","o":["They note the presence of common food allergens.","They appear on almost all multiple-ingredient foods.","They list the content of fat, saturated fat, trans fat, and cholesterol.","They contain information about the amount recommended for ingestion each day.","They list the % Daily Value (%DV) for each relevant nutrient."],"a":3,"e":"Checked answer, not from an official key. Labels show amounts per serving and % DV, which is a general reference, not a recommended amount for you to eat each day."},{"q":"Producers of bread, cornmeal, crackers, flour tortillas, white rice, and other products made with refined grains MUST use flours enriched with which of the following?","o":["Thiamin","Niacin","Iron","Riboflavin","All of the above"],"a":4,"e":"Checked answer, not from an official key. By law, enriched flour must have thiamin, riboflavin, niacin and iron added."},{"q":"What mandatory nutrient is missing from the food label? (Refers to the label in your test.)","o":["Unsaturated fats","Simple sugars","Vitamin C","Vitamin K"],"a":2,"e":"Checked answer, not from an official key. On the older label used in the textbook, vitamin C was mandatory. The other choices weren't required."},{"q":"Does this product fall within the Acceptable Macronutrient Distribution Range for fat? (The label in your test shows 170 Calories per serving, 45 from fat.)","o":["Yes","No"],"a":0,"e":"Checked answer, not from an official key. 45 ÷ 170 × 100 is about 26%, which is within the adult fat range of 20–35%."},{"q":"After class, you go to Jamba Juice and get an “Orange-a-Peel” smoothie that contains the following nutrients: 9 g of protein, 102 g carbohydrate, and 1 g of fat. How many total Calories does this provide?","o":["299","399","448","453","546"],"a":3,"e":"Checked answer, not from an official key. 9 × 4 = 36, 102 × 4 = 408 and 1 × 9 = 9. 36 + 408 + 9 = 453."},{"q":"A woman ate 1/2 of a pita bread sandwich filled with tuna salad. The entire sandwich contained 20 grams carbohydrate, 8 grams protein, and 5 grams fat. Approximately how many calories did she obtain?","o":["80","130","150","160"],"a":0,"e":"Checked answer, not from an official key. The whole sandwich is 80 + 32 + 45 = 157 Calories. Half is about 79, so about 80."},{"q":"If the woman in question #8 drank a glass of regular, fortified milk, what is the most important essential nutrient that she added to her diet?","o":["Calcium","Cholesterol","Fluoride","Glucose","Vitamin C"],"a":0,"e":"Checked answer, not from an official key. Milk is a major source of calcium."},{"q":"What nutrient would someone susceptible to high blood pressure be consuming too much of with a meal consisting of a salami sandwich, chicken noodle soup, and whole milk?","o":["Sugar","Caffeine","Sodium","Water","Calcium"],"a":2,"e":"Checked answer, not from an official key. Salami and canned or packaged soup are high in sodium."},{"q":"Phytochemicals are chemical substances found in _____ that protect human body processes and may benefit health.","o":["animals","the human body","plants","both plants and animals","None of the above"],"a":2,"e":"Checked answer, not from an official key. “Phyto” means plant. These substances come from plants."},{"q":"Which of the following vitamins acts as an antioxidant in the body?","o":["Vitamin C","Vitamin E","Beta-carotene","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook names vitamins C and E and beta-carotene as antioxidants."},{"q":"Which of the following is NOT one of the roles that water plays in the body?","o":["Energy transformation","Energy metabolism regulation","Excretion of wastes","Temperature regulation","Medium in which most chemical reactions take place"],"a":1,"e":"Checked answer, not from an official key. The textbook lists every other choice as a role of water."},{"q":"Nutrient-dense foods can be defined as:","o":["foods that are both good sources of nutrients and low in Calories.","foods that contain low amounts of nutrients and are high in Calories.","foods that are both good sources of nutrients and high in Calories.","foods that contain low amounts of nutrients and are low in Calories.","all animal-derived foods."],"a":0,"e":"Checked answer, not from an official key. Nutrient-dense foods have lots of nutrients for relatively few Calories."},{"q":"Which of the following would NOT be considered one of the four components of nutrition assessment?","o":["Anthropometric","Biochemical","Clinical/physical","Initial evaluation","Dietary"],"a":3,"e":"Checked answer, not from an official key. The four parts are clinical/physical, dietary, anthropometric and biochemical."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nHow many Calories from carbohydrates is Jill consuming daily?","o":["750","1000","1750","2250"],"a":1,"e":"Checked answer, not from an official key. 250 g × 4 = 1,000 Calories."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nThe percentage of energy that comes from Jill’s intake of carbohydrate is:","o":["12%.","25%.","48%.","57%.","65%."],"a":2,"e":"Checked answer, not from an official key. Her total is 1,000 + 900 + 200 = 2,100 Calories. 1,000 ÷ 2,100 × 100 is about 48%."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nThe percentage of energy that comes from Jill’s intake of fat is:","o":["13%.","30%.","43%.","56%."],"a":2,"e":"Checked answer, not from an official key. 100 g × 9 = 900 Calories. 900 ÷ 2,100 × 100 is about 43%."},{"q":"Good food sources of antioxidants would include which of the following foods?","o":["Bananas, raisins, figs","Oranges, sweet potatoes, bell peppers","Spinach, blueberries, cranberries","All of the above","b and c only"],"a":4,"e":"Checked answer, not from an official key. Less certain: the foods in b and c are the ones the textbook lists as rich in antioxidant vitamins, but raisins and figs also contain some antioxidants, so check this one against your graded result."},{"q":"Which of the following would NOT be an example of an approved dietary supplement claim?","o":["Calcium builds strong bones","Calcium prevents bone fracture","Vitamin E, an antioxidant, helps maintain cell membranes","XYZ helps promote urinary tract health","XYZ gives you energy and focus throughout your busy day"],"a":1,"e":"Checked answer, not from an official key. Supplement labels can't claim to prevent a disease or condition, such as a fracture."},{"q":"The water-soluble vitamins include:","o":["A, D, E, and K.","A and C.","B-complex and C.","B-complex and K.","All vitamins are water soluble."],"a":2,"e":"Checked answer, not from an official key. The B-complex vitamins and vitamin C dissolve in water."},{"q":"A diet low in fat-soluble vitamins will result in a more rapid onset of deficiency symptoms than one low in water-soluble vitamins.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Fat-soluble vitamins are stored in body fat, while most water-soluble vitamin stores run out within weeks to months, so it's the other way around."},{"q":"Typically, we absorb a greater percentage of minerals than vitamins.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Minerals often bind to other substances and can't be absorbed, so we absorb a smaller share of minerals than vitamins."},{"q":"Not having enough money to buy food to eat is an example of a potential cause of primary malnutrition.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Primary malnutrition comes from the diet itself."},{"q":"What food serving below does NOT provide significant amounts of iron?","o":["Round steak, 3 oz","Pork and beans, 1/2 cup","Peaches, 1/2 cup","Iron-fortified breakfast cereal, 1 cup"],"a":2,"e":"Checked answer, not from an official key. Less certain: meat, beans and fortified cereal are well-known iron sources, and peaches have very little, but check this one against your graded result."}]},{"n":2,"title":"Preconception Nutrition","kicker":"Lesson 2 of your course, built from Chapters 2 and 3 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l2-b1","chapter":"Getting pregnant isn't a sure thing","title":"Getting pregnant isn't a sure thing","teach":["Many conceptions never become a pregnancy anyone knows about. About 30–50% are lost in the first six weeks, and another 9% end in miscarriage in the first 20 weeks. The most common known cause of miscarriage is a severe defect in the fetus. Others include infection in the mother, problems with the shape of the uterus, hormone or immune problems, and random events.","Couples are called subfertile when the woman has had several miscarriages, the man has sperm problems such as a low count or poorly moving sperm, or the woman ovulates only now and then. About 18% of married couples in the U.S. are subfertile. Nutrition is one of the things that can help or hurt fertility."],"act":{"type":"choice","prompt":"Which of these would be described as subfertile?","options":[{"label":"A woman who ovulates only a few times a year","correct":true,"feedback":"Yes. Ovulating infrequently is one of the signs of subfertility."},{"label":"A woman who has just reached menopause","correct":false,"feedback":"Menopause ends fertility. Subfertility means reduced, not absent, fertility."},{"label":"A couple who conceived in their third month of trying","correct":false,"feedback":"Subfertility is usually defined as more than 12 months to conceive, or repeated losses."}]}},{"id":"l2-b2","chapter":"Hormones and the menstrual cycle","title":"Hormones and the menstrual cycle","teach":["A typical cycle is about 28 days and starts on the first day of bleeding. The first half is the follicular phase, and the last 14 days are the luteal phase. Early in the cycle, the pituitary gland releases follicle-stimulating hormone (FSH) and luteinizing hormone (LH). FSH helps eggs mature in the ovary.","Just before ovulation, usually on day 14, FSH and LH peak. The surge of LH releases the egg. If there is no pregnancy, the uterus makes prostaglandins, which make it contract and shed its lining. Prostaglandins are behind cramps and other side effects of menstruation."],"act":{"type":"sort","prompt":"Match each hormone or substance with what it does.","categories":["FSH","LH","Prostaglandins"],"items":[{"label":"Helps eggs mature in the ovary","category":0,"feedback":"Follicle-stimulating hormone drives follicle growth."},{"label":"Its surge on about day 14 triggers ovulation","category":1,"feedback":"The LH surge releases the egg."},{"label":"Makes the uterus contract, causing cramps","category":2,"feedback":"Prostaglandins from the uterus cause menstrual cramps."}]}},{"id":"l2-b3","chapter":"Body fat and fertility","title":"Body fat and fertility","teach":["Both too much and too little body fat can lower fertility in women and men. Fat cells make estrogen, testosterone and leptin, and these hormones affect egg development, ovulation and sperm. In people with obesity, losing body fat improves hormone levels, oxidative stress, inflammation and conception rates.","In normal-weight women, losing more than about 10–15% of usual weight lowers estrogen, LH and FSH. Periods can stop, ovulation can stop, and the luteal phase can become short or disappear. This is called functional hypothalamic amenorrhea, and hormone levels usually recover once weight is back to within 95% of before. Being underweight in pregnancy raises the risk of complications for the mother and of small, early babies. Young female athletes and dancers often start their periods 2–4 years later than average."],"act":{"type":"choice","prompt":"Which hormone is NOT made by fat cells?","options":[{"label":"Estrogen","correct":false,"feedback":"Fat cells do make estrogen."},{"label":"Leptin","correct":false,"feedback":"Leptin is made by fat cells."},{"label":"Insulin","correct":true,"feedback":"Right. Insulin comes from the pancreas. Fat cells make estrogen, testosterone and leptin."}]}},{"id":"l2-b4","chapter":"Folate and iron before pregnancy","title":"Folate and iron before pregnancy","teach":["All women who could become pregnant are advised to get 400 mcg of folic acid a day from fortified foods or a supplement. Good folate status around conception lowers the risk of neural tube defects such as spina bifida. One serving of a breakfast cereal fortified with 400 mcg of folic acid covers it. Gluten-free grain products may not be fortified, so check the label.","Iron status before pregnancy matters too. Low iron stores going into pregnancy are linked to poorer outcomes, and they are hard to build up once pregnancy starts."],"act":{"type":"choice","prompt":"How much folic acid a day is recommended for every woman who could become pregnant?","options":[{"label":"40 mcg","correct":false,"feedback":"That's ten times too little."},{"label":"400 mcg","correct":true,"feedback":"Yes, 400 micrograms a day from fortified foods or a supplement."},{"label":"400 mg","correct":false,"feedback":"Watch the units. The amount is 400 micrograms (mcg), not milligrams."}]}},{"id":"l2-b5","chapter":"What can throw fertility off","title":"What can throw fertility off","teach":["Conditions that affect fertility usually work through one of four routes. They change the hormones that control ovulation, change the presence or length of the luteal phase, reduce sperm production, or affect the tubes that eggs and sperm must travel through. An infection that scars the tubes is an example of the last one.","Hormonal birth control can also have nutrition side effects. Combination pills tend to lower HDL cholesterol and raise LDL cholesterol, triglycerides, blood glucose and insulin a little."],"act":{"type":"choice","prompt":"Which of these is NOT one of the ways hormone changes affect fertility, according to the chapter?","options":[{"label":"A short or missing luteal phase","correct":false,"feedback":"The textbook lists this as one of the effects."},{"label":"Lower sperm production","correct":false,"feedback":"Reduced sperm production is one of the routes."},{"label":"No follicular phase","correct":true,"feedback":"Right. The chapter talks about the luteal phase, ovulation, sperm and the passageways, not losing the follicular phase."}]}},{"id":"l2-b6","chapter":"Central body fat and metabolic syndrome","title":"Central body fat and metabolic syndrome","teach":["Fat stored deep in the abdomen is linked to insulin resistance, high insulin, inflammation, oxidative stress and metabolic syndrome. In women, high insulin leads the ovaries to make more testosterone, which disrupts egg development. Polycystic ovary syndrome (PCOS) often comes with high abdominal fat, even in normal-weight women.","Metabolic syndrome is a cluster of risk factors, not one disease. It is diagnosed when three of these five are present: waist over 40 inches in men or 35 inches in women, triglycerides of 150 mg/dL or more, HDL cholesterol under 40 mg/dL in men or 50 mg/dL in women, blood pressure of 130/85 or more, and fasting blood glucose of 100 mg/dL or more."],"act":{"type":"number","prompt":"A woman has a 37-inch waist, triglycerides of 160 mg/dL, HDL of 55 mg/dL, blood pressure of 118/76 and fasting glucose of 104 mg/dL. How many of the five criteria does she meet?","answer":3,"tolerance":0,"unit":"criteria","explanation":"Waist (over 35), triglycerides (150 or more) and fasting glucose (100 or more) count. Her HDL and blood pressure are fine. Three criteria means she would be diagnosed with metabolic syndrome."}},{"id":"l2-b7","chapter":"Diabetes and PKU before pregnancy","title":"Diabetes and PKU before pregnancy","teach":["High blood glucose in the first two months of pregnancy is teratogenic: it raises the risk of birth defects two- to three-fold and also raises the risk of miscarriage. Good glucose control before conception helps. Low-glycemic-index foods and plenty of fibre, about 14 g per 1,000 Calories, help keep blood glucose steady.","Phenylketonuria (PKU) is an inherited condition in which the body can't break down the amino acid phenylalanine. High phenylalanine early in pregnancy harms the baby's brain development and raises the risk of heart defects. Untreated, there is a 92% chance of intellectual disability and a 73% chance of an abnormally small head (microcephaly). That's why the PKU diet needs to be under control before pregnancy."],"act":{"type":"number","prompt":"Using 14 g of fibre per 1,000 Calories, how much fibre should someone eating 2,000 Calories a day aim for?","answer":28,"tolerance":0,"unit":"g","explanation":"14 g × 2 = 28 g of fibre a day."}},{"id":"l2-b8","chapter":"PMS and PMDD","title":"PMS and PMDD","teach":["Premenstrual syndrome (PMS) brings physical and emotional changes that start in the luteal phase and go away within two days after bleeding starts. It affects about 20–40% of women who menstruate.","Premenstrual dysphoric disorder (PMDD) is a severe form of PMS that affects about 5% of women who menstruate. It brings marked mood swings, anxiety, irritability, low mood, strained relationships and physical symptoms such as breast tenderness, headaches and joint or muscle pain. It seems to come from extra sensitivity to normal hormone changes."],"act":{"type":"choice","prompt":"Which of these is part of PMDD?","options":[{"label":"Mood swings only","correct":false,"feedback":"Mood swings are part of it, but so are other symptoms."},{"label":"Physical symptoms only","correct":false,"feedback":"PMDD includes emotional symptoms as well."},{"label":"Mood swings, irritability, low mood and physical symptoms","correct":true,"feedback":"Yes. PMDD includes all of these."}]}}],"flashcards":[{"front":"Miscarriage rate in the first 20 weeks","back":"About 9% of pregnancies."},{"front":"Most common known cause of miscarriage","back":"A severe defect in the fetus."},{"front":"Subfertile","back":"Women with multiple miscarriages, men with sperm problems, or women who ovulate infrequently."},{"front":"Hormones released by the pituitary in the follicular phase","back":"Follicle-stimulating hormone (FSH) and luteinizing hormone (LH)."},{"front":"When does LH peak in a 28-day cycle?","back":"Around day 14, just before ovulation."},{"front":"Cause of menstrual cramps","back":"Prostaglandins made by the uterus."},{"front":"Hormones made by fat cells","back":"Estrogen, testosterone and leptin."},{"front":"Functional hypothalamic amenorrhea","back":"Loss of periods after losing more than about 10–15% of usual weight."},{"front":"Delay in first period for young athletes","back":"Often 2–4 years."},{"front":"Folic acid before pregnancy","back":"400 mcg a day for all women who could become pregnant."},{"front":"Metabolic syndrome","back":"Three of five: large waist, high triglycerides, low HDL, high blood pressure, high fasting glucose."},{"front":"High blood glucose early in pregnancy","back":"Teratogenic. Two- to three-fold higher risk of birth defects."},{"front":"Fibre for blood glucose control","back":"About 14 g per 1,000 Calories."},{"front":"Untreated PKU in pregnancy","back":"Raises the risk of heart defects, microcephaly and intellectual disability in the baby."},{"front":"PMDD","back":"Severe PMS with mood swings, irritability, low mood, anxiety and physical symptoms."}],"quiz":[{"q":"What is the rate of miscarriages in the first 20 weeks of pregnancy?","o":["6%","7%","8%","9%"],"a":3,"e":"Checked answer, not from an official key. The textbook says 9% are lost to miscarriage in the first 20 weeks."},{"q":"The most common cause of miscarriage for women is:","o":["structural abnormalities in the uterus.","the presence of a severe defect in the fetus.","maternal infection.","endocrine disorders.","unknown random events."],"a":1,"e":"Checked answer, not from an official key. The textbook names a severe defect in the fetus as the most common known cause."},{"q":"The two hormones secreted by the pituitary gland during the FOLLICULAR phase of a woman’s cycle are:","o":["follicle-stimulating hormone and progesterone.","progesterone and estrogen.","follicle-stimulating hormone and luteinizing hormone.","luteinizing hormone and progesterone.","luteinizing hormone and estrogen."],"a":2,"e":"Checked answer, not from an official key. Early in the cycle the pituitary releases FSH and LH."},{"q":"Fat cells produce all of the following hormones that may interfere with reproductive processes EXCEPT:","o":["estrogen.","testosterone.","leptin.","insulin.","Fat cells do not produce any of these hormones."],"a":3,"e":"Checked answer, not from an official key. Fat cells make estrogen, testosterone and leptin. Insulin comes from the pancreas."},{"q":"Loss of body fat in obese men and women is related to:","o":["improved hormone levels.","reduced oxidative stress.","improved conception rates.","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook links losing body fat to better hormone levels, less oxidative stress and better conception rates."},{"q":"Women who experience multiple miscarriages, men who have sperm abnormalities, and women that ovulate infrequently may be classified as:","o":["fertile.","infertile.","subfertile.","menopausal.","infecund."],"a":2,"e":"Checked answer, not from an official key. The textbook calls these people subfertile."},{"q":"The recommended daily intake of folic acid for ALL women who may become pregnant is:","o":["40 mcg.","40 mg.","400 mcg.","400 mg.","400 g."],"a":2,"e":"Checked answer, not from an official key. 400 micrograms a day."},{"q":"The primary effect(s) of being underweight on reproduction in women is/are:","o":["high likelihood of maternal complications.","the birth of small and early infants.","spina bifida or other NTDs.","All of the above","Both a and b"],"a":4,"e":"Checked answer, not from an official key. Being underweight raises the risk of complications for the mother and of small, early babies. Neural tube defects are linked to low folate, not low weight."},{"q":"Cramps and other side effects of menstruation can be traced back to the production of _______________________________ by the uterus.","o":["progesterone","estrogen","prostaglandins","pituitary hormones","both a and b"],"a":2,"e":"Checked answer, not from an official key. Prostaglandins make the uterus contract."},{"q":"When hormones are altered in the body, many changes take place that affect fertility; which of the following would NOT be one of those changes?","o":["Change in length or presence of the luteal phase","A decrease in the production of sperm","Alterations in the passageways that ova and sperm travel","Absence of the follicular phase","All of the above would be changes that occur."],"a":3,"e":"Checked answer, not from an official key. The textbook lists ovulation, the luteal phase, sperm production and the passageways, but not the follicular phase."},{"q":"Young female athletes often experience a delay in menarche of approximately what duration?","o":["1-2 years","2-4 years","No delay in menarche","6 mo-1 year","None of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook says menarche is often delayed by 2–4 years."},{"q":"In a “typical” 28-day cycle, when would levels of luteinizing hormone most likely be the highest?","o":["Day 1","Day 7","Day 10","Day 14","Day 28"],"a":3,"e":"Checked answer, not from an official key. LH peaks just before ovulation, usually on day 14."},{"q":"Premenstrual dysphoric disorder (PMDD) is characterized by:","o":["mood swings.","irritability.","depressed mood.","physical symptoms.","All of the above"],"a":4,"e":"Checked answer, not from an official key. PMDD includes all of these."},{"q":"Untreated phenylketonuria in pregnant women can lead to:","o":["increased risk of heart defects in the infant.","infants with microcephaly.","mental retardation in their children.","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook names heart defects, microcephaly and intellectual disability."},{"q":"______________________________ during the first 2 months of pregnancy is teratogenic and leads to a two- to three-fold risk of congenital abnormalities.","o":["A high blood glucose level","Type 1 diabetes","Type 2 diabetes","Insulin resistance","Celiac disease"],"a":0,"e":"Checked answer, not from an official key. The textbook says high blood glucose in the first two months is teratogenic."},{"q":"Diets that provide low-glycemic index carbohydrates along with _______________________ of fiber daily are associated with improved blood glucose control.","o":["15 g","25-35 g","14 g per 1000 calories","38 g","50 g"],"a":2,"e":"Checked answer, not from an official key. The textbook recommends about 14 g of fibre per 1,000 Calories."},{"q":"Excess central body fat is related to ____________________________________.","o":["insulin resistance","increased sperm count","decreased testosterone production in females","increased testosterone production in males","decreased oxidative stress"],"a":0,"e":"Checked answer, not from an official key. Fat deep in the abdomen is linked to insulin resistance."},{"q":"Use the following information to answer questions 19 and 20.\n\nJane and her husband are interested in having a child, but she has had a hard time conceiving. She has met with her OB-GYN to have a physical, labs drawn, and a prenatal check-up in order to determine what the problem is. Lab work and other relevant data for Jane are as follows:\nAge: 36\nBlood pressure: 110/70 mm Hg\nFasting blood glucose: 130 mg/dL\nHDL cholesterol 35 mg/dL\nBlood triglycerides: 175 mg/dL\nWaist circumference: 36\"\nCurrent weight: 150 lbs\nHeight: 5'3\"\n\nBased on the data above, Jane will likely be diagnosed with:","o":["type 2 diabetes","metabolic syndrome","celiac disease","hypothalamic amenorrhea","gestational diabetes"],"a":1,"e":"Checked answer, not from an official key. Jane meets four of the five criteria for metabolic syndrome: high fasting glucose, low HDL, high triglycerides and a waist over 35 inches. Less certain: a fasting glucose of 130 could also point to type 2 diabetes, but the test seems to be built around metabolic syndrome, so check this one against your graded result."},{"q":"Jane and her husband are interested in having a child, but she has had a hard time conceiving. She has met with her OB-GYN to have a physical, labs drawn, and a prenatal check-up in order to determine what the problem is. Lab work and other relevant data for Jane are as follows:\nAge: 36\nBlood pressure: 110/70 mm Hg\nFasting blood glucose: 130 mg/dL\nHDL cholesterol 35 mg/dL\nBlood triglycerides: 175 mg/dL\nWaist circumference: 36\"\nCurrent weight: 150 lbs\nHeight: 5'3\"\n\nWhich of the following symptoms would indicate that Jane has this diagnosis?","o":["Her blood pressure, weight, and height","Hard time with conception and her age","High fasting blood glucose, blood triglycerides, and HDL cholesterol levels","Her waist circumference, age, and blood pressure","All of the above"],"a":2,"e":"Checked answer, not from an official key. Her fasting glucose and triglycerides are high and her HDL is low, which are three of the five criteria. Her blood pressure is normal."}]},{"n":3,"title":"Pregnancy Nutrition","kicker":"Lesson 3 of your course, built from Chapters 4 and 5 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l3-b1","chapter":"Why pregnancy nutrition matters","title":"Why pregnancy nutrition matters","teach":["What a woman eats before and during pregnancy affects the baby's growth, health at birth and even health later in life. Infant deaths are one way to measure how well a population is doing. Two-thirds of deaths of babies born alive happen in the first month after birth, the newborn period. Low birthweight and preterm birth are major reasons.","Each organ has a critical period of fast growth. A shortage at that exact time can cause lasting harm that can't be fixed later. The neural tube, which becomes the brain and spinal cord, forms in weeks 3 and 4 after conception, often before a woman knows she is pregnant. That is why folate matters so much early on."],"act":{"type":"choice","prompt":"When does the neural tube, which becomes the spinal cord, form?","options":[{"label":"1–2 weeks after conception","correct":false,"feedback":"A little too early. It forms in weeks 3 and 4."},{"label":"3–4 weeks after conception","correct":true,"feedback":"Yes, which is often before a woman knows she's pregnant."},{"label":"7–8 weeks after conception","correct":false,"feedback":"By then the critical period for the neural tube has passed."}]}},{"id":"l3-b2","chapter":"How the mother's body changes","title":"How the mother's body changes","teach":["Early in pregnancy, the mother's blood volume expands. Nutrients, some drawn from her stores, go first to support this expansion. The greater the expansion, the larger the baby tends to be. The extra water in the blood dilutes some vitamins and minerals, so blood levels can look lower even when intake is fine.","Hormones made by the placenta drive many of these changes. In the second half of pregnancy the body uses more fat, so blood lipids rise a lot. Triglycerides more than double, and cholesterol rises too. The placenta uses cholesterol to make hormones, and the baby uses it for nerve and cell membranes. Levels return to normal after birth."],"act":{"type":"choice","prompt":"What happens to blood cholesterol and triglycerides during pregnancy?","options":[{"label":"They drop because the blood is diluted.","correct":false,"feedback":"Dilution lowers some vitamins and minerals, but lipids go up."},{"label":"They rise a lot from pre-pregnancy levels.","correct":true,"feedback":"Yes. Triglycerides more than double by the end of pregnancy."},{"label":"They stay the same.","correct":false,"feedback":"They change a lot, especially in the second half of pregnancy."}]}},{"id":"l3-b3","chapter":"The placenta","title":"The placenta","teach":["The placenta makes hormones and enzymes, handles the exchange of nutrients and gases between mother and baby, and removes the baby's waste. It also acts as a partial barrier, but it is more like a fence than a filter. Many harmful things, including alcohol, some drugs, excess vitamins and bacteria such as listeria, can pass through.","Some substances don't cross at all. Maternal insulin is one: the baby has to make its own. That's why high blood glucose in the mother leads the baby to make extra insulin."],"act":{"type":"choice","prompt":"Which statement about the placenta is accurate?","options":[{"label":"It blocks alcohol and drugs from reaching the baby.","correct":false,"feedback":"It's more like a fence than a filter. Alcohol and many drugs do pass through."},{"label":"It makes hormones, exchanges nutrients and gases, and removes waste.","correct":true,"feedback":"Yes. These are its main jobs."},{"label":"Maternal insulin passes through it easily.","correct":false,"feedback":"Insulin doesn't cross the placenta. The baby makes its own."}]}},{"id":"l3-b4","chapter":"How much weight to gain","title":"How much weight to gain","teach":["Recommended weight gain depends on the woman's BMI before pregnancy. The Institute of Medicine ranges for one baby are: underweight (BMI under 18.5), 28–40 lb; normal weight (18.5–24.9), 25–35 lb; overweight (25–29.9), 15–25 lb; and obese (30 or more), 11–20 lb.","BMI is weight in kilograms divided by height in metres squared. For twins, the recommended gain is higher."],"act":{"type":"number","prompt":"A woman is 1.65 m tall and weighs 75 kg before pregnancy. What is her BMI? (Round to one decimal.)","answer":27.5,"tolerance":0.1,"unit":"kg/m²","explanation":"1.65 × 1.65 = 2.72. 75 ÷ 2.72 = 27.5. She is overweight, so the recommended gain is 15–25 lb."}},{"id":"l3-b5","chapter":"Key nutrients in pregnancy","title":"Key nutrients in pregnancy","teach":["Pregnant women need 71 g of protein a day, and most North American women already eat about that much. The recommendation for folate is 600 mcg a day, including 400 mcg of folic acid from fortified foods or a supplement. The rest can come from vegetables and fruit.","DHA, an omega-3 fat, supports the baby's brain and eyes. Pregnant women are advised to eat 2–3 servings a week of fish or seafood that is low in mercury, such as shrimp, canned light tuna, salmon, pollock and catfish. They should avoid high-mercury fish like swordfish, king mackerel, tilefish and shark. Algae-based DHA is an option for vegetarians."],"act":{"type":"choice","prompt":"Which of these would give a pregnant woman the most DHA?","options":[{"label":"A tuna salad sandwich","correct":true,"feedback":"Yes. Fish such as tuna is the main food source of DHA."},{"label":"A glass of whole milk","correct":false,"feedback":"Regular milk has very little DHA."},{"label":"A cup of broccoli","correct":false,"feedback":"Vegetables don't provide DHA."}]}},{"id":"l3-b6","chapter":"Pica and food safety","title":"Pica and food safety","teach":["Pica is a craving for and eating of non-food items such as ice, laundry starch or cornstarch, baking soda or clay. It is an eating disorder and is more common in non-Hispanic Black American women than in other groups. Women with pica are more likely to have low iron, though it isn't clear which comes first.","Pregnant women are more vulnerable to foodborne illness, especially listeria, which can cross the placenta. Foods to avoid include soft cheeses such as brie (unless made with pasteurized milk), ready-to-eat deli meats unless heated until steaming, raw oysters and other raw seafood, and unpasteurized milk."],"act":{"type":"sort","prompt":"Sort each food by its food safety risk in pregnancy.","categories":["Avoid or handle with care","Low risk"],"items":[{"label":"Unpasteurized milk","category":0,"feedback":"Can carry listeria and other bacteria."},{"label":"Raw oysters","category":0,"feedback":"Raw seafood carries a risk of foodborne illness."},{"label":"Cold deli meat straight from the package","category":0,"feedback":"Heat deli meats until steaming to kill listeria."},{"label":"A washed banana","category":1,"feedback":"Fresh fruit you peel is low risk."}]}},{"id":"l3-b7","chapter":"High blood pressure and preeclampsia","title":"High blood pressure and preeclampsia","teach":["Hypertension is blood pressure of 140/90 mm Hg or higher. High blood pressure disorders of pregnancy affect 5–10% of pregnancies and are a leading cause of death in mothers around the world. Preeclampsia usually appears after 20 weeks, with high blood pressure plus signs such as headache, blurred vision, belly pain and abnormal liver tests.","In preeclampsia, small blood clots and poor blood flow most affect the placenta and the mother's kidneys, liver and brain. Helpful habits include plenty of fruit and vegetables, enough fibre, moderate activity and enough vitamin D. High-dose iron supplements should not be given, because they can make inflammation worse."],"act":{"type":"choice","prompt":"Which of these is NOT recommended for a woman at risk of preeclampsia?","options":[{"label":"Five or more servings of fruit and vegetables a day","correct":false,"feedback":"This is recommended."},{"label":"High-dose iron supplements","correct":true,"feedback":"Right. High-dose iron can increase inflammation and shouldn't be given."},{"label":"Moderate exercise","correct":false,"feedback":"Moderate activity is part of the advice."}]}},{"id":"l3-b8","chapter":"Diabetes in pregnancy","title":"Diabetes in pregnancy","teach":["When the mother's blood glucose is high, the extra glucose reaches the baby. The baby responds by making more insulin, which moves glucose into its cells and turns it into fat. This can lead to a large baby and may raise the child's risk of type 2 diabetes later.","Type 1 diabetes is usually the most hazardous type in pregnancy, because of higher risks of kidney disease, high blood pressure, preeclampsia and other complications. Gestational diabetes develops during pregnancy. Insulin sensitivity usually improves once the placenta is delivered, but these women have a higher chance of gestational diabetes in later pregnancies and of type 2 diabetes."],"act":{"type":"choice","prompt":"What does the baby do when the mother's blood glucose is high?","options":[{"label":"Makes more insulin","correct":false,"feedback":"Yes, but that's only part of it."},{"label":"Turns extra glucose into stored fat","correct":false,"feedback":"True, but there's more."},{"label":"All of these, and it may raise the child's later risk of type 2 diabetes","correct":true,"feedback":"Right. Extra insulin, fat storage and a possible later risk all go together."}]}},{"id":"l3-b9","chapter":"Twins and other multiple pregnancies","title":"Twins and other multiple pregnancies","teach":["Only about 3% of babies come from multiple pregnancies, but they make up a large share of low-birthweight and preterm babies. Many twin pregnancies lose one embryo early on, which is called the vanishing twin. It is not unusual for embryos to disappear within 13 weeks of conception.","Carrying more than one baby raises the mother's risk of preeclampsia, iron-deficiency anemia, preterm delivery and cesarean birth. A 40-lb gain for twins takes about 35,000 more Calories over the pregnancy than a single pregnancy, roughly 150 extra Calories a day. A prenatal vitamin and mineral supplement is generally advised."],"act":{"type":"choice","prompt":"What is the vanishing twin phenomenon?","options":[{"label":"The disappearance of an embryo within 13 weeks of conception","correct":true,"feedback":"Yes. Many pregnancies that start as twins end with one baby."},{"label":"Fewer twins being born because of fertility drugs","correct":false,"feedback":"Fertility treatment actually raised the number of multiple births."},{"label":"One twin being much smaller at birth","correct":false,"feedback":"That's a growth difference, not the vanishing twin."}]}}],"flashcards":[{"front":"Infant deaths in the first month","back":"About two-thirds of infant deaths happen in the newborn period."},{"front":"Critical period for the neural tube","back":"Weeks 3 and 4 after conception."},{"front":"Blood lipids in pregnancy","back":"Rise a lot. Triglycerides more than double by the end of pregnancy."},{"front":"Dilution effect","back":"Expanded blood volume lowers blood levels of some vitamins and minerals."},{"front":"Main jobs of the placenta","back":"Making hormones and enzymes, exchanging nutrients and gases, and removing waste."},{"front":"Does insulin cross the placenta?","back":"No. The baby makes its own insulin."},{"front":"Weight gain for an overweight woman (BMI 25–29.9)","back":"15–25 lb."},{"front":"Protein in pregnancy","back":"71 g a day."},{"front":"Folate in pregnancy","back":"600 mcg a day, with 400 mcg as folic acid from fortified foods or a supplement."},{"front":"DHA in pregnancy","back":"2–3 servings a week of low-mercury fish or seafood."},{"front":"Pica","back":"Eating non-food items such as ice, starch or clay. More common in non-Hispanic Black American women."},{"front":"Hypertension","back":"Blood pressure of 140/90 mm Hg or higher."},{"front":"Leading cause of maternal death worldwide","back":"High blood pressure disorders of pregnancy."},{"front":"Organs most affected in preeclampsia","back":"The placenta and the mother's kidneys, liver and brain."},{"front":"Most hazardous type of diabetes in pregnancy","back":"Type 1 diabetes."},{"front":"Extra Calories for a twin pregnancy","back":"About 35,000 more over the pregnancy, roughly 150 a day."}],"quiz":[{"q":"Approximately what proportion of infants who die within the first year of life die within the first month after birth?","o":["1/3","2/3","1/2","3/4","5/8"],"a":1,"e":"Checked answer, not from an official key. The textbook says two-thirds of infant deaths happen in the first month."},{"q":"How can the change in lipid blood levels that occurs during pregnancy best be described?","o":["Cholesterol and triglyceride levels decrease due to the increased water volume in the blood","Cholesterol and triglyceride levels remain the same as pre-pregnancy levels","Cholesterol and triglyceride levels increase dramatically from pre-pregnancy levels","Cholesterol and triglyceride levels fluctuate daily depending on when the fetus is building nerve cells"],"a":2,"e":"Checked answer, not from an official key. The textbook says blood lipids increase dramatically, with triglycerides more than doubling."},{"q":"All of the following substances are transported through the placenta easily, with the exception of _________________, which is not transferred at all.","o":["water","cholesterol","oxygen","ketones","insulin"],"a":4,"e":"Checked answer, not from an official key. Maternal insulin does not cross the placenta. The baby makes its own."},{"q":"A critical period of spinal cord development following conception is:","o":["1-2 weeks after conception.","3-4 weeks after conception.","5-6 weeks after conception.","7-8 weeks after conception.","9-10 weeks after conception."],"a":1,"e":"Checked answer, not from an official key. The neural tube becomes the brain and spinal cord during weeks 3 and 4."},{"q":"The recommended daily protein (g) intake for pregnant women is _____.","o":["30 g","71 g","90 g","120 g"],"a":1,"e":"Checked answer, not from an official key. 71 g a day."},{"q":"Research is emerging that suggests pregnant women should increase their food sources of docosahexaenoic acid (DHA). Which of the following foods would provide the most DHA to pregnant women?","o":["1/2 tuna salad sandwich","1/4 cup granola containing 1 tsp sunflower seed","8 oz glass whole milk","1 cup broccoli"],"a":0,"e":"Checked answer, not from an official key. Fish such as tuna is the main food source of DHA."},{"q":"Pregnant women of ____________________________ ethnicity are more likely than those of other ethnicities to have an eating disorder known as pica.","o":["Chinese","African American","White Caucasian","Hispanic","Hmong"],"a":1,"e":"Checked answer, not from an official key. The textbook says pica is more common in non-Hispanic Black Americans."},{"q":"______________________________ do(es) NOT pose any foodborne bacterial risks in pregnant women.","o":["Brie cheese","Ready-to-eat deli meats","Raw oysters","Unpasteurized milk","Organic bananas"],"a":4,"e":"Checked answer, not from an official key. The others can carry listeria or other bacteria."},{"q":"Why must volume expansion occur BEFORE maternal nutrient stores accumulate?","o":["In order to support large gains in fetal weight","In order to provide the fetus with sufficient energy, nutrients, and oxygen","In order to provide the mother with plenty of fluids","In order to dilute the high concentration of nutrients in pregnant women","In order to make room for growing organs"],"a":1,"e":"Checked answer, not from an official key. Less certain: the textbook says expanded blood volume carries nutrients and oxygen to support the pregnancy, but it doesn't answer this question directly, so check it against your graded result."},{"q":"Which of the following is a major function of the placenta?","o":["Hormone and enzyme production","Nutrient and gas exchange between mother and fetus","Removal of waste products from the fetus","Barrier to drugs and alcohol","a, b, and c","all of the above"],"a":4,"e":"Checked answer, not from an official key. The placenta isn't a reliable barrier. Alcohol and many drugs pass through it."},{"q":"Use the following information to answer questions 11-13:\n\nJane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nWhat is Jane’s body mass index?","o":["19.7","25.1","31.4","43"],"a":1,"e":"Checked answer, not from an official key. 72.7 ÷ (1.70 × 1.70) = 72.7 ÷ 2.89 = 25.1."},{"q":"Jane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nBased on her BMI, Jane would be considered:","o":["underweight.","normal weight.","overweight.","obese.","morbidly obese."],"a":2,"e":"Checked answer, not from an official key. A BMI of 25–29.9 is overweight."},{"q":"Jane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nJane becomes pregnant. How many pounds should Jane gain during her pregnancy, based on her BMI?","o":["11 to 20","15 to 25","25 to 35","28 to 40","35 to 45"],"a":1,"e":"Checked answer, not from an official key. The recommendation for overweight women is 15–25 lb."},{"q":"The recommended daily dietary intake of folate during pregnancy is:","o":["200 mcg from fortified food or supplements.","400 mcg from fortified food or supplements.","600 mcg total with 400 mcg from fortified food or supplements.","800 mcg total with 600 mcg from fortified food or supplements.","4000 mcg total in any form."],"a":2,"e":"Checked answer, not from an official key. 600 mcg a day, including 400 mcg of folic acid."},{"q":"Hypertension is defined as having a blood pressure of _____.","o":["≥120 mm Hg systolic or ≥70 mm Hg diastolic","≥140 mm Hg systolic or ≥90 mm Hg diastolic","≥120 mm Hg systolic or ≥90 mm Hg diastolic","≥140 mm Hg systolic or ≥70 mm Hg diastolic","≥160 mm Hg systolic or ≥110 mm Hg diastolic"],"a":1,"e":"Checked answer, not from an official key. The textbook uses 140/90 mm Hg."},{"q":"A worldwide leading cause of MATERNAL mortality is:","o":["gestational diabetes.","hypertensive disorders of pregnancy.","AIDS/HIV.","multifetal pregnancies.","adolescent pregnancy complications."],"a":1,"e":"Checked answer, not from an official key. The textbook names high blood pressure disorders of pregnancy."},{"q":"Maternal organs most affected by small blot clots and reduced blood flow in preeclampsia include all of the following EXCEPT:","o":["the placenta","the kidneys.","the brain.","the appendix.","the liver."],"a":3,"e":"Checked answer, not from an official key. The textbook lists the placenta, kidneys, liver and brain."},{"q":"Nutritional and physical activity recommendations that may benefit women at risk for preeclampsia include all of the following EXCEPT:","o":["high-dose iron supplements.","5 or more servings of fruits and vegetables daily.","moderate exercise.","adequate fiber intake","adequate vitamin D."],"a":0,"e":"Checked answer, not from an official key. High-dose iron can increase inflammation and shouldn't be given."},{"q":"High maternal blood glucose levels cause the fetus to ____________________________________________________.","o":["increase insulin output","convert glucose into triglycerides and store it as fat","potentially develop type 2 diabetes later in life","All of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook describes all three effects."},{"q":"Which type of diabetes is potentially the most hazardous to the mother and fetus?","o":["Type 1 diabetes","Type 2 diabetes","Gestational diabetes","They are all equally hazardous."],"a":0,"e":"Checked answer, not from an official key. The textbook says type 1 is usually the most hazardous."},{"q":"The vanishing twin phenomenon refers to:","o":["the fact that more triplets and quadruplets are being born because of fertility drugs.","the disappearance of embryos within 13 weeks of conception.","the decreasing percentage of dizygotic twins in favor of monozygotes.","None of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook defines it this way."},{"q":"A multifetal pregnancy increases the mother’s risk for:","o":["development of preeclampsia","development of iron-deficiency anemia","preterm delivery","cesarean delivery","All of the above"],"a":4,"e":"Checked answer, not from an official key. Multiple pregnancies raise the risk of all of these."},{"q":"To achieve a 40-pound weight gain, women with twins need to consume approximately _________ more calories during pregnancy than do women with singleton pregnancies.","o":["15,000","25,000","35,000","45,000","50,000"],"a":2,"e":"Checked answer, not from an official key. The textbook gives about 35,000 Calories, or roughly 150 a day."},{"q":"“Best practice” vitamin and mineral supplement recommendations for women during multifetal pregnancies include which of the following statements?","o":["There is no need to take a vitamin and mineral supplement if you are eating enough food.","Women with twins need to take more iron.","Women should use a prenatal vitamin and mineral supplement.","Women with twins need to take twice the recommended amount of a supplement."],"a":2,"e":"Checked answer, not from an official key. The textbook's twin case uses a prenatal vitamin and mineral supplement. It doesn't support doubling the dose."}]},{"n":4,"title":"Lactation Nutrition","kicker":"Lesson 4 of your course, built from Chapters 6 and 7 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l4-b1","chapter":"How the breast makes milk","title":"How the breast makes milk","teach":["During puberty, the cyclic release of estrogen and progesterone develops the breasts. The working units of the mammary gland are the alveoli: clusters of milk-secreting cells around a small duct. The ducts branch like a tree toward the nipple. Muscle-like cells around the alveoli contract under the hormone oxytocin to push milk out (the letdown).","Breast size depends mostly on fat and doesn't decide how much milk a woman can make. Milk supply works on supply and demand: the more fully the breast is emptied, the more milk it makes. If a lot of milk is left behind, production slows."],"act":{"type":"choice","prompt":"What are the functional units of the mammary gland?","options":[{"label":"Alveoli","correct":true,"feedback":"Yes. Each alveolus is a cluster of cells that secrete milk."},{"label":"Areolas","correct":false,"feedback":"The areola is the darker skin around the nipple, not where milk is made."},{"label":"Lobules","correct":false,"feedback":"Lobules are groups of alveoli. The alveoli are the units that make milk."}]}},{"id":"l4-b2","chapter":"What's in breast milk","title":"What's in breast milk","teach":["Breast milk is mostly water, so a breastfed baby doesn't need extra water. Lactose is the main carbohydrate, and it helps the baby absorb calcium. Fat gives about half the energy. Fat is lower in the foremilk at the start of a feed and higher in the hindmilk at the end. Whey, the main protein, forms a soft curd that is easy to digest. Milk also carries antibodies, so nursing while the mother is sick helps protect the baby.","Milk from mothers of preterm babies has more protein and energy (58–70 kcal per 100 mL). Breast milk is low in vitamin K, so all newborns get a vitamin K shot at birth. Without it, a baby can bleed too much because the blood doesn't clot properly."],"act":{"type":"sort","prompt":"Match each part of breast milk with what it does.","categories":["Lactose","Whey","Hindmilk","Antibodies"],"items":[{"label":"Main carbohydrate. Helps calcium absorption.","category":0,"feedback":"Lactose is the dominant carbohydrate in human milk."},{"label":"Forms a soft, easily digested curd","category":1,"feedback":"Whey protein makes a soft curd in the baby's stomach."},{"label":"Higher-fat milk at the end of a feed","category":2,"feedback":"Hindmilk is richer in fat than foremilk."},{"label":"Protect the baby from germs the mother meets","category":3,"feedback":"The mother makes antibodies to germs around her and passes them on in her milk."}]}},{"id":"l4-b3","chapter":"Latch and feeding","title":"Latch and feeding","teach":["A good latch means the baby's mouth takes in a large part of the areola, with the nose close to the breast and breathing freely. The mother should hear swallowing, but not smacking, clicking or slurping. Those sounds suggest a poor latch, which raises the risk of sore nipples.","If a baby always nurses briefly on both breasts, they may get lots of low-fat foremilk and not enough hindmilk. That can cause gas, colic, loose stools and slow weight gain. Letting the baby finish one breast before switching, and having someone watch a feed, helps."],"act":{"type":"choice","prompt":"A baby makes smacking and clicking sounds while nursing. What does that tell you?","options":[{"label":"The baby is feeding well.","correct":false,"feedback":"You should hear swallowing, not smacking or clicking."},{"label":"The baby probably isn't latched on correctly, which can lead to sore nipples.","correct":true,"feedback":"Yes. These sounds point to a poor latch."},{"label":"Nothing. Some babies are just noisy.","correct":false,"feedback":"These sounds are a sign worth checking."}]}},{"id":"l4-b4","chapter":"The mother's diet","title":"The mother's diet","teach":["Drinking extra fluid doesn't raise milk supply. Mothers should drink to thirst and aim for pale yellow urine, rather than counting glasses. Mothers don't need to avoid common allergy foods unless the baby seems to react. If a baby has colic, cutting out cow's milk, eggs, peanuts, tree nuts, wheat, soy or fish has helped in studies. Only cut out foods that seem to cause problems, and replace the nutrients they provided.","Fish is good for mother and baby, but she should choose low-mercury seafood and avoid swordfish, shark and king mackerel."],"act":{"type":"choice","prompt":"A nursing mother asks how many glasses of water she should drink each day. What's the best answer?","options":[{"label":"At least 10 glasses","correct":false,"feedback":"Drinking extra doesn't raise milk supply, and needs vary."},{"label":"Drink to thirst, enough to keep your urine pale yellow","correct":true,"feedback":"Yes. Thirst and urine colour are better guides than a set number."},{"label":"6–8 glasses, no more","correct":false,"feedback":"There's no set number. Thirst is the guide."}]}},{"id":"l4-b5","chapter":"Common breastfeeding problems","title":"Common breastfeeding problems","teach":["Sore nipples, engorgement, plugged ducts and mastitis are all common. Mild nipple soreness in the first week is normal, but cracks or pain that lasts call for a check of the latch. Engorgement, swollen and overfull breasts, peaks around days 3–5. It can happen any time the breasts aren't emptied for a long stretch, such as missing several feeds.","Mastitis is inflammation or infection of the breast. The mother should keep nursing or pumping, because emptying the breast helps it clear. Rest, fluids, pain relief and, if it doesn't improve within 24 hours, antibiotics are used."],"act":{"type":"choice","prompt":"A new mother misses six hours of feeds while out. What problem is she most likely to have?","options":[{"label":"Engorgement","correct":true,"feedback":"Yes. Going a long time without emptying the breasts leads to engorgement."},{"label":"Sore nipples","correct":false,"feedback":"Sore nipples usually come from a poor latch, not from skipped feeds."},{"label":"Jaundice","correct":false,"feedback":"Jaundice is a newborn condition, not a problem for the mother."}]}},{"id":"l4-b6","chapter":"Medications, herbs and alcohol","title":"Medications, herbs and alcohol","teach":["If a nursing mother needs a medication, the safest time to take it is usually right after the baby nurses, at the lowest dose that works. Herbs can matter too. Large doses of St. John's wort may lower prolactin, the hormone that drives milk production, and so reduce milk supply.","Alcohol passes into milk. If a nursing mother drinks, the Institute of Medicine advises no more than 0.5 g of alcohol per kg of her body weight per day. Alcohol doesn't help babies sleep; babies actually sleep less after milk with alcohol. Pumping right after drinking doesn't speed up clearance. The safer plan is to pump before going out and use that milk until the alcohol has cleared."],"act":{"type":"number","prompt":"A nursing mother weighs 60 kg. Using 0.5 g of alcohol per kg, what is her daily limit in grams of alcohol?","answer":30,"tolerance":0,"unit":"g","explanation":"60 × 0.5 = 30 g of alcohol, which is about two cans of beer."}},{"id":"l4-b7","chapter":"Newborn jaundice","title":"Newborn jaundice","teach":["Jaundice is yellowing of the skin from too much bilirubin in the blood. At least 40% of healthy full-term babies and 80% of preterm babies become visibly jaundiced. Bilirubin comes from the breakdown of red blood cells. Newborns break down a lot of extra red blood cells after birth, and their young livers can't clear bilirubin quickly.","It is usually harmless and goes away on its own, but very high levels need treatment. Feeding often helps the baby pass bilirubin in stool."],"act":{"type":"choice","prompt":"What causes high bilirubin in newborns?","options":[{"label":"Breakdown of red blood cells","correct":true,"feedback":"Yes. Newborns break down many red blood cells after birth, and their livers can't keep up."},{"label":"High maternal vitamin A intake","correct":false,"feedback":"Bilirubin comes from red blood cell breakdown, not vitamin A."},{"label":"A labour lasting over 12 hours","correct":false,"feedback":"Length of labour isn't the cause."}]}}],"flashcards":[{"front":"Hormones behind breast development at puberty","back":"The cyclic release of estrogen and progesterone."},{"front":"Functional units of the mammary gland","back":"The alveoli."},{"front":"Largest components of breast milk","back":"Water first, then nutrients such as lactose and fat."},{"front":"Main carbohydrate in breast milk","back":"Lactose."},{"front":"Protein that forms a soft curd","back":"Whey."},{"front":"Foremilk vs. hindmilk","back":"Foremilk at the start of a feed is lower in fat. Hindmilk at the end is higher in fat."},{"front":"Energy in preterm milk","back":"58–70 kcal per 100 mL."},{"front":"Why newborns get vitamin K","back":"To prevent bleeding from poor blood clotting."},{"front":"Fluids while breastfeeding","back":"Drink to thirst. Aim for pale yellow urine."},{"front":"Safest time to take a medication","back":"Right after the baby nurses."},{"front":"Alcohol limit while breastfeeding","back":"No more than 0.5 g per kg of body weight per day."},{"front":"St. John's wort and breastfeeding","back":"Large doses may lower prolactin and reduce milk supply."},{"front":"Smacking or clicking while nursing","back":"A sign of a poor latch, which can cause sore nipples."},{"front":"Mastitis","back":"Breast inflammation or infection. Keep nursing or pumping."},{"front":"Newborn jaundice","back":"Yellow skin from high bilirubin, which comes from red blood cell breakdown. At least 40% of term babies get it."}],"quiz":[{"q":"Which of the following is a nutritional benefit of breastfeeding?","o":["It provides optimal nutrition to the infant.","The balance of nutrients matches requirements needed for human growth.","Infants do not need additional fluids or water when breastfeeding.","The low protein content is easily tolerated.","All of the above are considered nutritional benefits."],"a":4,"e":"Checked answer, not from an official key. Less certain: each statement describes a benefit of breast milk, but the textbook doesn't list them together, so check this one against your graded result."},{"q":"The cyclic release of what 2 hormones governs pubertal breast development?","o":["Prolactin and oxytocin","Progesterone and estrogen","Prolactin and estrogen","Progesterone and oxytocin","Testosterone and progesterone"],"a":1,"e":"Checked answer, not from an official key. The textbook says the cyclic release of estrogen and progesterone governs pubertal breast development."},{"q":"The functional units of the mammary gland are the:","o":["lobules.","myoepithelial cells.","alveoli.","areolas.","secretory cells."],"a":2,"e":"Checked answer, not from an official key. The textbook names the alveoli."},{"q":"The major component of breast milk is _________________, while the second largest component is ____________________.","o":["water, lipids","lipids, water","protein, carbohydrate","carbohydrate, protein","protein, lipids"],"a":0,"e":"Checked answer, not from an official key. Water is the largest component. Of these choices, only water then lipids fits."},{"q":"The dominant carbohydrate in human milk is _________________.","o":["galactose","glucose","lactose","sucrose","maltose"],"a":2,"e":"Checked answer, not from an official key. The textbook says lactose is the dominant carbohydrate."},{"q":"What nutrient forms a soft, easily digestible curd in the baby’s stomach?","o":["Copper","Vitamin K","Whey","Casein","Iron"],"a":2,"e":"Checked answer, not from an official key. The textbook says whey protein forms a soft, easily digestible curd."},{"q":"A health care professional was asked by a nursing mom, “How many glasses of water should I drink a today?” What would be an appropriate recommendation?","o":["6-8 glasses","8-10 glasses",">10 glasses","Drink enough fluids to keep your urine pale yellow."],"a":3,"e":"Checked answer, not from an official key. The textbook advises drinking to thirst rather than a set number of glasses."},{"q":"Use the following information for questions 8-10:\n\nA young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nWhat would the best advice be for this woman?","o":["Allow your baby to nurse on one breast only until it is completely empty.","Allow us to evaluate you while you are nursing your baby and see what you are doing.","Stop nursing immediately and use an infant formula so your baby starts growing.","Use supplemental infant formula after each feeding because the baby is obviously not getting enough to eat.","a and b only"],"a":4,"e":"Checked answer, not from an official key. Less certain: emptying one breast gives the baby more hindmilk, and watching a feed checks the latch. Stopping breastfeeding isn't called for. Check this one against your graded result."},{"q":"A young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nWhat is likely happening to this baby and causing the diarrhea?","o":["The baby is not latched on properly.","The mother is not producing enough breast milk.","The baby is getting too much foremilk and not enough hindmilk.","The baby has a poor suckle.","The baby is lactose intolerant."],"a":2,"e":"Checked answer, not from an official key. Switching breasts early gives lots of low-fat foremilk, which can cause gas, colic and loose stools."},{"q":"A young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nAfter looking at her diet, what changes could you suggest to help with the baby’s colic?","o":["Eliminate all fruit except canned fruit","Eliminate nuts","Eliminate dairy products","All of the above","b and c only"],"a":4,"e":"Checked answer, not from an official key. Cow's milk, peanuts and tree nuts are among the foods linked to colic in the textbook. There's no reason to cut fruit."},{"q":"Continuing to nurse while you are sick actually protects your baby because:","o":["you do not pass germs through breast milk.","your breast milk is full of antibodies that are passed on to your baby.","you do not contaminate bottles by handling them.","infant formulas are higher in vitamins and minerals and help boost the baby’s immune system."],"a":1,"e":"Checked answer, not from an official key. The mother makes antibodies to the germs around her and passes them on in her milk."},{"q":"A baby that is not given vitamin K at birth may have:","o":["excessive bleeding due to a lack of blood clotting.","decreased calcium absorption.","increased incidence of colic.","increased incidence of diarrhea","All of the above"],"a":0,"e":"Checked answer, not from an official key. Vitamin K is needed for clotting. Without it, babies are at risk of vitamin K deficiency bleeding."},{"q":"Which of the following would NOT be considered a common condition that is experienced by a woman who is breastfeeding?","o":["Sore nipples","Engorgement","Mastitis","Plugged ducts","All of the above are common problems."],"a":4,"e":"Checked answer, not from an official key. The textbook covers all four as common problems in breastfeeding."},{"q":"When is the safest time for a nursing mom to take a drug?","o":["In the morning","After eating a meal","After the infant nurses","Any time is safe to take a drug.","It is never safe for a nursing mom to take drugs."],"a":2,"e":"Checked answer, not from an official key. The textbook says the safest time is usually right after the baby nurses."},{"q":"If a 110-lb nursing woman (50 kg) wants to drink alcohol, how many cans of beer (15 g alcohol/12 oz) can this woman drink and stay within the Institute of Medicine’s alcohol recommendations?","o":["0","1","2","3"],"a":1,"e":"Checked answer, not from an official key. 50 kg × 0.5 g = 25 g of alcohol. One can is 15 g, and two would be 30 g, which is over the limit."},{"q":"Approximately _____ of term infants will become visibly jaundiced with their serum bilirubin levels exceeding 5 to 7 mg/dL.","o":["20%","30%","40%","50%","60%"],"a":2,"e":"Checked answer, not from an official key. The textbook says at least 40% of healthy full-term babies."},{"q":"Hyperbilirubinemia in newborns is caused by ________________________________.","o":["destruction of red blood cells","high blood lipid levels","high maternal intake of vitamin A","labor lasting over 12 hours"],"a":0,"e":"Checked answer, not from an official key. Bilirubin comes from the breakdown of red blood cells."},{"q":"The energy content of breast milk in women who deliver pre-term infants is ___________________.","o":["30-37 kcal/100 mL","40-48 kcal/100 mL","58-70 kcal/100 mL","72-120 kcal/100 mL"],"a":2,"e":"Checked answer, not from an official key. The textbook gives 58–70 kcal per 100 mL."},{"q":"A new mother goes to the mall shopping with her friends. She is gone longer than planned and is not able to nurse her baby until she returns 6 hours later. What is the most likely problem she will have?","o":["A breast infection","Engorgement","Plugged ducts","Sore nipples","Mastitis"],"a":1,"e":"Checked answer, not from an official key. Going hours without emptying the breasts leads to engorgement."},{"q":"A lactation consultant is observing a new mom breastfeeding and notices that the baby is making smacking and clicking sounds as she sucks. This tells her that:","o":["the baby is eating well and has a strong suckle.","the baby has a cleft palate and should be closely followed.","the baby is not latched on correctly and this may increase the risk of sore nipples.","this is just a noisy baby.","Noise is not an indicator of anything."],"a":2,"e":"Checked answer, not from an official key. The textbook says you should hear swallowing, not smacking or clicking."},{"q":"Large doses of St. John’s wort decrease prolactin levels in women. This could potentially:","o":["reduce oxytocin levels.","cause breast milk to taste like maple syrup.","cause a woman to become constipated.","reduce breast milk supply.","cause depression in some women."],"a":3,"e":"Checked answer, not from an official key. Prolactin drives milk production, so lowering it can reduce supply."},{"q":"Your best friend had a baby 3 months ago and is anxious to go “out on the town” with her friends. She is still breastfeeding, but would like to be able to have some drinks. What advice would you give her?","o":["It is okay to drink while nursing because it actually helps babies sleep.","It is okay to drink while nursing because it increases breast milk production.","Pump your milk immediately after drinking and it will be eliminated from your body.","Pump milk before going out and use that until the alcohol has been cleared from your system.","Drink only beer because babies tolerate it."],"a":3,"e":"Checked answer, not from an official key. The textbook suggests nursing or pumping before drinking and using that milk until the alcohol has cleared."},{"q":"You are at a nice restaurant and would like to order seafood for dinner; however, you are breastfeeding. Which of the following would have the lowest amount of mercury and be safest for you to eat?","o":["Calamari","Swordfish","Shark","Tuna","King mackerel"],"a":0,"e":"Checked answer, not from an official key. Less certain: swordfish, shark and king mackerel are high in mercury and tuna is moderate, so calamari (squid) is the low-mercury choice, but the textbook doesn't name calamari. Check this one against your graded result."},{"q":"Which of the following foods would a pediatrician recommend a nursing mother with no history of food allergies in the family restrict?","o":["Peanuts and tree nuts","Wheat","Soy","Eggs","None of the above"],"a":4,"e":"Checked answer, not from an official key. Less certain: the textbook advises cutting out only foods that seem to cause problems, so with no family history, no restriction is needed. Check this one against your graded result."},{"q":"A woman with mastitis should continue to nurse her baby.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Emptying the breast by nursing or pumping helps clear mastitis."}]},{"n":5,"title":"Infant Nutrition","kicker":"Lesson 5 of your course, built from Chapters 8 and 9 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l5-b1","chapter":"How babies develop","title":"How babies develop","teach":["Babies gain control of their muscles in a set order: from the head downward, and from the centre of the body out to the hands and fingers. They hold up their heads before they sit, and use their arms before they pick things up with their fingers. Newborns are born with feeding reflexes such as rooting: stroke a baby's cheek and they turn toward it and open their mouth.","In the first two years, babies learn through their senses and movements. This is called the sensorimotor stage. Feeding skills follow development: sitting with support, moving the head toward a spoon, then picking up finger foods. Readiness, not just age, should guide when new textures are offered."],"act":{"type":"choice","prompt":"Which statement describes how muscle control develops in infants?","options":[{"label":"From the head downward, and from the centre of the body out to the hands","correct":true,"feedback":"Yes. Head control comes first, and fine finger control comes last."},{"label":"From the toes upward","correct":false,"feedback":"It's the other way around: head first, legs later."},{"label":"From the fingers inward","correct":false,"feedback":"The central muscles come first, and the hands and fingers later."}]}},{"id":"l5-b2","chapter":"Energy and nutrient needs","title":"Energy and nutrient needs","teach":["Babies need a lot of energy for their size. In the first six months the average is 108 Calories per kg of body weight, based on the growth of breastfed babies. From 6 to 12 months it is 98 Calories per kg. Protein needs from 7 to 12 months are about 11 g a day.","Breast milk and standard formula both give about 20 Calories per ounce. Iron stores from birth last about four to six months. Exclusively breastfed babies are advised to get an iron supplement starting at four months (1 mg per kg per day) until they eat iron-rich foods. Meat is a good early food for iron and zinc."],"act":{"type":"number","prompt":"A 4-month-old baby weighs 7 kg. At 108 Calories per kg, how many Calories does she need each day?","answer":756,"tolerance":0,"unit":"Calories","explanation":"7 × 108 = 756 Calories a day."}},{"id":"l5-b3","chapter":"Formula feeding","title":"Formula feeding","teach":["Formula-fed babies should stay on formula for the first year. Routine formulas for full-term babies give 19–20 Calories per ounce when mixed as directed. Formulas for preterm babies after they leave the hospital usually give 22 or 24 Calories per ounce.","Many feeding troubles are blamed on allergies when they aren't. A baby with a suspected protein intolerance may be switched to a formula with hydrolyzed (broken-down) protein, which is less likely to trigger a reaction. These formulas cost more and taste stronger."],"act":{"type":"number","prompt":"A baby drinks 24 ounces of standard formula a day. At 20 Calories per ounce, how many Calories is that?","answer":480,"tolerance":0,"unit":"Calories","explanation":"24 × 20 = 480 Calories."}},{"id":"l5-b4","chapter":"Growth charts and size at birth","title":"Growth charts and size at birth","teach":["Growth charts show how a baby's weight, length and head size compare with other babies of the same age and sex. A baby between the 10th and 90th percentiles at birth is appropriate for gestational age (AGA). Below the 10th is small for gestational age (SGA), and above the 90th is large (LGA).","One measurement is a snapshot. What matters most is the pattern over time, and whether the baby keeps following their own curve."],"act":{"type":"sort","prompt":"Sort each newborn by size for gestational age.","categories":["SGA (below 10th)","AGA (10th–90th)","LGA (above 90th)"],"items":[{"label":"Birthweight at the 5th percentile","category":0,"feedback":"Below the 10th percentile is small for gestational age."},{"label":"Birthweight at the 50th percentile","category":1,"feedback":"This is right in the middle, so appropriate for gestational age."},{"label":"Birthweight at the 75th percentile","category":1,"feedback":"Still between the 10th and 90th, so AGA."},{"label":"Birthweight at the 95th percentile","category":2,"feedback":"Above the 90th percentile is large for gestational age."}]}},{"id":"l5-b5","chapter":"Newborn screening and inborn errors","title":"Newborn screening and inborn errors","teach":["Newborns are screened shortly after birth for metabolic disorders, most often PKU, congenital hypothyroidism, galactosemia and sickle cell disease. Finding these early lets treatment start before damage occurs. Food allergies can't be picked up by newborn screening.","Babies with galactosemia can't break down galactose, which is part of lactose (milk sugar). They can't have breast milk or regular milk-based formula. Soy formula, which has no lactose, is used instead. Babies with PKU need a special formula low in phenylalanine."],"act":{"type":"choice","prompt":"Which feeding is NOT safe for a baby with galactosemia?","options":[{"label":"Soy formula","correct":false,"feedback":"Soy formula has no lactose, so it's used for galactosemia."},{"label":"Breast milk","correct":true,"feedback":"Right. Breast milk is rich in lactose, which contains galactose."},{"label":"Apple juice","correct":false,"feedback":"Apple juice has no galactose."}]}},{"id":"l5-b6","chapter":"Vegetarian and vegan babies","title":"Vegetarian and vegan babies","teach":["A well-planned vegetarian diet can meet a baby's needs, but some nutrients need attention. Iron, vitamin B12, vitamin D, calcium and zinc are the main ones, especially in vegan diets. Fortified soy formula, iron-fortified cereals, beans and lentils, and a B12 source all help.","Check the diet against the baby's needs: about 98 Calories per kg from 6 to 12 months, and about 11 g of protein a day."],"act":{"type":"number","prompt":"A 10-month-old weighs 9 kg. At 98 Calories per kg, how many Calories does he need each day?","answer":882,"tolerance":0,"unit":"Calories","explanation":"9 × 98 = 882 Calories a day."}},{"id":"l5-b7","chapter":"Preterm babies and special needs","title":"Preterm babies and special needs","teach":["For preterm babies, use the corrected age: subtract the weeks born early from the age since birth. A baby born at 32 weeks is 8 weeks (about 2 months) early. At 9 months old, that baby's corrected age is about 7 months, and development should be judged on that. Preterm babies often can't suck, swallow and breathe in rhythm until 32–34 weeks, so they may need gavage feeding: a tube from the mouth or nose into the stomach.","Preterm babies need more energy, about 105–130 Calories per kg. Babies with bronchopulmonary dysplasia (BPD), a lung condition, grow more slowly because of higher nutrient needs and changes in their hormone and lung systems. Some babies need fewer Calories than usual, such as babies with Down syndrome, who tend to be less active and have lower energy needs."],"act":{"type":"number","prompt":"A baby born at 28 weeks (12 weeks early) is now 6 months old. What is the corrected age in months? (Use 4 weeks = 1 month.)","answer":3,"tolerance":0,"unit":"months","explanation":"12 weeks early is 3 months. 6 − 3 = 3 months corrected age."}}],"flashcards":[{"front":"Order of muscle control in infants","back":"From the head downward, and from the centre of the body out to the hands."},{"front":"Rooting reflex","back":"Stroke the cheek and the baby turns toward it and opens the mouth."},{"front":"Energy needs, 0–6 months","back":"About 108 Calories per kg per day."},{"front":"Energy needs, 6–12 months","back":"About 98 Calories per kg per day."},{"front":"Protein, 7–12 months","back":"About 11 g a day."},{"front":"Calories in standard formula or breast milk","back":"About 20 per ounce."},{"front":"Formula for preterm babies after discharge","back":"Usually 22 or 24 Calories per ounce."},{"front":"Suspected protein intolerance","back":"Switch to a formula with hydrolyzed (broken-down) protein."},{"front":"AGA","back":"Appropriate for gestational age: birthweight between the 10th and 90th percentiles."},{"front":"Newborn screening","back":"Commonly PKU, hypothyroidism, galactosemia and sickle cell disease. Not food allergies."},{"front":"Galactosemia","back":"Can't break down galactose. No breast milk or milk-based formula. Soy formula is used."},{"front":"Nutrients of concern for vegan babies","back":"Iron, vitamin B12, vitamin D, calcium and zinc."},{"front":"Corrected age","back":"Age since birth minus the weeks born early."},{"front":"Gavage feeding","back":"A tube from the mouth or nose into the stomach."},{"front":"Bronchopulmonary dysplasia (BPD)","back":"A lung condition. Slower growth from higher needs and hormone and lung changes."},{"front":"Lower energy needs","back":"Babies with Down syndrome often need fewer Calories."}],"quiz":[{"q":"Which of the following statements best describes motor development in infants?","o":["Voluntary control of muscles starts from the head and moves down to the legs.","Voluntary control of muscles starts from being able to fan toes out at birth to blinking eyes in response to a loud noise or light.","Voluntary muscle control develops with central muscles first and then moves out to hand muscles.","Voluntary muscle control develops with rooting reflex and then moves out to hand muscles.","a and c"],"a":4,"e":"Checked answer, not from an official key. Muscle control develops from the head down and from the centre out."},{"q":"An example of sensorimotor development is _______________________________________.","o":["thumb sucking","crying when hungry","blinking eyes in response to bright light","ability to sleep through the night","an increase in head circumference"],"a":2,"e":"Checked answer, not from an official key. Less certain: sensorimotor development is about responding to the senses with movement, and blinking at bright light is the clearest example here. Thumb sucking could also be argued, so check this one against your graded result."},{"q":"The AVERAGE caloric need of infants in the first six months of life is ________________ per kg of body weight, based on growth in breast-fed infants.","o":["57 Calories","98 Calories","108 Calories","122 Calories","154 Calories"],"a":2,"e":"Checked answer, not from an official key. The textbook gives 108 Calories per kg for the first six months."},{"q":"Based on your answer to question #3, a 5-month-old infant would require approximately _____ total Calories per day based on a weight of 6 kg.","o":["648","732","924","1037","1251"],"a":0,"e":"Checked answer, not from an official key. 6 × 108 = 648."},{"q":"A 3-month-old infant was taking 30 ounces/day of a standard formula. How many Calories did the infant consume each day?","o":["600","300","450","510"],"a":0,"e":"Checked answer, not from an official key. Standard formula gives about 20 Calories an ounce. 30 × 20 = 600."},{"q":"Based on your answer to #6, this baby is: (Question 6 asks you to plot an 8-pound newborn girl on the growth chart in your test.)","o":["small for gestational age (SGA).","large for gestational age (LGA).","appropriate for gestational age (AGA).","None of the above"],"a":2,"e":"Checked answer, not from an official key. An 8-pound newborn girl falls between the 10th and 90th percentiles, so she is appropriate for gestational age."},{"q":"Which of the following conditions CANNOT be screened for shortly after birth?","o":["PKU","Food allergy","Galactosemia","Sickle-cell disease","Hypothyroidism"],"a":1,"e":"Checked answer, not from an official key. Newborns are screened for PKU, hypothyroidism, galactosemia and sickle cell disease, but not food allergies."},{"q":"An infant with a suspected protein intolerance may be:","o":["put on a soy formula because plant proteins are well tolerated.","put on a hydrolyzed formula because the protein is broken down.","breast fed only because breast milk is the gold standard to feed babies","put on IV fluids with a fat replacement."],"a":1,"e":"Checked answer, not from an official key. The textbook says these babies may be switched to a hydrolyzed protein formula."},{"q":"Use the following information to answer questions 10-12.\n\nThe mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nNutrients of concern in this diet include:","o":["calcium","vitamin B12","vitamin D","Iron","All of the above"],"a":4,"e":"Checked answer, not from an official key. With only 8 oz of soy formula and no other B12, calcium or vitamin D sources, all four are a concern."},{"q":"The mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nDoes this diet have an adequate amount of calories for a 9-month-old infant?","o":["Yes","No"],"a":1,"e":"Checked answer, not from an official key. 8.6 kg × 98 = about 843 Calories needed. 750 is short."},{"q":"The mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nDoes this diet have an adequate amount of protein for a 9-month-old infant?","o":["Yes","No"],"a":0,"e":"Checked answer, not from an official key. Babies 7–12 months need about 11 g of protein a day, and he gets 21 g."},{"q":"An infant with what special condition requires less energy than a healthy infant?","o":["Extremely low-birth-weight infant","Low-birth-weight infant","Infant with Down’s syndrome","Infant born with difficulty breathing","Infant born with PKU"],"a":2,"e":"Checked answer, not from an official key. The textbook lists babies with lower activity and slower growth, including Down syndrome, as needing fewer Calories. Preterm and lung conditions raise needs."},{"q":"What is the gestation-adjusted age for a 9-month-old infant born preterm (32 weeks)?","o":["6.5 months","7 months","8 months","8.5 months"],"a":1,"e":"Checked answer, not from an official key. Born 8 weeks (2 months) early, so 9 − 2 = 7 months."},{"q":"Which of the following foods would NOT be appropriate for a baby with galactosemia?","o":["Sugar solution","Apple juice","Soybean formula","Breast milk"],"a":3,"e":"Checked answer, not from an official key. Breast milk is rich in lactose, which contains galactose."},{"q":"Growth rates among infants that have the lung condition bronchopulmonary dysplasia (BPD) are slower due to all of the following EXCEPT:","o":["higher nutritional requirements.","more muscle mass.","changes in endocrine systems.","changes in pulmonary systems.","All of the above are reasons that these infants have slower growth rates."],"a":1,"e":"Checked answer, not from an official key. The textbook lists higher needs and changes in the endocrine and lung systems, not muscle mass."},{"q":"A gavage feeding is one that:","o":["provides nutrition directly through the central vein and includes amino acids, dextrose, and a lipid emulsion.","provides nutrition through a tube inserted into the stomach or small intestine.","provides slow feedings from the mouth or nose into the stomach through a tube.","provides oral nutrition that has been pureed thoroughly so the infant does not choke.","provides nutrition through the use of an oral syringe."],"a":2,"e":"Checked answer, not from an official key. The textbook describes gavage feeding as a tube from the mouth or nose to the stomach."},{"q":"Please read the case study below and use the information to answer questions 18-20.\n\nCase Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nWhat daily weight gain goal would the dietitian set for the first three months?","o":["10-25g/day","20-30 g/day","30-40 g/day",">40 g/day"],"a":1,"e":"Checked answer, not from an official key. Less certain: 20–30 g a day is a common goal for preterm babies after discharge, but the textbook text doesn't give the figure directly, so check this one against your graded result."},{"q":"Case Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nFollowing discharge from the hospital, Rebecca showed signs of fatigue during feeding. The dietitian then recommended a higher-calorie formula. How many Calories/ounce would the new formula most likely contain?","o":["40 Calories","24 Calories","30 Calories","35 Calories"],"a":1,"e":"Checked answer, not from an official key. Post-discharge formulas usually give 22 or 24 Calories an ounce, so the next step up is 24."},{"q":"Case Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nWill Rebecca be able to sit in a high chair and maintain a stable feeding position at 6 months — the same physical development expected from a term infant?","o":["Yes","No"],"a":1,"e":"Checked answer, not from an official key. Born 2 months early, at 6 months her corrected age is about 4 months, so she likely won't be ready yet."}]},{"n":6,"title":"Toddler and Preschooler Nutrition","kicker":"Lesson 6 of your course, built from Chapters 10 and 11 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l6-b1","chapter":"Slower growth, smaller appetite","title":"Slower growth, smaller appetite","teach":["Growth slows down after the first year. Toddlers gain about 8 oz and 1 cm a month, and preschoolers gain about 4.4 lb (2 kg) and 7 cm a year. Appetite drops along with growth, and many parents worry their child isn't eating enough. A smaller appetite is a normal part of growing up at this age.","Growth charts and BMI-for-age help show whether a child is growing well. For children, BMI is compared with percentiles for age and sex rather than adult cut-offs."],"act":{"type":"number","prompt":"A 4-year-old weighs 18 kg and is 1.05 m tall. What is her BMI? (Round to one decimal.)","answer":16.3,"tolerance":0.1,"unit":"kg/m²","explanation":"1.05 × 1.05 = 1.1025. 18 ÷ 1.1025 = 16.3. For children, you then compare this with BMI-for-age percentiles."}},{"id":"l6-b2","chapter":"Feeding young children","title":"Feeding young children","teach":["A handy portion guide for toddlers is 1 tablespoon of each food per year of age. Parents decide what, when and where food is offered, and children decide how much to eat. Keep distractions like TV to a minimum and let toddlers practise feeding themselves.","Children often need many tries before they accept a new food, so keep offering it calmly. Pressure and bribes backfire. Restricting a tasty food can make it more desirable and lead children to overeat it and feel bad about it. Using a food as a reward makes it even more prized."],"act":{"type":"choice","prompt":"A parent keeps cookies locked away and only gives them as a reward. What is the likely effect?","options":[{"label":"The child loses interest in cookies.","correct":false,"feedback":"Studies show restriction and rewards make a food more desirable, not less."},{"label":"Cookies become more desirable, and the child may overeat them when they get the chance.","correct":true,"feedback":"Yes. Restricting a tasty food tends to increase the desire for it."},{"label":"No effect on how the child sees cookies.","correct":false,"feedback":"How foods are offered does shape children's preferences."}]}},{"id":"l6-b3","chapter":"Nutrient needs","title":"Nutrient needs","teach":["Fat is important for young children's growth. The acceptable range is 30–40% of Calories for ages 1–3 and 25–35% for ages 4–18. The RDA for iron is 7 mg a day for ages 1–3 and 10 mg for ages 4–8. A simple fibre guide is the child's age plus 5 g a day, so 10 g for a 5-year-old. Age plus 15 g or more may be too much bulk for a small appetite.","Most young children get plenty of most nutrients, but iron, vitamin D and calcium are often low. More than 24 oz of milk a day can crowd out iron-rich foods. Too much fruit juice, especially juice with sorbitol, is a common cause of diarrhea in healthy toddlers."],"act":{"type":"sort","prompt":"Match each guideline with the right number.","categories":["30–40% of Calories","10 mg a day","Age + 5 g a day"],"items":[{"label":"Fat for children aged 1–3","category":0,"feedback":"Young children need a higher share of fat than older children."},{"label":"Iron RDA for children aged 4–8","category":1,"feedback":"The RDA rises from 7 mg (ages 1–3) to 10 mg (ages 4–8)."},{"label":"Fibre for a young child","category":2,"feedback":"A 5-year-old would aim for about 10 g."}]}},{"id":"l6-b4","chapter":"Vegetarian toddlers","title":"Vegetarian toddlers","teach":["Toddlers on a vegetarian diet can grow well with some planning. Offer three meals and two to three snacks a day. Include energy-dense foods such as cheese, avocado, nut butters and oils, because small stomachs fill up fast.","Avoid bran and too many bulky foods like raw fruit and vegetables, which fill children up without enough Calories. Make sure there is a good source of vitamin B12, or a supplement if needed."],"act":{"type":"choice","prompt":"Which of these is NOT good advice for a vegetarian toddler?","options":[{"label":"Serve bran muffins with fruit and vegetables.","correct":true,"feedback":"Right. Bran is bulky and low in energy, so it should be avoided at this age."},{"label":"Include cheese or avocado.","correct":false,"feedback":"These are good energy-dense choices."},{"label":"Make sure there's a source of vitamin B12.","correct":false,"feedback":"B12 is important, especially in vegan diets."}]}},{"id":"l6-b5","chapter":"Common nutrition problems","title":"Common nutrition problems","teach":["Iron-deficiency anemia, tooth decay and constipation are common in young children. Lead poisoning is less common but serious. Some children are at higher risk of nutrient deficiencies: those who are abused or neglected, those with failure to thrive, those on vegan diets without dairy or fortified foods, and those on restrictive weight-management plans. Children who eat a variety of basic foods are at low risk.","Failure to thrive means poor growth, and it often comes from a mix of medical and family factors. A diet that leans on juice and plain starches, with little variety, is a sign of a feeding problem."],"act":{"type":"choice","prompt":"A 3-year-old drinks about 40 oz of juice a day and eats mostly plain pasta, bread and crackers. What points to a feeding problem?","options":[{"label":"Lack of variety","correct":false,"feedback":"Yes, but that's not all."},{"label":"Too much fluid","correct":false,"feedback":"Yes, but there's more."},{"label":"Lack of variety, bland choices and too much fluid","correct":true,"feedback":"Right. All three are warning signs."}]}},{"id":"l6-b6","chapter":"Children with special health needs","title":"Children with special health needs","teach":["Up to 90% of children with disabilities have some kind of nutrition problem. Needs depend on the condition. A child with Down syndrome is at risk of gaining too much weight if food intake doesn't match their energy needs. A child with cerebral palsy who uses a wheelchair needs less energy than one who walks.","Rett syndrome is a rare genetic disorder on the X chromosome, almost always in girls, with severe neurological delays and slowed head growth. Children with autism may refuse foods they don't like, insist on certain foods or drinks, and have tantrums at meals."],"act":{"type":"choice","prompt":"Who needs less energy?","options":[{"label":"A child with cerebral palsy who uses a wheelchair","correct":true,"feedback":"Yes. Less movement means lower energy needs."},{"label":"A child with cerebral palsy who walks","correct":false,"feedback":"Walking takes more energy, especially with muscle-control problems."},{"label":"Both need the same","correct":false,"feedback":"Activity level makes a real difference."}]}},{"id":"l6-b7","chapter":"Celiac disease, sickle cell disease and asthma","title":"Celiac disease, sickle cell disease and asthma","teach":["Celiac disease is an immune reaction to gluten, found in wheat, rye and barley. These grains must be removed from the diet for life. Children with sickle cell disease who get blood transfusions also receive iron from them, so iron-rich foods may need to be limited rather than encouraged.","Asthma itself doesn't need nutrition treatment, but some children with asthma also have food allergies, and food allergies can trigger asthma. Families sometimes cut out dairy because they believe milk increases mucus, which isn't supported and can leave children short of calcium."],"act":{"type":"choice","prompt":"Which grains must be removed for celiac disease?","options":[{"label":"Wheat, rye and barley","correct":true,"feedback":"Yes. These contain gluten."},{"label":"Wheat, rice and soy","correct":false,"feedback":"Rice and soy are gluten-free."},{"label":"Rice, corn and eggs","correct":false,"feedback":"None of these contain gluten."}]}}],"flashcards":[{"front":"Growth of preschoolers","back":"About 4.4 lb (2 kg) and 7 cm a year."},{"front":"Portion rule of thumb for toddlers","back":"1 tablespoon of each food per year of age."},{"front":"Restricting a tasty food","back":"Makes it more desirable and can lead to overeating it."},{"front":"Fat AMDR, ages 1–3","back":"30–40% of Calories."},{"front":"Fat AMDR, ages 4–18","back":"25–35% of Calories."},{"front":"Iron RDA, ages 4–8","back":"10 mg a day."},{"front":"Fibre for young children","back":"Age plus 5 g a day."},{"front":"Nutrients often low in young children","back":"Iron, vitamin D and calcium."},{"front":"Common cause of diarrhea in healthy toddlers","back":"Too much fruit juice."},{"front":"Vegetarian toddlers: what to avoid","back":"Bran and too many bulky foods."},{"front":"Children with disabilities and nutrition problems","back":"Up to 90% have some kind of nutrition problem."},{"front":"Rett syndrome","back":"A rare genetic change on the X chromosome causing severe neurological delays, mostly in girls."},{"front":"Cerebral palsy and energy","back":"A child who uses a wheelchair needs less energy than one who walks."},{"front":"Celiac disease","back":"Remove gluten: wheat, rye and barley."},{"front":"Sickle cell disease with transfusions","back":"Transfusions add iron, so iron-rich foods may need limiting."}],"quiz":[{"q":"On average, toddlers gain 8 oz/month and preschoolers gain _____ lb/year.","o":["4.4","6.2","8.3","10.5"],"a":0,"e":"Checked answer, not from an official key. The textbook says preschoolers gain about 4.4 lb a year."},{"q":"One “rule of thumb” regarding portion sizes for toddlers is:","o":["Serve them as you would serve yourself and let them decide how much they would like to eat.","1 tablespoon of food per year of age.","Allow toddlers to self serve and graze throughout the day as there are no actual portion sizes for this age group.","1/4 cup of protein-type foods and ½ cup of all others.","None of the above is correct."],"a":1,"e":"Checked answer, not from an official key. A common guide is 1 tablespoon of each food per year of age."},{"q":"Studies have shown that restricting a young child’s access to palatable food may:","o":["promote desirability of that particular food.","increase disinterest in new foods.","encourage them to overeat these foods and have negative feelings.","All of the above","a and c only"],"a":4,"e":"Checked answer, not from an official key. The textbook says restriction makes a food more desirable, and girls whose parents restricted snacks ate more of them and felt bad about it."},{"q":"Approximately how many exposures to a new food might it take for a toddler to accept the flavor or taste?","o":["1-2","5-7","8-10",">15"],"a":2,"e":"Checked answer, not from an official key. Less certain: the textbook stresses repeated exposure, and 8–10 tries is the common figure, but the chapter text doesn't give a number. Check this one against your graded result."},{"q":"The Acceptable Macronutrient Distribution Ranges (AMDRs) for fat are _____ for children 1 to 3 years and _____________________ for children 4 to 18 years old.","o":["20-30%, <30%","20-30%, 25-35%","30-40%, <30%","30-40%, 25-35%","It is the same for both age groups at <30%."],"a":3,"e":"Checked answer, not from an official key. The textbook gives 30–40% for ages 1–3 and 25–35% for ages 4–18."},{"q":"The RDA for iron for children ages 4-8 years is __________________.","o":["<5 mg/day","8 mg/day","10 mg/day","18 mg/day","29 mg/day"],"a":2,"e":"Checked answer, not from an official key. The RDA for ages 4–8 is 10 mg a day."},{"q":"The general fiber recommendation for 5-year-old children is _____/day.","o":["5 g","7 g","10 g","25 g","35-50 g"],"a":2,"e":"Checked answer, not from an official key. Age plus 5 g: 5 + 5 = 10 g."},{"q":"Use the following information for questions 8 & 9:\n\nA 5-year-old boy is brought in for a nutrition assessment and health check. He weighs 50 lb (22.7 kg), and is 45 in (114 cm) tall.\n\nBased on the above information, this boy has a BMI of:","o":["13.1","15.2","17.4","19.6","21.8"],"a":2,"e":"Checked answer, not from an official key. 22.7 ÷ (1.14 × 1.14) = 22.7 ÷ 1.30 = 17.4."},{"q":"A 5-year-old boy is brought in for a nutrition assessment and health check. He weighs 50 lb (22.7 kg), and is 45 in (114 cm) tall.\n\nWhat does this boy’s BMI mean?","o":["He is underweight.","He is normal weight.","He is at risk of overweight.","He is overweight.","He is obese."],"a":2,"e":"Checked answer, not from an official key. Less certain: a BMI of 17.4 for a 5-year-old boy falls between the 85th and 95th percentiles on the growth chart, which this test calls “at risk of overweight”. Check this one against your graded result."},{"q":"In general, children ages 1-5 tend to consume more than enough of most nutrients in their diets EXCEPT ___________________________________.","o":["calcium and zinc","fat and carbohydrate","vitamin C and iron","vitamin A and fluoride","iron and vitamin D"],"a":4,"e":"Checked answer, not from an official key. Iron and vitamin D are often low in young children's diets."},{"q":"A decrease in appetite is a normal part of growth and development for toddlers and preschool age children.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. The textbook says parents can be reassured this is normal."},{"q":"Which of the following children would NOT be at risk for a nutrient deficiency?","o":["Children suffering from abuse or neglect","Children who consume a vegetarian diet without dairy products","Children with failure to thrive","Children who participate in a dietary program for managing obesity","Children who consume a variety of basic foods"],"a":4,"e":"Checked answer, not from an official key. Eating a variety of basic foods is protective."},{"q":"Which of the following nutrition problems is the LEAST common among young children?","o":["Iron-deficiency anemia","Dental caries","Constipation","Lead poisoning"],"a":3,"e":"Checked answer, not from an official key. Less certain: anemia, tooth decay and constipation are common, and lead poisoning is the least common of these, but the textbook doesn't rank them directly. Check this one against your graded result."},{"q":"Recommendations for toddlers whose parents are vegetarian include all of the following EXCEPT:","o":["Encourage toddlers to eat bran muffins when serving fruits and vegetables.","Include cheese or avocados in toddlers’ diets.","Encourage toddlers to eat two to three snacks.","Include good sources of vitamin B12 in toddler’s diets or supplement, if required."],"a":0,"e":"Checked answer, not from an official key. The textbook says to avoid serving bran and too many bulky foods."},{"q":"It is estimated that up to _____ of children with disabilities have some type of nutritional problem.","o":["25%","45%","55%","75%","90%"],"a":4,"e":"Checked answer, not from an official key. The textbook says up to 90%."},{"q":"A child who has Down syndrome would have a poorer health outcome associated with","o":["skipping one meal.","offering meals in the school foodservice cafeteria on days when he is not attending.","reviewing his individualized education plan three weeks late.","mismatching his energy needs with food intake, thus leading to excessive weight gain."],"a":3,"e":"Checked answer, not from an official key. Children with Down syndrome often have lower energy needs, so too much food leads to excess weight gain."},{"q":"Rett syndrome is a rare disorder characterized by:","o":["damage that occurs to underdeveloped lungs resulting in breathing that requires extra effort.","a genetic change on the X chromosome resulting in severe neurological delays","damage to the part of the brain controlling movement of the legs, interfering with muscle control and ambulation.","damage to chromosome 7 that interferes with all the exocrine functions in the body.","destruction of the infection-fighting abilities of the body by a virus."],"a":1,"e":"Checked answer, not from an official key. Rett syndrome is a genetic change on the X chromosome, mostly in girls."},{"q":"Characteristics of food choices by an autistic child might include all of the following EXCEPT:","o":["preferring to eat solid foods rather than drink liquids.","refusing to eat when offered something he/she does not like.","having temper tantrums in which he/she can be injured.","preferring one type of drink above others.","All of the above ARE characteristics of food choices."],"a":0,"e":"Checked answer, not from an official key. Less certain: food refusal, tantrums and strong drink preferences are typical, while preferring solids over liquids isn't a recognized pattern, but the textbook text doesn't settle this. Check this one against your graded result."},{"q":"Healthy toddlers are likely to develop diarrhea from _____.","o":["introduction of vegetables into their diet","addition of too much fat into their diet","consumption of eggs","drinking too much fruit juice","drinking 2% milk versus whole milk"],"a":3,"e":"Checked answer, not from an official key. The textbook links diarrhea to too much juice, especially with sorbitol."},{"q":"Dietary management of celiac disease requires the elimination of:","o":["wheat, rye, and barley.","wheat, rice, and soy.","wheat, rice, corn, and soy.","rice, corn, eggs, and bulgur.","fruits, vegetables, and nuts."],"a":0,"e":"Checked answer, not from an official key. These are the gluten-containing grains."},{"q":"Which food may not be appropriate to serve a child with sickle-cell disease also receiving a blood transfusion containing iron?","o":["Cereal with milk","Hamburger with tomatoes","Green beans and butter","Hostess snack cake","Potato chips"],"a":1,"e":"Checked answer, not from an official key. Transfusions add iron, so iron-rich foods like hamburger may not be needed."},{"q":"Use the following diet record to answer questions 22 & 23.\n\nBreakfast: Instant oatmeal sweetened with brown sugar Mashed banana 8 oz. fortified juice\nLunch: Macaroni with butter 8 oz. fortified juice\nSnack: Goldfish crackers 12 oz. fortified juice\nDinner: White bread without crusts and with butter 12 oz. fortified juice\n\nWhat would indicate that the 3-year-old girl following this diet has a potential feeding problem?","o":["Lack of variety","Bland food choices","Excessive fluid intake","All of the above","a and c only"],"a":3,"e":"Checked answer, not from an official key. Her diet has little variety, only bland foods and 40 oz of juice a day."},{"q":"Breakfast: Instant oatmeal sweetened with brown sugar Mashed banana 8 oz. fortified juice\nLunch: Macaroni with butter 8 oz. fortified juice\nSnack: Goldfish crackers 12 oz. fortified juice\nDinner: White bread without crusts and with butter 12 oz. fortified juice\n\nWhat foods could you suggest to increase variety and still make it easy for her to eat?","o":["Pureed pears or peaches","Macaroni made with milk and cheese","Peanut butter sandwich crackers","Fortified juice smoothie","All of the above"],"a":4,"e":"Checked answer, not from an official key. Each choice adds variety in a soft, familiar form."},{"q":"A child with cerebral palsy in a wheelchair will likely require _____ energy than/as a child with cerebral palsy that is able to walk.","o":["more","less","the same amount of"],"a":1,"e":"Checked answer, not from an official key. Less movement means lower energy needs."},{"q":"Some children have asthma as a result of food allergies.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Less certain: the textbook says some children with asthma also have food allergies, and food allergies can trigger asthma, but it doesn't say this in so many words. Check this one against your graded result."}]},{"n":7,"title":"Child and Preadolescent Nutrition","kicker":"Lesson 7 of your course, built from Chapters 12 and 13 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l7-b1","chapter":"Growth and BMI rebound","title":"Growth and BMI rebound","teach":["School-age children grow steadily until the growth spurt of adolescence. Body fat drops through the preschool years, reaches its lowest point and then starts to rise again, usually around age six. This normal rise is called BMI rebound or adiposity rebound, and you can see it on BMI-for-age charts.","An early BMI rebound, before age five, is linked to a higher risk of overweight and obesity later. Maternal obesity has been found to be the strongest predictor of childhood obesity, along with the home environment."],"act":{"type":"choice","prompt":"What is BMI rebound?","options":[{"label":"The normal rise in body fat after it reaches its lowest point in early childhood","correct":true,"feedback":"Yes. It usually happens around age six."},{"label":"Losing all baby fat at age six","correct":false,"feedback":"Body fat drops and then rises again. That rise is the rebound."},{"label":"Returning to a normal weight after a growth spurt","correct":false,"feedback":"It's about the normal pattern of body fat in childhood."}]}},{"id":"l7-b2","chapter":"Parents' feeding style","title":"Parents' feeding style","teach":["Parents shape a healthy food environment, but being too controlling backfires. When parents restrict food or pressure children to eat, children become less able to regulate how much they eat and are more likely to become overweight.","A responsive feeding style works better. Parents offer healthy food at regular times, eat together as a family and let children decide how much to eat. More activity and less screen time also help prevent overweight."],"act":{"type":"choice","prompt":"What tends to happen to children whose parents strictly control what and how much they eat?","options":[{"label":"They develop healthier habits.","correct":false,"feedback":"Strict control usually backfires."},{"label":"They're less able to regulate their intake and more likely to become overweight.","correct":true,"feedback":"Yes. Both effects are linked to controlling feeding."},{"label":"They have fewer eating problems.","correct":false,"feedback":"Controlling feeding is linked to more problems, not fewer."}]}},{"id":"l7-b3","chapter":"Nutrient needs of school-age children","title":"Nutrient needs of school-age children","teach":["School-age children (4–13) need about 0.95 g of protein per kg of body weight a day. The fat range for ages 4–18 is 25–35% of Calories. The Adequate Intake for fibre is 25 g a day for ages 4–8. Fresh fruit, vegetables and whole-grain breads are the best ways to add fibre.","To check a child's diet, multiply grams by Calories per gram (4 for protein and carbohydrate, 9 for fat), then compare the results with these ranges."],"act":{"type":"number","prompt":"A 10-year-old weighs 32 kg. At 0.95 g per kg, about how much protein does he need each day? (Round to the nearest gram.)","answer":30,"tolerance":1,"unit":"g","explanation":"32 × 0.95 = 30.4, so about 30 g a day."}},{"id":"l7-b4","chapter":"Teeth and school drinks","title":"Teeth and school drinks","teach":["Sticky, sugary foods like raisins and other dried fruit cling to teeth and are the most likely to cause cavities. Cheese, plain yogurt and peanut butter are much less likely to.","The American Academy of Pediatrics wants sweetened drinks out of schools, replaced with real fruit and vegetable juices, water, and low-fat white or flavoured milk. Sports drinks aren't on the list of replacements."],"act":{"type":"choice","prompt":"Which snack is most likely to promote cavities?","options":[{"label":"Cheddar cheese","correct":false,"feedback":"Cheese is unlikely to cause cavities and may even help protect teeth."},{"label":"Raisins","correct":true,"feedback":"Yes. Sticky, sugary dried fruit clings to teeth."},{"label":"Plain yogurt","correct":false,"feedback":"Plain yogurt has no added sugar to feed cavity-causing bacteria."}]}},{"id":"l7-b5","chapter":"Cystic fibrosis, diabetes and special diets","title":"Cystic fibrosis, diabetes and special diets","teach":["In cystic fibrosis (CF), the pancreas doesn't release enough digestive enzymes, so nutrients, especially fat and the fat-soluble vitamins, are poorly absorbed. Children with CF take pancreatic enzymes with every meal and snack, plus water-soluble forms of vitamins A, D, E and K. Their energy and protein needs are much higher than usual because of poor absorption and lung infections.","Type 1 diabetes is an immune condition that leaves the body making virtually no insulin. Protein needs go up with wound healing and CF, but not with PKU. The ketogenic diet, used for hard-to-control seizures, is very high in fat and very low in carbohydrate: think eggs, bacon and cheese, not cereal and juice."],"act":{"type":"choice","prompt":"Which breakfast fits a ketogenic diet?","options":[{"label":"Oatmeal with milk, raisins and brown sugar","correct":false,"feedback":"This is high in carbohydrate."},{"label":"Scrambled eggs with bacon and cheese","correct":true,"feedback":"Yes. High fat and very low carbohydrate."},{"label":"Toast and jelly with grape juice","correct":false,"feedback":"This is almost all carbohydrate."}]}},{"id":"l7-b6","chapter":"Cerebral palsy and ADHD","title":"Cerebral palsy and ADHD","teach":["Spastic quadriplegia, cerebral palsy (CP) affecting all four limbs, causes the most nutrition problems. These children often look thin partly because their muscles are smaller, so body composition changes. Common problems include feeding difficulty, constipation, reflux and contractures.","Children with ADHD are often treated with psychostimulant medication, which can lower appetite and slow weight gain and growth. Plan meals and snacks around the medication. A large bedtime snack, when the medication has worn off, is a common tip."],"act":{"type":"choice","prompt":"A child on medication for ADHD isn't hungry at lunch. What is a common suggestion?","options":[{"label":"Stop the medication on school days.","correct":false,"feedback":"Medication decisions belong to the child's doctor. Nutrition advice works around it."},{"label":"Offer a bigger snack in the evening when the medication has worn off.","correct":true,"feedback":"Yes. Time meals and snacks for when appetite returns."},{"label":"Insist the child finishes lunch.","correct":false,"feedback":"Pressure doesn't help, and appetite is truly low while the medication works."}]}}],"flashcards":[{"front":"BMI (adiposity) rebound","back":"The normal rise in body fat after its lowest point, usually around age six. Early rebound raises obesity risk."},{"front":"Strongest predictor of childhood obesity","back":"Maternal obesity."},{"front":"Controlling or restrictive feeding","back":"Children regulate intake less well and are more likely to become overweight."},{"front":"Protein for ages 4–13","back":"About 0.95 g per kg per day."},{"front":"Fibre AI, ages 4–8","back":"25 g a day."},{"front":"Fat AMDR, ages 4–18","back":"25–35% of Calories."},{"front":"Most cavity-promoting snacks","back":"Sticky, sugary foods like raisins."},{"front":"AAP: replace sweetened school drinks with…","back":"Fruit and vegetable juices, water, and low-fat white or flavoured milk."},{"front":"Cystic fibrosis","back":"Too few pancreatic enzymes cause poor absorption. Take enzymes with meals, plus vitamins A, D, E and K."},{"front":"Type 1 diabetes","back":"An immune condition with virtually no insulin production."},{"front":"Conditions that increase protein needs","back":"Wound healing and cystic fibrosis."},{"front":"Ketogenic diet","back":"Very high fat, very low carbohydrate. Used for hard-to-control seizures."},{"front":"Spastic quadriplegia","back":"CP in all four limbs. Changes in body composition and the most nutrition problems."},{"front":"Psychostimulants","back":"Medication for ADHD. Can lower appetite and slow growth."}],"quiz":[{"q":"Studies show that children of parents who impose authoritarian methods of control on their eating are:","o":["likely to have healthy eating habits","less likely to regulate their intake","more likely to become overweight","prone to developing fewer eating-related issues","Both b and c"],"a":4,"e":"Checked answer, not from an official key. The textbook says controlled children regulate their intake less well and are more likely to become overweight."},{"q":"What is the recommended adequate intake of total fiber for children between the ages of 4 and 8?","o":["25 g/day","29 g/day","31 g/day","35 g/day"],"a":0,"e":"Checked answer, not from an official key. The AI for ages 4–8 is 25 g a day."},{"q":"Which of the following foods would be MOST likely to promote dental caries?","o":["Raisins","Apple slices","Cheddar cheese","Peanut butter","Plain yogurt"],"a":0,"e":"Checked answer, not from an official key. Sticky, sugary dried fruit clings to teeth."},{"q":"“BMI rebound” can be defined as:","o":["the period in which your weight “rebounds” and settles in at your normal weight.","the normal increase in percent body fat which occurs after percent body fat declines and reaches its lowest point.","the point at which you have the greatest amount of fat you will ever have, typically between the ages of 8 and 10.","the weight you attain by the age of 13 after you have had a growth spurt.","the loss of all a child’s baby fat, which occurs at about 6 years of age."],"a":1,"e":"Checked answer, not from an official key. The textbook defines it as the normal rise in body fat after its lowest point, usually around age six."},{"q":"The most significant predictor of childhood obesity has been found to be:","o":["low family income.","food insecurity.","Maternal obesity.","lower cognitive stimulation.","use of formula instead of breastfeeding."],"a":2,"e":"Checked answer, not from an official key. The textbook says maternal obesity was the most significant predictor."},{"q":"Which of the following foods would be the best choice for a parent trying to increase fiber in her/his child’s diet?","o":["Protein or energy bar","Fresh fruits, vegetables and whole-grain breads","Fresh juice and enriched bread","Canned fruits","All of the above would be great sources of fiber."],"a":1,"e":"Checked answer, not from an official key. Whole fruits, vegetables and whole grains are the best fibre sources."},{"q":"The American Academy of Pediatrics (AAP) advocates for the elimination of sweetened beverages in school and suggests replacing them with all of the following EXCEPT:","o":["Low-fat chocolate milk","Low-fat milk","Vegetable juice","100% fruit juice","Sports beverages"],"a":4,"e":"Checked answer, not from an official key. The AAP lists juices, water, and low-fat white or flavoured milk, not sports drinks."},{"q":"Using the following information, answer questions 8-11.\n\nJane is an 8-year-old girl that weighs 56.5 pounds (25.6 kg), is 51 inches tall, and enjoys lots of outdoor activities. Her total caloric intake is 1800 Calories per day consisting of 80 grams of fat, 225 grams of carbohydrate, and 45 grams of protein. She likes vegetables and eats lots of fruit; the only food she truly dislikes is milk.\n\nJane gets _____% of her energy from fat.","o":["20","25","30","35","40"],"a":4,"e":"Checked answer, not from an official key. 80 g × 9 = 720 Calories. 720 ÷ 1,800 × 100 = 40%."},{"q":"Jane is an 8-year-old girl that weighs 56.5 pounds (25.6 kg), is 51 inches tall, and enjoys lots of outdoor activities. Her total caloric intake is 1800 Calories per day consisting of 80 grams of fat, 225 grams of carbohydrate, and 45 grams of protein. She likes vegetables and eats lots of fruit; the only food she truly dislikes is milk.\n\nIs this within the Acceptable Macronutrient Distribution Range (AMDR) for fat for a child her age?","o":["Yes","No","Cannot be determined from the information provided"],"a":1,"e":"Checked answer, not from an official key. The range for ages 4–18 is 25–35%, and 40% is above it."},{"q":"Jane is an 8-year-old girl that weighs 56.5 pounds (25.6 kg), is 51 inches tall, and enjoys lots of outdoor activities. Her total caloric intake is 1800 Calories per day consisting of 80 grams of fat, 225 grams of carbohydrate, and 45 grams of protein. She likes vegetables and eats lots of fruit; the only food she truly dislikes is milk.\n\nHow many grams of protein per day are recommended for Jane?","o":["24 g","15 g","30 g","20 g","50 g"],"a":0,"e":"Checked answer, not from an official key. 25.6 kg × 0.95 g = about 24 g."},{"q":"Jane is an 8-year-old girl that weighs 56.5 pounds (25.6 kg), is 51 inches tall, and enjoys lots of outdoor activities. Her total caloric intake is 1800 Calories per day consisting of 80 grams of fat, 225 grams of carbohydrate, and 45 grams of protein. She likes vegetables and eats lots of fruit; the only food she truly dislikes is milk.\n\nIs she eating more, less, or the recommended amount of protein compared to the DRI for a girl her age?","o":["More","Less","Exactly as much as the DRI recommends"],"a":0,"e":"Checked answer, not from an official key. She eats 45 g, which is more than the 24 g recommended."},{"q":"Examples of conditions that INCREASE protein needs include:","o":["wound healing.","cystic fibrosis.","PKU.","All of the above","a and b only"],"a":4,"e":"Checked answer, not from an official key. Wound healing and CF raise protein needs. PKU calls for a special low-phenylalanine protein source, not more protein."},{"q":"Fat-soluble vitamin supplements are recommended for children with __________________ due to poor intestinal absorption of these nutrients.","o":["diabetes","seizures","PKU","cystic fibrosis","all of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook says CF treatment requires fat-soluble vitamin supplements."},{"q":"Energy and protein needs for children with cystic fibrosis are _____________________ those of healthy children.","o":["less than","the same as","two to four times greater than","greater than four times"],"a":2,"e":"Checked answer, not from an official key. Less certain: the textbook says needs are much higher because of poor absorption and lung infections, but it doesn't give this exact range. Check this one against your graded result."},{"q":"Type 1 diabetes is related to immune function and results in virtually ________________________________________.","o":["no immune system regulation","no colds for the first few years of the disease","no ability to process all macronutrients","no regulation of appetite","no insulin production"],"a":4,"e":"Checked answer, not from an official key. In type 1 diabetes the body makes virtually no insulin."},{"q":"Nutritional consequences of spastic quadriplegia include:","o":["rapid weight gain.","predictable 2-fold increases in energy needs.","changes in body composition.","extreme vitamin and mineral deficiencies."],"a":2,"e":"Checked answer, not from an official key. Less certain: the textbook says these children often look thin partly because their muscles are smaller, which is a change in body composition. Check this one against your graded result."},{"q":"A psychostimulant is a medication given to children with ____________________________.","o":["seizures","attention deficit hyperactivity disorder","phenylketonuria","type 1 diabetes"],"a":1,"e":"Checked answer, not from an official key. Psychostimulants are used for ADHD."},{"q":"What is the importance of taking pancreatic enzymes when a child has cystic fibrosis?","o":["These enzymes help digest foods and when they are missing, malabsorption of various nutrients occurs","Pancreatic enzymes also supply the fat-soluble vitamins, which are necessary for normal growth.","It is not necessary to take pancreatic enzymes with cystic fibrosis; you need to take nutritional supplements, however.","Without these enzymes, inflammation occurs.","These enzymes help with calcium absorption."],"a":0,"e":"Checked answer, not from an official key. Without pancreatic enzymes, many nutrients are poorly absorbed."},{"q":"Which of the following foods would be the best breakfast choice for a child on a ketogenic diet?","o":["A bowl of frosted Mini-Wheat, milk, and orange juice","Homemade oatmeal with milk, raisins, and brown sugar","Scrambled eggs with bacon and cheese","Toast and jelly with a glass of grape juice","A doughnut with a glass of chocolate milk"],"a":2,"e":"Checked answer, not from an official key. The ketogenic diet is high in fat and very low in carbohydrate."},{"q":"Which of the following is NOT a secondary effect of cerebral palsy?","o":["Dehydration","Constipation","Contractures","Gastroesophageal reflux"],"a":0,"e":"Checked answer, not from an official key. Less certain: constipation, contractures and reflux are common in children with CP, so dehydration is the likely answer, but the textbook text doesn't list them together. Check this one against your graded result."}]},{"n":8,"title":"Adolescent Nutrition","kicker":"Lesson 8 of your course, built from Chapters 14 and 15 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l8-b1","chapter":"What shapes how teens eat","title":"What shapes how teens eat","teach":["Three levels of influence shape teen eating. Personal factors include family and friends, food likes, role models, confidence and body changes. Environmental factors include home, school, fast-food places and stores. Macrosystem factors include how food is produced and sold, and the media and advertising. Good programs work on all three.","Snacks make up about a quarter of teens' daily energy and a large share of their added sugars. Soft drinks are the top source of energy and added sugar in teen diets."],"act":{"type":"sort","prompt":"Sort each influence into its level.","categories":["Personal","Environmental","Macrosystem"],"items":[{"label":"Friends' food choices","category":0,"feedback":"Peers are a personal or interpersonal influence."},{"label":"What the school cafeteria sells","category":1,"feedback":"The school food environment is an environmental factor."},{"label":"TV and online food ads","category":2,"feedback":"Mass media and advertising are macrosystem factors."}]}},{"id":"l8-b2","chapter":"Growth and key nutrients","title":"Growth and key nutrients","teach":["Adolescence is a time of fast growth. Teens hold on to more calcium than adults and build much of their lifetime bone mass, which is why calcium matters so much at this age. Milk and fortified drinks are key sources, and vitamin D helps calcium do its job.","Iron needs rise with fast growth, more blood volume and, for girls, the start of periods. Teens have the lowest folate levels of any age group, which matters for girls who could become pregnant. Breakfast cereals and orange juice help."],"act":{"type":"choice","prompt":"What is the best reason to make sure young teens get enough calcium?","options":[{"label":"They retain more calcium than adults and are building bone mass.","correct":true,"feedback":"Yes. This is a key window for building bone."},{"label":"They burn more energy in sports.","correct":false,"feedback":"Energy use doesn't drive calcium needs."},{"label":"Dairy foods are cheap.","correct":false,"feedback":"Cost isn't the nutrition reason."}]}},{"id":"l8-b3","chapter":"Talking with teens about food","title":"Talking with teens about food","teach":["Teens respond to messages about the here and now, such as having energy for sports and friends, more than warnings about disease decades away. Focus on lasting healthy habits rather than short-term dieting.","A 24-hour recall, food frequency questionnaire or food record can all be used with teens. A 24-hour recall is quick to start in person and can easily be finished by phone later."],"act":{"type":"choice","prompt":"Which message is most likely to motivate a teen?","options":[{"label":"“Eating well will give you energy for sports and time with friends.”","correct":true,"feedback":"Yes. Short-term, personal benefits work best with teens."},{"label":"“Eating well may prevent heart disease later in life.”","correct":false,"feedback":"Long-term disease risk feels far away to most teens."},{"label":"“Eat it because it's good for you.”","correct":false,"feedback":"This usually backfires with teens."}]}},{"id":"l8-b4","chapter":"Overweight in adolescence","title":"Overweight in adolescence","teach":["For teens, BMI is compared with percentiles for age and sex. Between the 5th and 85th percentile is a healthy weight, the 85th to 95th is overweight (older guides say “at risk for overweight”), and the 95th and above is obese.","Up to 90% of overweight teens stay overweight as adults, so early support matters. Look at the share of Calories from fat when helping teens choose fast food: grams of fat × 9 ÷ Calories × 100."],"act":{"type":"number","prompt":"A fast-food item has 500 Calories and 15 g of fat. What percent of its Calories come from fat?","answer":27,"tolerance":0,"unit":"%","explanation":"15 × 9 = 135 Calories from fat. 135 ÷ 500 × 100 = 27%, which is within 25–35%."}},{"id":"l8-b5","chapter":"Teen athletes","title":"Teen athletes","teach":["Teens need energy for their basal metabolism, their activity and pubertal growth. Carbohydrates are the most effective way to build up muscle glycogen. Some endurance athletes use carbohydrate loading before a big event.","For fluids, drink about 16 oz for each pound lost during activity. During long events, sports drinks with no more than 6–8% carbohydrate, or juice diluted with water, hydrate better. Undiluted juice and stronger drinks can cause cramping."],"act":{"type":"number","prompt":"A wrestler loses 2 lb during practice. How many ounces of fluid should he drink afterward?","answer":32,"tolerance":0,"unit":"oz","explanation":"16 oz × 2 lb = 32 oz."}},{"id":"l8-b6","chapter":"Eating disorders and special needs","title":"Eating disorders and special needs","teach":["Binge-eating disorder means eating large amounts in a short time while feeling out of control, but without compensating by vomiting, laxatives or over-exercising. That last part is what sets it apart from bulimia. Treatment goals include a full diet assessment, a regular pattern of balanced meals, slowly bringing back “forbidden” foods, and stepping away from dieting and too much exercise. Family members can help by eating balanced meals themselves and showing love and praise that has nothing to do with food or weight.","Up to 40% of children and teens with special health care needs have nutrition risks that call for a referral to a dietitian. A lacto-vegetarian teen can get iron from beans and lentils, eaten with vitamin C foods such as tomatoes to boost absorption."],"act":{"type":"choice","prompt":"How does binge-eating disorder differ from bulimia?","options":[{"label":"It doesn't involve compensating behaviours like vomiting or laxatives.","correct":true,"feedback":"Yes. That is the key difference."},{"label":"It doesn't involve eating large amounts.","correct":false,"feedback":"Both involve eating large amounts in a short time."},{"label":"Binges are mostly fruit and vegetables.","correct":false,"feedback":"The type of food isn't what defines it."}]}}],"flashcards":[{"front":"Three levels of influence on teen eating","back":"Personal, environmental and macrosystem."},{"front":"Snacks in teen diets","back":"About a quarter of daily food energy."},{"front":"Why calcium matters for teens","back":"They retain more calcium than adults and build bone mass."},{"front":"What raises teens' iron needs","back":"Fast growth, more blood volume and the start of periods."},{"front":"Folate in teens","back":"Teens have the lowest folate levels of any age group, which matters for girls who could become pregnant."},{"front":"Best motivating message for teens","back":"Short-term benefits, like energy for sports and friends."},{"front":"BMI 50th–75th percentile","back":"Healthy (normal) weight."},{"front":"Overweight teens into adulthood","back":"Up to 90% stay overweight."},{"front":"Fluid after exercise","back":"About 16 oz for each pound lost."},{"front":"Carbohydrate in drinks during long exercise","back":"No more than 6–8%."},{"front":"Best for building muscle glycogen","back":"Carbohydrates."},{"front":"Binge-eating disorder vs. bulimia","back":"No compensating behaviours in binge-eating disorder."},{"front":"Special health care needs and referral","back":"Up to 40% have nutrition risks that call for a dietitian."},{"front":"Iron for a lacto-vegetarian teen","back":"Beans and lentils, with vitamin C foods like tomatoes."}],"quiz":[{"q":"In order to improve the eating habits of youth, nutrition interventions should be aimed at three levels of influence. Which of the following would NOT be one of these levels?","o":["Environmental factors","Macrosystem factors","Transportation factors","Personal factors"],"a":2,"e":"Checked answer, not from an official key. The three levels are personal, environmental and macrosystem."},{"q":"Snacks account for up to _____% of daily food intake among adolescents.","o":["15-20","23-27","27-35","41-44","51-55"],"a":1,"e":"Checked answer, not from an official key. The textbook says snacks make up about one-quarter of teens' daily food energy."},{"q":"The best reason for advising young adolescents to consume foods that provide adequate calcium is ____________________________________________________________________.","o":["young adolescents expend more energy from increased physical activity and need more calcium","young adolescents do not have much money and dairy foods are the least expensive to buy","young adolescents retain four times as much calcium than adults and build bone mass","young adolescents fight with their parents a lot and this would eliminate one food battle"],"a":2,"e":"Checked answer, not from an official key. Teens retain more calcium and build much of their bone mass."},{"q":"All of the following are factors that increase a teen’s need for iron EXCEPT:","o":["A rapid rate of linear growth.","The onset of menarche for females.","An increase in blood volume.","Greater intake of heme than nonheme iron sources.","All of the above factors increase a teen’s need for iron."],"a":3,"e":"Checked answer, not from an official key. Heme iron is better absorbed, so it doesn't increase needs."},{"q":"Susan is a 15-year-old who likes fruits, some vegetables, and breads (whole-grain and enriched) but refuses to consume milk, seafood, and eggs. A recent doctor visit revealed normal hemoglobin and plasma ferritin levels. What would you advise?","o":["A folate supplement (400 micrograms/day)","A vitamin D supplement (400 IU/day)","An iron supplement (10 mg/day)","No changes in nutrient intake"],"a":1,"e":"Checked answer, not from an official key. Less certain: her iron is normal and enriched breads give folate, but without milk, seafood or eggs she has almost no vitamin D source. Check this one against your graded result."},{"q":"An underweight 17-year-old male was 15 minutes late to his nutrition counseling appointment and he has to leave for a school-related practice in 20 minutes. What dietary assessment method would be the most appropriate for the dietitian to begin assessing his food intake pattern as well as a method that she could reliably complete on the telephone at a later time?","o":["24-hour recall","Food frequency","Food record","Diet history"],"a":0,"e":"Checked answer, not from an official key. A 24-hour recall is quick to start and easy to finish by phone."},{"q":"Which of these messages is best for motivating adolescents to eat a healthy diet?","o":["“Eating well will give you energy for sports or social activities.”","”Eat what you don’t like because it’s good for you.”","”Eating well may prevent heart disease in the long term.”","”Eat well now so you won’t be frail or disabled when you are old.”"],"a":0,"e":"Checked answer, not from an official key. Teens respond best to short-term, personal benefits."},{"q":"For which 16-year-old teen would the dietitian have the greatest concern about folate status?","o":["Male whose estimated intake is 450 micrograms per day","Female who consumes orange juice and cereal for breakfast","Male with serum folate levels just below the normal range","Female who is sexually active and skips breakfast"],"a":3,"e":"Checked answer, not from an official key. She could become pregnant, and skipping breakfast means missing fortified cereal and juice."},{"q":"Youth with body mass index (BMI) values > 50th percentile, but < 75th percentile are considered:","o":["normal weight.","at risk for overweight.","overweight.","obese.","morbidly obese."],"a":0,"e":"Checked answer, not from an official key. Below the 85th percentile is a healthy weight."},{"q":"As many as _____ of overweight adolescents can be expected to remain overweight into adulthood.","o":["40%","50%","60%","70%","90%"],"a":4,"e":"Checked answer, not from an official key. The textbook says as many as 90%."},{"q":"Each pound of body weight lost during an activity requires ingestion of _____ ounces of fluid following the activity to maintain proper hydration.","o":["8","16","20","32","48"],"a":1,"e":"Checked answer, not from an official key. The usual guide is 16 oz for each pound lost."},{"q":"Use the Tapango’s menu provided below to answer questions 12-14.\n\nBreakfast Burrito\nnutritional information: 412 Calories, 17g fat, 6.6g saturated fat, 44.9g carbs per 200g burrito\ningredients: flour tortilla, scrambled eggs, salsa, and cheddar cheese\nBreakfast Burrito with Bacon\nnutritional information: 657 Calories, 35.9g fat, 12.9g saturated fat, 45.5g carbs per 245g burrito\ningredients: flour tortilla, scrambled eggs, bacon, salsa, and cheddar cheese\nPrimo Breakfast Burrito\nnutritional information: 761 Calories, 43.6g fat, 16.8g saturated fat, 54.2g carbs per 402g burrito\ningredients: flour tortilla, scrambled eggs, bacon, cheddar cheese, salsa, lettuce, chili sauce, sour cream, tomatoes, olives, onions, jalapeño peppers\nBreakfast Quesadilla\nnutritional information: 478 Calories, 23.9g fat, 11.8g saturated fat, 41.7g carbs per 171g quesadilla\ningredients: flour tortilla, scrambled eggs, and cheddar cheese\nBreakfast Quesadilla with Bacon\nnutritional information: 726 Calories, 43g fat, 18.1g saturated fat, 42.5g carbs per 217g quesadilla\ningredients: flour tortilla, scrambled eggs, bacon, and cheddar cheese\nPrimo Nachos\nnutritional information: 964 Calories, 49.3g fat, 14.3g saturated fat, 102.7g carbs per 445g nachos\ningredients: tortilla chips, nacho cheese, refried beans, chicken (chicken breast, green chili peppers, olive oil, onions, garlic), salsa, lettuce, chili sauce, sour cream, tomatoes, olives, onions, and jalapeño peppers\nPrimo Taco Salad\nnutritional information: 502 Calories, 20.9g fat, 5.5g saturated fat, 62.6g carbs per 448g taco salad\ningredients: lettuce, chicken (chicken breast, green chili peppers, olive oil, onions, garlic, and spices), tortilla chips, refried beans, Spanish rice (rice, olive oil, tomato sauce, onions, garlic, and spices), salsa, lettuce, chili sauce, sour cream, tomatoes, olives, onions, and jalapeño peppers\nBeef Taco\nnutritional information: 214 Calories, 11.7g fat, 5.1g saturated fat, 14.5 carbs per 128g taco\ningredients: corn tortilla, beef (ground beef, tomato sauce, onions, and spices), chili sauce, lettuce, tomatoes, and cheddar cheese\nChicken Taco\nnutritional information: 154 Calories, 5.3g fat, 2.4g saturated fat, 14.1g carbs per 128g taco\ningredients: corn tortilla, chicken (chicken breast, green chili peppers, olive oil, onions, garlic, and spices), chili sauce, lettuce, tomatoes, and cheddar cheese\n\nAn adolescent is considering Tapango’s menu and would like to choose the food with the lowest percentage of fat calories. This would be the:","o":["breakfast burrito w/ bacon.","breakfast quesadilla w/ bacon.","primo taco salad.","beef taco.","primo nachos."],"a":2,"e":"Checked answer, not from an official key. Taco salad: 20.9 × 9 ÷ 502 = 37%. The others are 46–53%."},{"q":"Would this food fit within the current recommendations for fat consumption?","o":["No, it is high at 37% fat","No, it is high at 47% fat","No, it is low at 17% fat","Yes, it is only 30% fat","Need more information"],"a":0,"e":"Checked answer, not from an official key. 37% is above the 25–35% range for teens."},{"q":"What beverage would be a good accompaniment to this meal and provide a nutrient that is usually scarce in adolescent diets?","o":["Non-fat milk","Diet soda","Water","Regular soda","Iced tea with sweetener"],"a":0,"e":"Checked answer, not from an official key. Milk adds calcium, which is often low in teen diets."},{"q":"A juice or sports drink that contains no more than _____ carbohydrate may allow for better hydration and physical performance than those that are more concentrated.","o":["2-3%","4-5%","5-6%","6-8%","9-10%"],"a":3,"e":"Checked answer, not from an official key. The textbook says no more than 6–8% carbohydrate."},{"q":"A teenage girl ate Christmas dinner at her step-mother’s house and following a creamy dessert, announced, “I am fatter than all of my classmates; I am going to stop eating for 5 days!” Important behaviors the step-mother should model include all of the following EXCEPT:","o":["eating well-balanced meals as part of her normal routine.","showing the step-daughter love without using food.","identifying strengths of the step-daughter that are not eating related.","beginning a subscription to Weight Watcher’s magazine for the stepdaughter."],"a":3,"e":"Checked answer, not from an official key. A dieting magazine would feed the focus on weight."},{"q":"Binge-eating disorder differs from bulimia nervosa in that binge-eating disorder:","o":["does not include binges on “fast” or “junk” foods.","does not involve eating large amounts of food in a short period of time.","does include large amounts of fruits and vegetables during a binge episode.","does not involve compensatory behaviors.","involves stool softeners, not laxatives."],"a":3,"e":"Checked answer, not from an official key. Binge-eating disorder has no vomiting, laxatives or other compensating behaviours."},{"q":"Key goals of nutritional care for someone in treatment for an eating disorder would include:","o":["establishing a regular pattern of nutritionally balanced meals.","gradually introducing forbidden foods into the diet.","avoiding dieting behaviors and excessive exercise.","thoroughly assessing dietary intake and adequacy.","All of the above are key goals"],"a":4,"e":"Checked answer, not from an official key. All four are goals of nutrition care for eating disorders."},{"q":"An estimated _____ percent of children and adolescents with a chronic condition or disability also have nutrition risk factors that warrant a referral to a dietitian.","o":["20","30","40","50"],"a":2,"e":"Checked answer, not from an official key. The textbook says as many as 40%."},{"q":"Use the following nutrition label to answer questions 20-22.\n\nNutrition Facts\nServing Size 1 Drink Box (6.75 oz)\nServings Per Container 1\nAmount Per Serving\nCalories 100\nCalories from Fat 0\n% Daily Value*\nTotal Fat 0g 0%\nSaturated Fat 0g 0%\nTrans Fat 0g\nCholesterol 0mg 0%\nSodium 25mg 1%\nTotal Carbohydrate 27g 10%\nDietary Fiber 0g\nSugars 24g\nProtein 1g 2%\nVitamin A 0%\nVitamin C 2%\nCalcium 10%\nIron 0%\n\nA coach bought fruit juice boxes (see food label above) for the wrestling team to provide energy to wrestlers after they weighed in. What is the best recommendation for teens when they consume this 30 minutes before the meet?","o":["Dilute half of this juice with 6.75 oz cold water","Drink three juice boxes to get adequate fluid volume before the match.","Only drink 20 oz of water before the match.","Find a vending machine and purchase a sports drink containing caffeine."],"a":0,"e":"Checked answer, not from an official key. Diluting juice with water brings the carbohydrate down to a level that hydrates better."},{"q":"Nutrition Facts\nServing Size 1 Drink Box (6.75 oz)\nServings Per Container 1\nAmount Per Serving\nCalories 100\nCalories from Fat 0\n% Daily Value*\nTotal Fat 0g 0%\nSaturated Fat 0g 0%\nTrans Fat 0g\nCholesterol 0mg 0%\nSodium 25mg 1%\nTotal Carbohydrate 27g 10%\nDietary Fiber 0g\nSugars 24g\nProtein 1g 2%\nVitamin A 0%\nVitamin C 2%\nCalcium 10%\nIron 0%\n\nBased on the calories in this drink, calculate the percentage of total calories from carbohydrates it provides.","o":["14","40","50","100"],"a":3,"e":"Checked answer, not from an official key. 27 g × 4 = 108 Calories, which is essentially all of the 100 Calories."},{"q":"Nutrition Facts\nServing Size 1 Drink Box (6.75 oz)\nServings Per Container 1\nAmount Per Serving\nCalories 100\nCalories from Fat 0\n% Daily Value*\nTotal Fat 0g 0%\nSaturated Fat 0g 0%\nTrans Fat 0g\nCholesterol 0mg 0%\nSodium 25mg 1%\nTotal Carbohydrate 27g 10%\nDietary Fiber 0g\nSugars 24g\nProtein 1g 2%\nVitamin A 0%\nVitamin C 2%\nCalcium 10%\nIron 0%\n\nWould this beverage be a good choice to drink during a strenuous activity?","o":["Yes: it is 100% fruit juice, so it is a good choice","No: it is too high in carbohydrate and may cause cramping","Not enough information is provided on the label"],"a":1,"e":"Checked answer, not from an official key. At about 13% carbohydrate, it is well above the 6–8% advised during exercise."},{"q":"What iron-rich food source would be the best choice for an adolescent who is a lactovegetarian?","o":["Pinto beans and diced tomatoes","Scrambled eggs with cheese","Tuna sandwich","Flour tortilla with cheese","Fish sandwich with lettuce"],"a":0,"e":"Checked answer, not from an official key. Beans give iron, and the vitamin C in tomatoes helps absorb it. Lacto-vegetarians don't eat eggs or fish."},{"q":"What dietary components are MOST effective at raising muscle glycogen concentrations?","o":["Fats","Proteins","Carbohydrates","Chromium & iron-containing supplements"],"a":2,"e":"Checked answer, not from an official key. Carbohydrates build muscle glycogen."},{"q":"The energy needs of adolescents are influenced by basal metabolic rate, activity level, and increased requirements to support pubertal growth and development.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. All three affect energy needs."}]},{"n":9,"title":"Adult Nutrition","kicker":"Lesson 9 of your course, built from Chapters 16 and 17 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l9-b1","chapter":"How energy needs change in adulthood","title":"How energy needs change in adulthood","teach":["Metabolic rate and energy use start to drop in early adulthood, by about 2.0% per decade in women and 2.9% in men. This mostly follows a drop in activity and muscle. Staying active slows it down.","Resting energy expenditure (REE) can be estimated with a formula. For women: REE = (10 × weight in kg) + (6.25 × height in cm) − (5 × age) − 161. Multiply by an activity factor (for example, 1.4 for light activity) to estimate daily needs. To lose about 1 lb a week, eat about 500 fewer Calories a day."],"act":{"type":"number","prompt":"A 40-year-old woman weighs 60 kg and is 165 cm tall. What is her REE? (Round to the nearest whole number.)","answer":1270,"tolerance":2,"unit":"Calories","explanation":"(10 × 60) + (6.25 × 165) − (5 × 40) − 161 = 600 + 1,031 − 200 − 161 = 1,270 Calories."}},{"id":"l9-b2","chapter":"Macronutrients and alcohol","title":"Macronutrients and alcohol","teach":["The adult range for fat is 20–35% of Calories. On 2,000 Calories, that's 400–700 Calories from fat. To check a food, divide the Calories from fat by total Calories and multiply by 100. Saturated fat should stay under the Daily Value of 20 g on a 2,000-Calorie diet.","A standard alcoholic drink has about 13–15 g of alcohol, or about 0.5 oz of ethanol. Sugary drinks, including fancy coffee drinks, add a lot of Calories and are linked to metabolic syndrome and fatty liver."],"act":{"type":"number","prompt":"A snack has 180 Calories, 54 of them from fat. What percent of its Calories come from fat?","answer":30,"tolerance":0,"unit":"%","explanation":"54 ÷ 180 × 100 = 30%, which is within the 20–35% range."}},{"id":"l9-b3","chapter":"Menopause","title":"Menopause","teach":["After menopause, the drop in estrogen speeds up bone loss, shifts fat toward the belly and raises the risk of heart disease. Calcium, vitamin D, weight-bearing activity and a heart-healthy diet become even more important.","Fat stored deep in the belly (visceral fat) is linked to more health risks than fat under the skin or on the hips and thighs."],"act":{"type":"choice","prompt":"Which of these is NOT caused by lower estrogen after menopause?","options":[{"label":"Faster bone loss","correct":false,"feedback":"Lower estrogen does speed up bone loss."},{"label":"More belly fat","correct":false,"feedback":"Fat tends to shift toward the abdomen."},{"label":"More acne","correct":true,"feedback":"Right. Acne isn't one of the effects described."}]}},{"id":"l9-b4","chapter":"Heart disease and metabolic syndrome","title":"Heart disease and metabolic syndrome","teach":["Cardiovascular disease affects the heart, the brain (stroke) and the blood vessels. Risk factors for coronary heart disease include low HDL (under 40 mg/dL), high LDL, smoking, high blood pressure, diabetes, a family history of early heart disease, older age (55+ for women), belly fat and eating few whole grains. Fat on the hips and thighs isn't a risk factor.","Metabolic syndrome is a cluster that includes belly fat, high blood glucose, high triglycerides, low HDL and high blood pressure. Helpful changes include fewer high-fat dairy foods and fried foods, leaner meats, and more whole grains and fibre."],"act":{"type":"choice","prompt":"Which is NOT a risk factor for coronary heart disease?","options":[{"label":"HDL under 40 mg/dL","correct":false,"feedback":"Low HDL raises risk."},{"label":"Extra fat on the hips and thighs","correct":true,"feedback":"Right. Belly fat raises risk, but hip and thigh fat doesn't."},{"label":"Eating few whole grains","correct":false,"feedback":"A low intake of whole grains is linked to higher risk."}]}},{"id":"l9-b5","chapter":"Cancer","title":"Cancer","teach":["Cancer can start in any cell, but most cancers start in epithelial tissue, the cells lining the skin, lungs, gut, breast and other organs. These cells divide quickly and are most exposed to things in the environment.","Diet can raise or lower risk. Excess body fat, alcohol and processed meat raise it, while vegetables (such as cruciferous ones), fruit, whole grains and fibre are protective."],"act":{"type":"choice","prompt":"Where do most cancers develop?","options":[{"label":"Epithelial tissue","correct":true,"feedback":"Yes. These fast-dividing lining cells are most exposed to carcinogens."},{"label":"Fat cells","correct":false,"feedback":"Excess body fat raises risk, but most cancers start in epithelial tissue."},{"label":"Bone marrow","correct":false,"feedback":"Some cancers do, but most start in epithelial tissue."}]}}],"flashcards":[{"front":"Decline in metabolic rate per decade","back":"About 2.0% for women and 2.9% for men."},{"front":"REE formula for women","back":"(10 × kg) + (6.25 × cm) − (5 × age) − 161."},{"front":"To lose 1 lb a week","back":"Eat about 500 fewer Calories a day."},{"front":"Adult AMDR for fat","back":"20–35% of Calories (400–700 Calories on 2,000)."},{"front":"Grams of alcohol in a drink","back":"About 13–15 g (0.5 oz of ethanol)."},{"front":"Saturated fat Daily Value","back":"20 g a day on a 2,000-Calorie diet."},{"front":"Effects of lower estrogen after menopause","back":"Faster bone loss, more belly fat and higher heart disease risk."},{"front":"Areas affected by cardiovascular disease","back":"The heart, the brain and the blood vessels."},{"front":"Not a heart disease risk factor","back":"Fat on the hips and thighs."},{"front":"Metabolic syndrome includes…","back":"Belly fat, high glucose, high triglycerides, low HDL and high blood pressure."},{"front":"Where most cancers start","back":"Epithelial tissue."}],"quiz":[{"q":"The decline in estrogen production in women after menopause leads to all of the following EXCEPT:","o":["more acne.","accelerated loss of bone mass.","an increase in abdominal fat.","greater risk of cardiovascular disease.","All of the above occur with less estrogen."],"a":0,"e":"Checked answer, not from an official key. Lower estrogen speeds bone loss, adds belly fat and raises heart disease risk, but acne isn't one of its effects."},{"q":"To lose one pound per week, a person would need to eat ________ fewer Calories per day.","o":["250","300","450","500","1,000"],"a":3,"e":"Checked answer, not from an official key. About 3,500 Calories make a pound, and 3,500 ÷ 7 = 500 a day."},{"q":"Metabolic rate and energy expenditure begin to decline in early adulthood at a rate of about _____ per decade for women and _____ per decade for men.","o":["2.0%, 2.9%","5.0%, 5.9%","8.0%, 8.0%","5.9%, 5.0%","2.9%, 2.0%"],"a":0,"e":"Checked answer, not from an official key. The textbook gives 2.0% for women and 2.9% for men."},{"q":"The Acceptable Macronutrient Distribution Range for total fat intake is _____ of Calories.","o":["10-15%","15-20%","20-35%","35-40%","40-50%"],"a":2,"e":"Checked answer, not from an official key. 20–35% for adults."},{"q":"Based on the Acceptable Macronutrient Distribution Ranges, someone that consumes 2000 Calories per day should aim for _______________ fat Calories/day.","o":["200-400","400-700","600-900","1000-1200"],"a":1,"e":"Checked answer, not from an official key. 20% of 2,000 is 400 and 35% is 700."},{"q":"An alcoholic drink contains roughly _____ grams of alcohol or 0.5 oz of ethanol.","o":["2-5","6-8","9-11","13-15","17-21"],"a":3,"e":"Checked answer, not from an official key. Less certain: a standard drink is about 14 g of alcohol, but the textbook text doesn't give the figure. Check this one against your graded result."},{"q":"One serving of Gardetto’s reduced-fat chips and twists snack mix contains 220 Calories, with 79 kcal from fat. Therefore, the snack mix derives _____% kcal from fat:","o":["75","50","36","25","5"],"a":2,"e":"Checked answer, not from an official key. 79 ÷ 220 × 100 = 36%."},{"q":"Using the answer from question #7, would this product fit the Acceptable Macronutrient Distribution Range for fat intake?","o":["Yes","No","Not enough information to determine"],"a":1,"e":"Checked answer, not from an official key. 36% is just above the 20–35% range."},{"q":"Use the food label below to answer questions 9-11.\n\nNutrition Facts\nServing Size 1 cup (228g)\nServings Per Container 2\nAmount Per Serving\nCalories 260\nCalories from Fat 120\n% Daily Value*\nTotal Fat 13g 20%\nSaturated Fat 5g 25%\nTrans Fat 2g\nCholesterol 30mg 10%\nSodium 660mg 28%\nTotal Carbohydrate 31g 10%\nDietary Fiber 0g\nSugars 5g\nProtein 5g\nVitamin A 4%\nVitamin C 2%\nCalcium 15%\nIron 4%\n\nWhat % of Calories in this food are provided by saturated fat?","o":["2%","9%","13%","17%","25%"],"a":3,"e":"Checked answer, not from an official key. 5 g × 9 = 45 Calories. 45 ÷ 260 × 100 = 17%."},{"q":"Nutrition Facts\nServing Size 1 cup (228g)\nServings Per Container 2\nAmount Per Serving\nCalories 260\nCalories from Fat 120\n% Daily Value*\nTotal Fat 13g 20%\nSaturated Fat 5g 25%\nTrans Fat 2g\nCholesterol 30mg 10%\nSodium 660mg 28%\nTotal Carbohydrate 31g 10%\nDietary Fiber 0g\nSugars 5g\nProtein 5g\nVitamin A 4%\nVitamin C 2%\nCalcium 15%\nIron 4%\n\nWould a person who consumed one container of the food described in this label plus an additional 15 g saturated fat in the same day meet the current recommendations for saturated fat intake (based on the Daily Value)?","o":["Yes, they would meet the recommendations.","No, they would not meet the recommended amount.","Based on the recommendations, they would consume too much saturated fat."],"a":2,"e":"Checked answer, not from an official key. A container is 2 servings, or 10 g. Plus 15 g makes 25 g, which is over the 20 g Daily Value."},{"q":"Nutrition Facts\nServing Size 1 cup (228g)\nServings Per Container 2\nAmount Per Serving\nCalories 260\nCalories from Fat 120\n% Daily Value*\nTotal Fat 13g 20%\nSaturated Fat 5g 25%\nTrans Fat 2g\nCholesterol 30mg 10%\nSodium 660mg 28%\nTotal Carbohydrate 31g 10%\nDietary Fiber 0g\nSugars 5g\nProtein 5g\nVitamin A 4%\nVitamin C 2%\nCalcium 15%\nIron 4%\n\nWould the food described in this label be a good source of fiber?","o":["Yes","No"],"a":1,"e":"Checked answer, not from an official key. It has 0 g of fibre."},{"q":"Use the following information to answer questions 12-13.\n\nMichelle is a 49-year-old, lightly active female who weighs 131 pounds and is 5’8” tall.\nFemales: REE = (10 x weight) + (6.25 x height) - (5 x age) - 161\nSedentary = 1.2\nLight activity = 1.4\nModerate activity = 1.6\nVery active = 1.1\n\nWhat is Michelle’s resting metabolic rate?","o":["1270","1500","1760","2164","2340"],"a":0,"e":"Checked answer, not from an official key. 131 lb = 59.5 kg and 68 in = 172.7 cm. 595 + 1,079 − 245 − 161 = about 1,270."},{"q":"Michelle is a 49-year-old, lightly active female who weighs 131 pounds and is 5’8” tall.\nFemales: REE = (10 x weight) + (6.25 x height) - (5 x age) - 161\nSedentary = 1.2\nLight activity = 1.4\nModerate activity = 1.6\nVery active = 1.1\n\nWhat is Michelle’s estimated daily Calorie expenditure?","o":["1500","1780","1930","2100","2450"],"a":1,"e":"Checked answer, not from an official key. 1,270 × 1.4 = about 1,780."},{"q":"The majority of cancers develop in:","o":["epithelial tissue.","lymph nodes.","adipocytes.","bones and bone marrow.","connective tissue"],"a":0,"e":"Checked answer, not from an official key. The textbook says most cancers develop in epithelial tissue."},{"q":"The areas of the body affected by cardiovascular diseases include the:","o":["heart.","brain.","blood vessels.","All of the above","a and c only"],"a":3,"e":"Checked answer, not from an official key. Cardiovascular disease includes heart disease, stroke and blood vessel disease."},{"q":"Which of the following is NOT a risk factor for coronary heart disease?","o":["HDL cholesterol < 40 mg/dL","Age 55 and older in women","Excess hip or thigh fat","Consumption of few whole-grain products","Diabetes"],"a":2,"e":"Checked answer, not from an official key. Belly fat raises risk, but hip and thigh fat doesn't."},{"q":"Metabolic syndrome is related to a cluster of metabolic abnormalities that include:","o":["low fasting blood glucose levels.","abdominal obesity.","low LDL levels.","high levels of HDL cholesterol.","All of the above"],"a":1,"e":"Checked answer, not from an official key. Belly fat is one of the criteria. The others are the reverse of the real criteria."},{"q":"Use the following information for questions 18-20.\n\nMr. Jones\nSex: Male\nHours of work: 55+/wk\nAge: 61\nOccupation: Computer programmer\nHousehold members: wife, 65 years old\nFamily Hx: coronary artery disease in father, had MI age 59\nSmoker: yes, 40 years, 1 pack/day\nHt = 70” Wt = 190 lbs\nBMI = 27\nWaist circumference: 43 inches\nCholesterol: 220 mg/dL; HDL-C 30 mg/dL; LDL-C 160 mg/dL; VLDL 45 mg/dL; TG 150 mg/dL\nBlood pressure: 140/85\nDiet history of Mr. Jones shows that he eats the following foods: Dairy products such as milk, cheese, and ice cream regularly. He consumes a variety of protein-rich foods including fish, shellfish, beef, poultry, and eggs; and large quantities of rice and potatoes; and he and his wife also frequently eat breads, crackers, and potato chips. Mr. Jones consumes a large variety of vegetables including eggplant, broccoli, mushrooms, onions, and tomatoes, although many of these are deep fried or cooked in butter.\n\nAccording to the BMI chart on page 519 Mr. Jones is:","o":["underweight","normal weight","overweight","severely obese"],"a":2,"e":"Checked answer, not from an official key. A BMI of 27 is in the overweight range (25–29.9)."},{"q":"Mr. Jones\nSex: Male\nHours of work: 55+/wk\nAge: 61\nOccupation: Computer programmer\nHousehold members: wife, 65 years old\nFamily Hx: coronary artery disease in father, had MI age 59\nSmoker: yes, 40 years, 1 pack/day\nHt = 70” Wt = 190 lbs\nBMI = 27\nWaist circumference: 43 inches\nCholesterol: 220 mg/dL; HDL-C 30 mg/dL; LDL-C 160 mg/dL; VLDL 45 mg/dL; TG 150 mg/dL\nBlood pressure: 140/85\nDiet history of Mr. Jones shows that he eats the following foods: Dairy products such as milk, cheese, and ice cream regularly. He consumes a variety of protein-rich foods including fish, shellfish, beef, poultry, and eggs; and large quantities of rice and potatoes; and he and his wife also frequently eat breads, crackers, and potato chips. Mr. Jones consumes a large variety of vegetables including eggplant, broccoli, mushrooms, onions, and tomatoes, although many of these are deep fried or cooked in butter.\n\nBased on the information above, what chronic disease is he at risk of developing?","o":["Coronary heart disease","Colon cancer","Type 2 diabetes","All of the above","a and c"],"a":3,"e":"Checked answer, not from an official key. Smoking, belly fat, low HDL, high LDL and his diet raise his risk of all three."},{"q":"Mr. Jones\nSex: Male\nHours of work: 55+/wk\nAge: 61\nOccupation: Computer programmer\nHousehold members: wife, 65 years old\nFamily Hx: coronary artery disease in father, had MI age 59\nSmoker: yes, 40 years, 1 pack/day\nHt = 70” Wt = 190 lbs\nBMI = 27\nWaist circumference: 43 inches\nCholesterol: 220 mg/dL; HDL-C 30 mg/dL; LDL-C 160 mg/dL; VLDL 45 mg/dL; TG 150 mg/dL\nBlood pressure: 140/85\nDiet history of Mr. Jones shows that he eats the following foods: Dairy products such as milk, cheese, and ice cream regularly. He consumes a variety of protein-rich foods including fish, shellfish, beef, poultry, and eggs; and large quantities of rice and potatoes; and he and his wife also frequently eat breads, crackers, and potato chips. Mr. Jones consumes a large variety of vegetables including eggplant, broccoli, mushrooms, onions, and tomatoes, although many of these are deep fried or cooked in butter.\n\nWhat dietary suggestions could you make to him to help decrease his risk factors?","o":["Decrease consumption of high-fat dairy products","Increase whole grain intake","Increase dietary fiber intake","Choose lean cuts of meat and poultry","All of the above"],"a":4,"e":"Checked answer, not from an official key. All four would help."}]},{"n":10,"title":"Nutrition and Older Adults","kicker":"Lesson 10 of your course, built from Chapters 18 and 19 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l10-b1","chapter":"Why we age","title":"Why we age","teach":["Life expectancy keeps rising, but the human life span stays at about 110–120 years. Programmed aging theories say aging is built in. One idea is that telomeres, the caps on the ends of chromosomes, get shorter with each cell division until cells can no longer divide. Hayflick found that human cells divide only about 40–60 times.","Other theories blame damage that builds up over time: free radicals harming cells, and proteins becoming cross-linked when glucose is high. Free radical damage is linked to heart disease, cataracts and some cancers."],"act":{"type":"choice","prompt":"Which idea is a programmed theory of aging?","options":[{"label":"Telomeres shorten with each cell division until cells can't replicate","correct":true,"feedback":"Yes. The molecular clock is a programmed theory."},{"label":"Free radicals damage cell membranes","correct":false,"feedback":"That's a damage (wear-and-tear) theory, not a programmed one."},{"label":"Fast-paced living shortens life","correct":false,"feedback":"That isn't one of the theories in the textbook."}]}},{"id":"l10-b2","chapter":"Energy and nutrient needs","title":"Energy and nutrient needs","teach":["Lower activity and a slower metabolism cut energy needs by about 7–10 Calories a year, or 70–100 a day over a decade. Vitamin and mineral needs stay the same or rise, and it's hard to meet them on fewer than 1,600 Calories a day. Staying active helps, and older adults gain just as much from exercise as younger people.","Many older adults absorb vitamin B12 poorly. Up to 30% have atrophic gastritis, where less stomach acid makes it hard to free B12 from food. Low B12 can cause memory problems and permanent nerve damage. Supplements made for older adults usually have more B12 and little or no iron."],"act":{"type":"number","prompt":"On 1,900 Calories, what is the most carbohydrate in grams that fits the AMDR of 45–65%? (Round up.)","answer":309,"tolerance":1,"unit":"g","explanation":"1,900 × 0.65 = 1,235 Calories. 1,235 ÷ 4 = 308.75, so 309 g. The low end is 1,900 × 0.45 ÷ 4 = 214 g."}},{"id":"l10-b3","chapter":"Body changes that affect eating","title":"Body changes that affect eating","teach":["With age, saliva gets thicker and there is less of it, appetite control is blunted, taste and smell fade, sex hormones drop, breathing capacity falls and blood flow drops. Total body water drops too, and thirst becomes less reliable, so dehydration is common. Drinking six or more glasses of fluid a day helps.","Signs of dehydration in older adults include confusion, a dry or furrowed tongue, sunken eyes, slurred speech and weakness in the arms or legs. Older adults are also at higher risk from foodborne illness, often from undercooked food or food held at the wrong temperature."],"act":{"type":"choice","prompt":"Which is NOT an age-related change that affects nutrition?","options":[{"label":"More saliva","correct":true,"feedback":"Right. Saliva usually decreases and thickens with age."},{"label":"Blunted appetite control","correct":false,"feedback":"This is a common change with age."},{"label":"Less blood flow","correct":false,"feedback":"Blood flow does decrease with age."}]}},{"id":"l10-b4","chapter":"Common conditions","title":"Common conditions","teach":["Hypertension is the only chronic condition more common in older adults than arthritis. Diabetes brings a tenfold higher risk of amputation, macular degeneration, cataracts and nerve damage. GERD causes heartburn and acid coming back up. Skipping alcohol and coffee and eating smaller, lower-fat meals can help.","Risk factors for osteoporosis include too little calcium, heavy drinking and low body weight. Men treated for prostate cancer with androgen deprivation can lose bone twice as fast. For lower stroke risk, the DASH, Mediterranean and Prudent diets all show benefits."],"act":{"type":"choice","prompt":"Which is NOT a risk factor for osteoporosis?","options":[{"label":"Low calcium intake","correct":false,"feedback":"This is a risk factor."},{"label":"Heavy drinking","correct":false,"feedback":"Heavy alcohol use is a risk factor."},{"label":"High iron intake","correct":true,"feedback":"Right. Iron isn't one of the listed risk factors."}]}},{"id":"l10-b5","chapter":"Unplanned weight loss","title":"Unplanned weight loss","teach":["Unplanned weight loss is a red flag in older adults. Compare current weight with usual weight: current ÷ usual × 100. Protein needs for older adults are about 1.0–1.5 g per kg of body weight a day.","To help, offer small, frequent meals and snacks with more Calories and protein, a protein and energy supplement if needed, and gentle strength exercise to rebuild muscle. Avoid foods that cause discomfort."],"act":{"type":"number","prompt":"A woman usually weighs 140 lb and now weighs 119 lb. What percent of her usual weight is she?","answer":85,"tolerance":0,"unit":"%","explanation":"119 ÷ 140 × 100 = 85% of her usual weight."}}],"flashcards":[{"front":"Human life span","back":"About 110–120 years."},{"front":"Programmed aging: telomeres","back":"Telomeres shorten with each cell division until chromosomes can no longer replicate."},{"front":"Drop in energy needs with age","back":"About 7–10 Calories a year."},{"front":"Hard to meet vitamin and mineral needs below…","back":"1,600 Calories a day."},{"front":"Main cause of poor B12 status in older adults","back":"Atrophic gastritis: less stomach acid, so B12 isn't freed from food."},{"front":"Supplements for older adults","back":"More B12 and little or no iron."},{"front":"Effects of B12 deficiency","back":"Memory problems and permanent nerve damage."},{"front":"Body water with age","back":"Decreases. Thirst is less reliable."},{"front":"More common than arthritis in older adults","back":"Hypertension."},{"front":"Diabetes: tenfold higher risk of…","back":"Amputation, macular degeneration, cataracts and nerve damage."},{"front":"Main symptoms of GERD","back":"Heartburn and acid regurgitation."},{"front":"Prostate cancer treatment and bone","back":"Bone loss can double with androgen deprivation."},{"front":"Diets linked to less stroke","back":"DASH, Mediterranean and Prudent diets."},{"front":"Protein for older adults","back":"About 1.0–1.5 g per kg per day."}],"quiz":[{"q":"The human life span is projected to be ______________ years.","o":["102-104","105-110","110-120",">120"],"a":2,"e":"Checked answer, not from an official key. The textbook says about 110–120 years."},{"q":"Programmed aging theories propose that senescence occurs because","o":["the telomeres capping the ends of chromosomes become shorter with each cell division and their loss eventually stops the chromosomes from replicating.","mistakes in the replication of cells or buildup of damaging by-products from biologic processes eventually destroy the organism.","unstable oxygen, formed normally during metabolism, can damage cells by initiating reactions that break down cell membranes.","fast-paced living shortens one’s lifespan."],"a":0,"e":"Checked answer, not from an official key. The telomere (molecular clock) idea is a programmed theory. The others are damage theories."},{"q":"A decrease in physical activity and basal metabolic rate from early to late adulthood leads to an estimated decrease in daily energy needs by ____________ Calories per year.","o":["7-10","12-15","20-23","25-28","34-37"],"a":0,"e":"Checked answer, not from an official key. The textbook gives 7–10 Calories a year."},{"q":"It is difficult to meet vitamin and mineral needs via foods at Calorie levels below","o":["1300.","1600.","1800.","2000.","It is hard to meet vitamin and mineral needs at ANY calorie level; therefore, a multivitamin is ALWAYS recommended."],"a":1,"e":"Checked answer, not from an official key. The textbook says below 1,600 Calories."},{"q":"Age-associated physiological system changes that affect nutritional health include all of the following EXCEPT:","o":["increased secretion of saliva","reduced levels of estrogen and testosterone.","blunted appetite regulation.","reduced breathing capacity.","less blood flow."],"a":0,"e":"Checked answer, not from an official key. Saliva decreases and thickens with age."},{"q":"Which statement describes how physiologic doses found in a vitamin-mineral supplement for the elderly differ from doses in supplements for the general adult population?","o":["Additional vitamin B12 is added","Little or no iron is added","Decrease in zinc","Additional vitamin E is added","a and b"],"a":4,"e":"Checked answer, not from an official key. Supplements for older adults usually have more B12 and little or no iron."},{"q":"A short-stature female (5’2”) was not consistently eating two or three meals a day. She usually had a piece of toast and coffee with cream and sugar at breakfast and never could quite eat all of her home-delivered noon meal. What dietary supplement would you recommend?","o":["Multi-vitamin/mineral that is physiologically designed for elderly","Calcium supplement only","Folate, vitamin B12, and iron only","Calcium and magnesium only"],"a":0,"e":"Checked answer, not from an official key. Her intake is low overall, so a broad supplement made for older adults fits best."},{"q":"What is the most common reason that vitamin B12 deficiency, or at least compromised B12 status, occurs in older adults?","o":["Diets are frequently low in vitamin B12, since oral problems and financial difficulties limit meat intake and meats are the best dietary sources of B12.","Pernicious anemia is common in the elderly.","Their diets provide primarily synthetic forms of vitamin B12, which are less absorbable than the protein-bound form found naturally in foods.","The elderly have a higher incidence of bacterial overgrowth, which decreases secretion of hydrochloric acid.","None of the above"],"a":3,"e":"Checked answer, not from an official key. Atrophic gastritis, with bacterial overgrowth and less stomach acid, affects up to 30% of older adults."},{"q":"Failing to cook foods long enough and to hold them at proper temperatures before consumption are among the most common practices that lead to foodborne illness among older adults.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Undercooking and poor temperature control are common causes."},{"q":"Older people do NOT benefit from exercise as much as younger people.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Older adults benefit from exercise just as much."},{"q":"The recommended Calorie intake for energy for females between the ages of 60 and 74 is 1900 Calories. Calculate how many grams of carbohydrate they should consume to meet the AMDR. (Round up.)","o":["130-145","175-220","215-310","400-550"],"a":2,"e":"Checked answer, not from an official key. 1,900 × 0.45 ÷ 4 = 214 and 1,900 × 0.65 ÷ 4 = 309. Rounded up, that's about 215–310 g."},{"q":"The amount of stored body water decreases with age.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Body water drops with age, which raises the risk of dehydration."},{"q":"The only chronic condition that has higher prevalence in older adults than arthritis is:","o":["diabetes.","hypertension.","cancer.","stroke.","osteoporosis."],"a":1,"e":"Checked answer, not from an official key. The textbook says hypertension is the only one."},{"q":"Diabetes leads to a tenfold greater risk of all of the following EXCEPT:","o":["amputations.","neuropathies.","macular degeneration.","cataracts.","elevated blood lipids."],"a":4,"e":"Checked answer, not from an official key. The textbook lists amputations, macular degeneration, cataracts and neuropathies."},{"q":"Which of the following is NOT a risk factor for osteoporosis?","o":["Inadequate calcium intake","Heavy alcohol consumption","Low body weight","High iron intake"],"a":3,"e":"Checked answer, not from an official key. Iron intake isn't a listed risk factor."},{"q":"An elderly man who is 75 years old and recently had prostate cancer treatments would likely have:","o":["a doubling of bone mass loss.","a slowing of bone mass loss.","a twenty-five percent chance of mortality within 6 months.","a fifty percent chance of mortality within 1 year."],"a":0,"e":"Checked answer, not from an official key. The textbook says bone loss doubles when androgen deprivation starts."},{"q":"The main symptoms of GERD include:","o":["heartburn.","acid regurgitation.","bloating and cramping.","All of the above","a and b only"],"a":4,"e":"Checked answer, not from an official key. The textbook names heartburn and regurgitation."},{"q":"A deficiency in vitamin B12 may lead to:","o":["irreversible neurological damage.","cognitive impairment.","constipation.","a and b","b and c"],"a":3,"e":"Checked answer, not from an official key. Low B12 can cause permanent nerve damage and memory problems."},{"q":"Seven signs and symptoms have been strongly related to dehydration in the elderly. Which of the following would NOT be one of these?","o":["Hearing difficulty","Confusion","Dry tongue","Sunken appearance of eyes","Upper-body weakness"],"a":0,"e":"Checked answer, not from an official key. Confusion, a dry tongue, sunken eyes and weakness are signs. Hearing difficulty isn't."},{"q":"Which of the following is NOT one of the diets that was correlated with reduced stroke incidence?","o":["DASH diet","South Beach Diet","The Prudent Diet","Mediterranean Diet"],"a":1,"e":"Checked answer, not from an official key. The DASH, Prudent and Mediterranean diets are linked to less stroke."},{"q":"Use the following information to answer questions 22-25.\n\nA 75-year-old female reports having lost 20 pounds in the last 3 months and now weighs 100 pounds; she is 5’3”. She is complaining that food has lost its taste, and when she does eat, she develops severe heartburn. She is now in your office for assessment. Her daily intake is ~1000 Calories with 35 g of protein.\n1 cup non-fat milk\n1 medium apple\n1 slice bread + 3 t. butter\n1 cup black coffee + 3 t. sugar\n1/3 cup cooked rice\n1/2 cup cooked zucchini\n2 oz. ground beef\n1 cup orange juice\n1 oz. Cheddar cheese\nBlack coffee\n2 martinis before dinner.\n\nHow does her current weight compare to her usual weight?","o":["She is 77% of her usual body weight","She is 83% of her usual body weight","She is 94% of her usual body weight","She is 120% of her usual body weight"],"a":1,"e":"Checked answer, not from an official key. Her usual weight was 120 lb. 100 ÷ 120 × 100 = 83%."},{"q":"A 75-year-old female reports having lost 20 pounds in the last 3 months and now weighs 100 pounds; she is 5’3”. She is complaining that food has lost its taste, and when she does eat, she develops severe heartburn. She is now in your office for assessment. Her daily intake is ~1000 Calories with 35 g of protein.\n1 cup non-fat milk\n1 medium apple\n1 slice bread + 3 t. butter\n1 cup black coffee + 3 t. sugar\n1/3 cup cooked rice\n1/2 cup cooked zucchini\n2 oz. ground beef\n1 cup orange juice\n1 oz. Cheddar cheese\nBlack coffee\n2 martinis before dinner.\n\nHow does her intake compare to her estimated protein needs?","o":["It is low; based on her current weight, she should be consuming at least 100 g per day.","It is high; based on her current weight, she should be consuming at least 25 g per day.","It is low; based on her current weight, she should be consuming between 45 and 70 g per day.","It is adequate to meet her needs based on her current weight and Calorie intake."],"a":2,"e":"Checked answer, not from an official key. At 45 kg and 1.0–1.5 g per kg, she needs about 45–70 g, so 35 g is low."},{"q":"A 75-year-old female reports having lost 20 pounds in the last 3 months and now weighs 100 pounds; she is 5’3”. She is complaining that food has lost its taste, and when she does eat, she develops severe heartburn. She is now in your office for assessment. Her daily intake is ~1000 Calories with 35 g of protein.\n1 cup non-fat milk\n1 medium apple\n1 slice bread + 3 t. butter\n1 cup black coffee + 3 t. sugar\n1/3 cup cooked rice\n1/2 cup cooked zucchini\n2 oz. ground beef\n1 cup orange juice\n1 oz. Cheddar cheese\nBlack coffee\n2 martinis before dinner.\n\nWhat dietary changes might help with her heartburn?","o":["Skipping the martinis before dinner","Avoiding coffee","Changing her milk to whole vs. non-fat","All of the above","a and b only"],"a":4,"e":"Checked answer, not from an official key. Alcohol and coffee can worsen heartburn. Higher-fat milk wouldn't help."},{"q":"A 75-year-old female reports having lost 20 pounds in the last 3 months and now weighs 100 pounds; she is 5’3”. She is complaining that food has lost its taste, and when she does eat, she develops severe heartburn. She is now in your office for assessment. Her daily intake is ~1000 Calories with 35 g of protein.\n1 cup non-fat milk\n1 medium apple\n1 slice bread + 3 t. butter\n1 cup black coffee + 3 t. sugar\n1/3 cup cooked rice\n1/2 cup cooked zucchini\n2 oz. ground beef\n1 cup orange juice\n1 oz. Cheddar cheese\nBlack coffee\n2 martinis before dinner.\n\nWhat other suggestions could you give her to help prevent weight loss and increase protein in her diet?","o":["Eat more calories throughout day","Exercise to help build muscle mass","Try a protein and energy supplement","Avoid foods that irritate you","All of the above"],"a":4,"e":"Checked answer, not from an official key. All four help prevent more weight loss."}]},{"n":11,"title":"The Counselling Relationship","kicker":"Lesson 11 of your course, built from Chapter 1 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l11-b1","chapter":"Counselling and education","title":"Counselling and education","teach":["Nutrition education and nutrition counselling share the same aim: helping people choose foods that support their health. The difference is who the work is shaped around. Nutrition education is designed around the needs of a group or community. Nutrition counselling is shaped around one client and is built on a working partnership between the counsellor and that client.","In counselling, you pay attention to the client's experience, feelings, thoughts and behaviour, and you respond on purpose: to acknowledge, to explore or to gently challenge. Your job is to increase knowledge, influence motivation and help the client build the skills they need to change how they eat."],"act":{"type":"choice","prompt":"A Nutritionist runs a six-week cooking class for a community centre. Which kind of work is this mainly?","options":[{"label":"Nutrition education","correct":true,"feedback":"Yes. The class is planned around the needs of a group, which is what makes it education."},{"label":"Nutrition counselling","correct":false,"feedback":"Counselling is shaped around one client and their own goals. A class for a community is education."},{"label":"Neither","correct":false,"feedback":"It is nutrition education: learning experiences planned for a group."}]}},{"id":"l11-b2","chapter":"What shapes food choices","title":"What shapes food choices","teach":["Before you can help someone change, you need to understand why they eat the way they do. Many forces pull on food choices at once, and they often compete. Taste is generally seen as the strongest one. Taste preferences can change with age, a move or illness, which is good news for anyone trying to change their diet.","Other influences include habit, health concerns, nutrition knowledge, convenience and time, culture and religion, the people we eat with, advertising and what is around us, money and access, how much variety is on offer, and stress or mood. People with more nutrition knowledge tend to eat better and lose more weight in weight-loss programs, so teaching still matters. Advice also lands better when it stresses that healthy food tastes good and is easy to fit in."],"act":{"type":"sort","prompt":"Match each situation with the main influence on the food choice.","categories":["Social influences","Economics","Culture and religion","Convenience and time"],"items":[{"label":"He orders wings because his friends always do after the game.","category":0,"feedback":"Eating with friends shapes what and how much we eat."},{"label":"She buys most of her groceries at the dollar store near the bus stop.","category":1,"feedback":"Income and transportation affect which stores and foods are within reach."},{"label":"Her family never eats pork.","category":2,"feedback":"Religion and culture define which foods are acceptable."},{"label":"He picks up takeout most nights because he has twenty minutes to make dinner.","category":3,"feedback":"Little time pushes people toward quick, ready-made food."}]}},{"id":"l11-b3","chapter":"What makes an effective counsellor","title":"What makes an effective counsellor","teach":["The relationship between counsellor and client is the main driver of change. Clients who succeed often say the relationship was the most important part of their care.","From a review of the counselling research, Okun named seven qualities that matter most: knowledge, self-awareness, ethical integrity, congruence, honesty, the ability to communicate, and awareness of gender and culture. Nutrition counselling writers add a sense of humour, flexibility, optimism, respect for others and empathy. Congruence means what you say matches who you are and how you act, including your body language. No one has all of these perfectly. They are qualities to keep working on."],"act":{"type":"choice","prompt":"A client describes an unusual eating habit. The counsellor says “I see” calmly, but her face shows shock. Which quality is missing?","options":[{"label":"Congruence","correct":true,"feedback":"Right. Her words and her body language don't match, so she isn't congruent."},{"label":"Knowledge","correct":false,"feedback":"Knowledge is about what she knows. The problem here is the mismatch between her words and her face."},{"label":"Flexibility","correct":false,"feedback":"Flexibility is about pace and expectations. The problem is that her words and her face don't match."}]}},{"id":"l11-b4","chapter":"Know yourself first","title":"Know yourself first","teach":["Your personality is one of the main tools you bring to counselling, so it helps to know it well. Ask yourself honestly why you want to help. Counsellors who need to feel in control tend to lecture and stop listening. Counsellors who need to be liked may avoid hard topics and do too much for the client, so the client never learns new skills.","Your worldview, the outlook you get from your culture and life, shapes how you see health, illness and food. Culture is the shared history of racial, ethnic, religious or other social groups, such as gender, age, occupation or income level. Everyone belongs to several groups, so no two people share exactly the same culture. Knowing your own values and biases helps keep them from leaking into your sessions."],"act":{"type":"choice","prompt":"Which counsellor message is most likely to help the client?","options":[{"label":"“I want you to like me.”","correct":false,"feedback":"A counsellor who needs approval tends to avoid difficult issues, so real change doesn't happen."},{"label":"“I am here to help you.”","correct":true,"feedback":"Yes. The focus stays on the client, not on the counsellor's own needs."},{"label":"“Just do what I tell you.”","correct":false,"feedback":"A counsellor who needs control tends to dictate and stops listening."}]}},{"id":"l11-b5","chapter":"Understanding your client","title":"Understanding your client","teach":["Clients come with their own personality, culture, health problems, worries and expectations. Learn about the cultures your clients come from, but remember that what is true of a group is only a generality. It may or may not fit the person in front of you. Avoid stereotyping.","Timing matters too. Someone who has just been given a serious diagnosis may be in shock, angry or in denial, and not ready for detailed diet advice. Self-sufficiency is often a goal, but not always: some clients prefer a more guided role, and some need ongoing support. Asking for help can also make people feel vulnerable or less capable, so explain clearly why you are there and what the work involves."],"act":{"type":"choice","prompt":"You read that people from a certain culture prefer formal greetings. What should you do with that information?","options":[{"label":"Use it as background, and watch how this client actually prefers to be treated.","correct":true,"feedback":"Yes. Group traits are generalities that may or may not fit the individual."},{"label":"Treat every client from that culture formally, no matter what.","correct":false,"feedback":"That is stereotyping. People take on all, some or none of the habits of a culture they seem to belong to."},{"label":"Ignore it, since culture doesn't affect counselling.","correct":false,"feedback":"Culture shapes how clients see health, food and professionals, so it is worth learning about."}]}},{"id":"l11-b6","chapter":"Two phases of the helping relationship","title":"Two phases of the helping relationship","teach":["The helping relationship has two phases. In the first, you build the relationship: rapport, empathy and trust. The goals are to learn about the problem from the client's point of view, find their strengths and help them explore.","In the second phase, you help the client pick specific behaviours to change and plan realistic ways to change them. Skipping the first phase is a common mistake. Without it, you may end up solving the wrong problem, and the plan is unlikely to work."],"act":{"type":"sort","prompt":"Sort each task into the phase it belongs to.","categories":["Phase 1: building the relationship","Phase 2: facilitating positive action"],"items":[{"label":"Learning about the problem from the client's point of view","category":0,"feedback":"This is the focus of the first phase."},{"label":"Exploring the client's strengths","category":0,"feedback":"Finding strengths is part of building the relationship."},{"label":"Choosing specific behaviours to change","category":1,"feedback":"This comes once the relationship and the problem are clear."},{"label":"Designing realistic behaviour change strategies","category":1,"feedback":"Planning the change belongs to the second phase."}]}},{"id":"l11-b7","chapter":"Why “everything will be fine” falls flat","title":"Why “everything will be fine” falls flat","teach":["Telling a client that everything will be fine sounds kind, but it has no basis yet. It brushes aside how they feel, and any comfort it gives fades because nothing has been solved. It can also sound patronizing, as if you are above them.","In the textbook's example, a fitness counsellor named Joe weighs his new client Lilly, decides she needs to lose 20 pounds, and signs her up for classes before she can finish a sentence. She came for more energy and stamina. Real reassurance comes from explaining your role, looking for possible solutions together and explaining how the program works."],"act":{"type":"choice","prompt":"Lilly says she gets tired quickly and wants more stamina. What would be a better first response from Joe?","options":[{"label":"“Tell me more about when you feel tired and what you'd like to be able to do.”","correct":true,"feedback":"Yes. This learns about the problem from her point of view before planning anything."},{"label":"“Don't worry, everything will be fine. Let's get you on the scale.”","correct":false,"feedback":"Empty reassurance brushes past her concern, and the scale wasn't what she came for."},{"label":"“Take some power bars home. They're great for beginners.”","correct":false,"feedback":"This jumps to a solution before understanding her goals."}]}},{"id":"l11-b8","chapter":"Issues for new counsellors","title":"Issues for new counsellors","teach":["New counsellors often worry about whether they know enough. That worry can lead to vague answers on controversial topics, like a politician who won't take a stand. If you don't know, say you will look into it. If the evidence is still mixed, share the pros and cons fairly.","Another trap is picking only one role. The expert gives answers that clients follow for a while without working out how to make change fit their life. The empathizer listens so much that the client gets little direction. Effective counsellors learn to combine the two. Confidence grows with experience."],"act":{"type":"choice","prompt":"A client asks whether high-protein diets are a good way to lose weight, and you haven't looked into it. What should you say?","options":[{"label":"“Some people say they lose weight on them.”","correct":false,"feedback":"This dodges the question without taking a stand or giving useful information."},{"label":"“I haven't looked into that closely. I'll review it and tell you what I find, including the pros and cons.”","correct":true,"feedback":"Yes. You are honest about what you know and commit to giving balanced information."},{"label":"“They don't work. Next question.”","correct":false,"feedback":"Giving a firm answer you haven't checked isn't honest or balanced."}]}}],"flashcards":[{"front":"Nutrition education","back":"Learning experiences planned for a group or community to help people choose foods and habits that support health."},{"front":"Nutrition counselling","back":"A supportive, collaborative process with one client to set food, nutrition and activity priorities, goals and a personal action plan."},{"front":"Most important influence on food choices","back":"Taste (sensory appeal)."},{"front":"Advice is more likely to work when it stresses…","back":"The good taste of wholesome foods and convenient ways to include them in the diet."},{"front":"Okun's seven counsellor qualities","back":"Knowledge, self-awareness, ethical integrity, congruence, honesty, ability to communicate, and gender and culture awareness."},{"front":"Congruence","back":"No contradiction between who the counsellor is, what they say and how they act, including body language."},{"front":"Two counsellor needs that can harm counselling","back":"A need for power or control (leads to dictating) and a need for approval (leads to avoiding hard issues and doing too much for the client)."},{"front":"Worldview","back":"A cultural outlook: the basic beliefs a group holds about reality, which shape views on health, illness and food."},{"front":"Culture","back":"The shared history of racial, ethnic, religious or other social groups, including their thoughts, customs, beliefs, values and institutions."},{"front":"Cultural values","back":"The principles or standards that members of a cultural group share."},{"front":"Phase 1 of the helping relationship","back":"Building the relationship: rapport, empathy and trust. Learn about the problem from the client's point of view and explore strengths."},{"front":"Phase 2 of the helping relationship","back":"Facilitating positive action: choose specific behaviours to change and plan realistic strategies."},{"front":"Why not say “everything will be fine”?","back":"It has no basis, brushes aside the client's feelings and can sound patronizing. Reassure by explaining your role, finding solutions and explaining the program."},{"front":"Three issues for new counsellors","back":"Worrying about competence, giving vague answers on controversial topics, and relying on only the expert role or only the empathizer role."}],"quiz":[{"q":"_______________ has been defined as “any set of learning experiences designed to facilitate the voluntary adoption of eating and other nutrition-related behaviours conducive to health and well-being.”","o":["Nutrition education","Nutrition counselling","Nutrition culture","Nutrition behaviour"],"a":0,"e":"Checked answer, not from an official key. This describes nutrition education, which is planned around the needs of a group."},{"q":"Nutrition professionals work to","o":["increase knowledge.","influence motivations.","guide development of skills required for dietary behaviour change.","All of the above"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 lists all three as part of the job."},{"q":"Those with ______________ are more likely to have better quality diets and lose more weight in weight loss programs.","o":["more money","higher levels of knowledge","strong willpower","All of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook says people with more nutrition knowledge tend to have better diets and lose more weight."},{"q":"Consumers are more likely to respond to healthful food messages if the advice stresses","o":["the good taste of wholesome foods.","convenient ways to include wholesome foods in the diet.","the low cost of wholesome foods.","All of the above","A and B"],"a":4,"e":"Checked answer, not from an official key. The textbook names good taste and convenient ways to include wholesome foods. It doesn't mention cost."},{"q":"A counsellor’s personality","o":["is one of the principle tools of the helping process.","plays a minor role in the helping process.","is not relevant to the helping process."],"a":0,"e":"Checked answer, not from an official key. The textbook calls personality one of the main tools of the helping process."},{"q":"People from all cultures appreciate a friendly, open health care professional.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Many North Americans do, but people from some cultures find it uncomfortable and may even see it as a sign of incompetence."},{"q":"“Culture” is the shared history of _____________ groups.","o":["racial","gender","religious","occupational","Any of the above"],"a":4,"e":"Checked answer, not from an official key. Culture comes from racial, ethnic, religious or other social groups, and social groups include gender and occupation."},{"q":"The characteristics of a cultural group","o":["apply to all people within that group.","are generalities that may or may not apply to individuals within that group."],"a":1,"e":"Checked answer, not from an official key. Group traits are generalities. Assuming they fit everyone is stereotyping."},{"q":"Promoting self-sufficiency is always a main goal of nutrition counselling.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. It is often a goal, but for some clients it needs to change. Some prefer a guided role or need ongoing support."},{"q":"What is the focus of the first phase of the counselling process?","o":["Helping clients identify specific behaviours to alter","Designing realistic behavior change strategies","Learning about the nature of the problem from the client’s viewpoint","All of the above"],"a":2,"e":"Checked answer, not from an official key. The first phase builds the relationship and learns about the problem from the client's view. Choosing behaviours and planning strategies come in the second phase."}]},{"n":12,"title":"Behaviour Change Models and Theories","kicker":"Lesson 12 of your course, built from Chapter 2 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l12-b1","chapter":"Why theories matter, and self-efficacy","title":"Why theories matter, and self-efficacy","teach":["Behaviour change theories help you understand why people eat the way they do and choose approaches that are more likely to work. No single theory fits every client, so counsellors often mix ideas from several.","One idea shows up in almost all of them: self-efficacy, or a person's confidence that they can make a change. It affects the choices people make, how much effort they put in, how they see barriers and whether they keep going when things get hard. A person's confidence in their ability to change may matter more than their actual skill."],"act":{"type":"choice","prompt":"Two clients know equally well how to plan meals. One is sure she can do it, the other doubts herself. Who is more likely to change?","options":[{"label":"The confident client","correct":true,"feedback":"Yes. Self-efficacy can matter more than actual skill."},{"label":"Both equally, since their skills are the same","correct":false,"feedback":"Confidence affects effort and persistence, so skill alone doesn't decide it."},{"label":"The doubtful client, because she'll try harder","correct":false,"feedback":"Low confidence usually means less effort and giving up sooner when obstacles come up."}]}},{"id":"l12-b2","chapter":"The Health Belief Model","title":"The Health Belief Model","teach":["The Health Belief Model says people are more likely to act when they believe they are at risk (perceived susceptibility), believe the problem would be serious (perceived severity), believe that acting will help (perceived benefits), and believe the obstacles are manageable (perceived barriers). Severity includes physical and social effects, such as the impact on work or money.","Cues to action are the nudges that get someone started: physical symptoms, seeing someone else take action, a media report, or a doctor's advice. You and your client can also plan your own cues, such as a note on the fridge. Self-efficacy was later added to the model too."],"act":{"type":"sort","prompt":"Match each thought with the Health Belief Model idea it shows.","categories":["Perceived susceptibility","Perceived severity","Perceived barriers","Cue to action"],"items":[{"label":"“Heart disease runs in my family, so I could get it.”","category":0,"feedback":"Believing you are at risk is perceived susceptibility."},{"label":"“If I had a heart attack, I couldn't work and pay my bills.”","category":1,"feedback":"Seeing serious physical or financial effects is perceived severity."},{"label":"“Cooking from scratch takes too much time.”","category":2,"feedback":"Obstacles like time, cost or taste are perceived barriers."},{"label":"“My doctor told me to cut back on salt.”","category":3,"feedback":"A doctor's advice can be a cue to action."}]}},{"id":"l12-b3","chapter":"Stages of change","title":"Stages of change","teach":["The Transtheoretical Model describes change as a series of stages. In precontemplation, the person isn't thinking about changing. In contemplation, they are thinking about it, usually within the next six months, but they're stuck weighing pros and cons. People can stay in contemplation for years, waiting for certainty or a “magic moment”. Then come preparation, action and maintenance.","Decisional balance is the weighing of pros and cons. In precontemplation the cons clearly win, and in contemplation they are about even. Self-efficacy tends to drop between precontemplation and contemplation, as people start to see how hard the change will be, and then it rises gradually through action and maintenance."],"act":{"type":"choice","prompt":"A client says, “I know I should eat better, and I'll probably start sometime this year, but it's just not the right time.” Which stage is this?","options":[{"label":"Precontemplation","correct":false,"feedback":"She is already thinking about changing, so she has moved past precontemplation."},{"label":"Contemplation","correct":true,"feedback":"Yes. She is thinking about it but waiting for the right moment."},{"label":"Action","correct":false,"feedback":"She hasn't started making changes yet."}]}},{"id":"l12-b4","chapter":"Planned behaviour and Social Cognitive Theory","title":"Planned behaviour and Social Cognitive Theory","teach":["The Theory of Planned Behaviour looks at intention. A person is more likely to act when they have a positive attitude toward the behaviour, feel that people who matter to them support it, and feel they have control over doing it.","Social Cognitive Theory goes beyond the individual. It includes a person's relationship with social groups and the environment. It describes reciprocal determinism: the person, their behaviour and their environment all affect each other. For example, a husband's high blood pressure (environment) motivates his wife to learn about food (person), so she starts eating more vegetables (behaviour). Ways to build self-efficacy include social modelling, verbal persuasion and helping the person feel better physically and emotionally."],"act":{"type":"choice","prompt":"Which theory looks at a person's relationship with social groups and the environment?","options":[{"label":"Health Belief Model","correct":false,"feedback":"The Health Belief Model focuses on the person's own beliefs about risk, severity, benefits and barriers."},{"label":"Social Cognitive Theory","correct":true,"feedback":"Yes. It looks at how the person, their behaviour and the environment influence each other."},{"label":"Transtheoretical Model","correct":false,"feedback":"This model describes stages of readiness, not social groups and the environment."}]}},{"id":"l12-b5","chapter":"Cognitive-behavioural approaches","title":"Cognitive-behavioural approaches","teach":["Cognitive-behavioural therapy works on both thoughts and actions. The cognitive part helps clients notice and change unhelpful thinking, such as “I ate one cookie, so the whole day is ruined.”","The behavioural part changes actions directly. Classical conditioning pairs a cue with a response. Operant conditioning is based on the law of effect: behaviours can be changed by their positive or negative effect. In nutrition counselling, the positive side is usually used, such as a reward for reaching a goal. Sometimes the change is its own reward, like relief from constipation after drinking more fluids and eating more fibre."],"act":{"type":"choice","prompt":"A client treats herself to a new cookbook after a month of packing lunches. Which approach is this?","options":[{"label":"Operant conditioning","correct":true,"feedback":"Yes. A reward strengthens the behaviour, which is the law of effect."},{"label":"Classical conditioning","correct":false,"feedback":"Classical conditioning pairs a cue with a response. This is a reward after a behaviour."},{"label":"Modelling","correct":false,"feedback":"Modelling means learning by watching someone else."}]}},{"id":"l12-b6","chapter":"Client-centred and solution-focused counselling","title":"Client-centred and solution-focused counselling","teach":["Client-centred counselling, from Carl Rogers, guides how to build a good counselling relationship: warmth, genuineness, acceptance and empathy. Many practitioners use its basics no matter which other approach they follow.","Solution-focused therapy spends less time on the problem and more on what is already working. It looks for exceptions (times the problem didn't happen) and builds on the client's strengths and past successes."],"act":{"type":"choice","prompt":"Which question fits a solution-focused approach?","options":[{"label":"“Why do you think you overeat at night?”","correct":false,"feedback":"This digs into the problem rather than what works."},{"label":"“Tell me about a night this week when snacking wasn't a problem. What was different?”","correct":true,"feedback":"Yes. Looking for exceptions and building on them is the heart of this approach."},{"label":"“How many calories do you eat after dinner?”","correct":false,"feedback":"This gathers facts but doesn't look for what's already working."}]}},{"id":"l12-b7","chapter":"Motivational interviewing","title":"Motivational interviewing","teach":["Motivational interviewing (MI) helps people resolve ambivalence, the feeling of wanting to change and not wanting to at the same time. Its spirit is a partnership with the client rather than an expert telling them what to do. It assumes people already have reasons to change, and your job is to draw them out (evocation), while respecting that the choice is theirs (autonomy). Your course test describes the three parts as collaboration, evocation and autonomy.","Core MI skills are open-ended questions, affirmations, reflections and summaries. The aim is for the client, not you, to make the case for change. This is called change talk. As the client voices their own need for change and the gap between their behaviour and their values grows, the balance of indecision starts to tip toward action."],"act":{"type":"choice","prompt":"Which counsellor move is most in the spirit of motivational interviewing?","options":[{"label":"Listing all the health risks so the client sees why she must change","correct":false,"feedback":"Trying to convince the client tends to create pushback. MI lets the client make the case."},{"label":"Asking, “What would be different for you if you made this change?”","correct":true,"feedback":"Yes. An open question that draws out the client's own reasons encourages change talk."},{"label":"Telling the client which change to start with","correct":false,"feedback":"MI respects the client's choice and works in partnership."}]}}],"flashcards":[{"front":"Self-efficacy","back":"A person's confidence that they can make a change. It may matter more than actual skill."},{"front":"Health Belief Model: perceived susceptibility","back":"Believing you are at risk of the problem."},{"front":"Health Belief Model: perceived severity","back":"Believing the problem would have serious physical or social effects, including on money or work."},{"front":"Health Belief Model: perceived barriers","back":"The obstacles a person sees, such as taste, cost or inconvenience."},{"front":"Cues to action","back":"Prompts to act, such as physical symptoms, seeing others act, a media report or a doctor's advice."},{"front":"Contemplation stage","back":"Thinking about changing, usually within six months. People can be stuck here for years waiting for the “magic moment”."},{"front":"Self-efficacy across the stages of change","back":"It tends to drop from precontemplation to contemplation, then rises through action and maintenance."},{"front":"Decisional balance","back":"Weighing the pros and cons of changing."},{"front":"Social Cognitive Theory","back":"Looks at the person, their behaviour and the environment, including social groups, and how they affect each other (reciprocal determinism)."},{"front":"Ways to build self-efficacy (SCT)","back":"Social modelling, verbal persuasion, and improving physical and emotional states."},{"front":"Operant conditioning","back":"Based on the law of effect: behaviours change through their positive or negative effects."},{"front":"Solution-focused therapy","back":"Focuses on exceptions and what is already working rather than on the problem."},{"front":"Spirit of motivational interviewing (course test)","back":"Collaboration, evocation and autonomy."},{"front":"Change talk","back":"The client's own statements in favour of change. As it grows, the balance shifts toward action."}],"quiz":[{"q":"A person’s confidence in his or her ability to accomplish a behaviour change may be more important than actual skill.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says this about self-efficacy almost word for word."},{"q":"Which behaviour change theory incorporates a person’s relationship with social groups and the environment?","o":["Health belief model","Transtheoretical model","Theory of planned behaviour","Social cognitive theory","All of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook says Social Cognitive Theory looks beyond the individual to social groups and the environment."},{"q":"In the Health Belief Model, physical symptoms, a media report, or advice of a physician can all be cues to action.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. The textbook lists all three as cues to action."},{"q":"Which Health Belief Construct is the perception that heart disease can negatively affect a person’s financial status?","o":["Cue to Action","Perceived Susceptibility","Perceived Severity","Perceived Barrier"],"a":2,"e":"Checked answer, not from an official key. Perceived severity covers the physical and social effects of a condition, including effects on money."},{"q":"In the Transtheoretical Model, people can be stuck in which stage for years, waiting for the “magic moment”?","o":["Precontemplation","Contemplation","Preparation","Action","Maintenance"],"a":1,"e":"Checked answer, not from an official key. The textbook says this about the contemplation stage."},{"q":"Self-efficacy tends to increase for individuals between the precontemplation and contemplation stages.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. It tends to decrease between these stages, as people start to see how hard the change will be."},{"q":"A__________ is based on the law of effect, which states that behaviours can be changed by their positive or negative effect.","o":["Modelling","Classical conditioning","Operant conditioning","Systematic densensitization"],"a":2,"e":"Checked answer, not from an official key. The textbook defines operant conditioning this way."},{"q":"Social modelling, verbal persuasion, and improving physical and emotional states are intervention strategies for which Social Cognitive Theory concept?","o":["Behavioural capacity","Self-efficacy","Observational learning","Facilitation"],"a":1,"e":"Checked answer, not from an official key. These are the classic ways to build self-efficacy."},{"q":"Collaboration, evocation, and autonomy are the three components of _____________.","o":["solution-focused therapy","behavioural therapy","cognitive therapy","motivational interviewing."],"a":3,"e":"Checked answer, not from an official key. These describe the spirit of motivational interviewing. The 7th edition describes it as partnership, acceptance, compassion and evocation."},{"q":"When clients express _______________, the balance of indecision begins to shift toward taking action.","o":["ambivalence","need for change","resistance","B and C"],"a":1,"e":"Checked answer, not from an official key. As clients voice their own need for change (change talk), the balance of indecision begins to shift toward action."}]},{"n":13,"title":"Communication Skills","kicker":"Lesson 13 of your course, built from Chapter 3 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l13-b1","chapter":"Learning a new skill takes stages","title":"Learning a new skill takes stages","teach":["Learning counselling skills follows predictable stages. First you become aware of a skill. Then comes awkwardness, when using it feels clumsy and forced. Next is conscious awareness: you're more comfortable, but you still have to think about it. Finally it becomes an automatic response.","Feeling awkward is a normal step, not a sign you're doing it wrong. Practice moves you through it."],"act":{"type":"choice","prompt":"Which stage comes right before conscious awareness?","options":[{"label":"Awkwardness","correct":true,"feedback":"Yes. Skills feel clumsy before they feel comfortable."},{"label":"Automatic response","correct":false,"feedback":"That's the last stage, after conscious awareness."},{"label":"Motivation","correct":false,"feedback":"Motivation isn't one of the named stages."}]}},{"id":"l13-b2","chapter":"Nonverbal communication","title":"Nonverbal communication","teach":["Much of what we communicate isn't in our words. Eye contact, facial expression, posture, gestures, energy level and the volume, pace and tone of your voice all send messages.","When two people's body language naturally matches, it's called synchrony. It's a sign of rapport. Watch your clients' nonverbal cues too, because they often show feelings their words don't."],"act":{"type":"choice","prompt":"Which of these is nonverbal communication?","options":[{"label":"Eye contact","correct":false,"feedback":"Yes, but it's not the only one."},{"label":"Volume of voice and energy level","correct":false,"feedback":"Yes, but there's more."},{"label":"All of these","correct":true,"feedback":"Right. Eye contact, voice volume and energy level all send messages."}]}},{"id":"l13-b3","chapter":"Responses that build the relationship","title":"Responses that build the relationship","teach":["Some responses are especially useful for building a relationship: attending (giving full attention), reflecting, legitimation (letting the client know their feelings make sense) and respect.","Reflection means naming the emotion the client has shown in words or body language. When it's accurate, clients feel understood. Respond to your client's own feelings, not to how other people in their story might feel."],"act":{"type":"choice","prompt":"A client says, “My husband keeps bringing home donuts and I just give in.” Which response reflects her feeling?","options":[{"label":"“Your husband must feel bad about it.”","correct":false,"feedback":"This focuses on someone else's feelings. Stay with your client's."},{"label":"“It sounds frustrating to keep facing that temptation at home.”","correct":true,"feedback":"Yes. It names her emotion and checks your understanding."},{"label":"“Just tell him to stop.”","correct":false,"feedback":"This is advice, not reflection."}]}},{"id":"l13-b4","chapter":"Focus and intent","title":"Focus and intent","teach":["Every response has a focus and an intent. The focus is where you put the emphasis: information, or the client's experience, which can be their feelings, thoughts or behaviours. The intent is your reason for the response: to acknowledge, to explore or to challenge.","Open questions (what, how, tell me) invite the client to explore. Closed questions get a short fact or a yes or no. “What do you think would work for you?” is an open question about the client's thoughts, asked to explore."],"act":{"type":"sort","prompt":"Match each counsellor response with its intent.","categories":["To acknowledge","To explore","To challenge"],"items":[{"label":"“You've packed your lunch every day this week. That took effort.”","category":0,"feedback":"Affirming an effort acknowledges the client."},{"label":"“What gets in the way of eating breakfast?”","category":1,"feedback":"An open question invites the client to explore."},{"label":"“You want more energy, and you're skipping lunch most days.”","category":2,"feedback":"Pointing out a gap between goals and actions is a gentle challenge."}]}},{"id":"l13-b5","chapter":"Challenging gently","title":"Challenging gently","teach":["Sometimes you need to point out a gap between what a client says and what they do. How you phrase it matters. “But” tends to cancel out what came before it and can sound like an accusation.","A softer approach is to state the observation without “but”, often using “and”: “You want to improve your eating habits, and you had delivery pizza twice this week.” This puts both facts side by side and lets the client think about them."],"act":{"type":"choice","prompt":"Which version is the softer challenge?","options":[{"label":"“You say you want to eat better, but you had pizza twice this week.”","correct":false,"feedback":"“But” can sound like an accusation and cancels the first part."},{"label":"“You say you want to eat better, and you had pizza twice this week.”","correct":true,"feedback":"Yes. “And” puts both facts side by side without blame."}]}}],"flashcards":[{"front":"Stages of skill development","back":"Awareness, awkwardness, conscious awareness, automatic response."},{"front":"Nonverbal communication","back":"Eye contact, facial expression, posture, gestures, energy level and voice volume, pace and tone."},{"front":"Synchrony","back":"Body language harmony between two people."},{"front":"Relationship-building responses","back":"Attending, reflecting, legitimation and respect."},{"front":"Reflection","back":"Naming the emotion a client has shown in words or body language."},{"front":"Whose feelings do you respond to?","back":"Your client's, not other people's."},{"front":"Counselling focus","back":"Information, or the client's experience: feelings, thoughts or behaviours."},{"front":"Counselling intent","back":"To acknowledge, to explore or to challenge."},{"front":"Open question","back":"Starts with what, how or tell me, and invites a fuller answer."},{"front":"Softer challenge","back":"Use “and” instead of “but” to state the observation."}],"quiz":[{"q":"What step precedes “conscious awareness” in the stages of skill development?","o":["Motivation","Learning","Awkwardness","Automatic response"],"a":2,"e":"Checked answer, not from an official key. Skills feel awkward before you reach conscious awareness."},{"q":"Which of the following is a nonverbal mode of communication?","o":["Volume of voice","Energy level","Eye contact","All of the above"],"a":3,"e":"Checked answer, not from an official key. All three are nonverbal."},{"q":"Body language harmony between two people is referred to as _________ .","o":["synchrony","empathy","encoding","awkward."],"a":0,"e":"Checked answer, not from an official key. The textbook calls this synchrony."},{"q":"Attending, reflecting, legitimation, and respect responses are particularly useful for:","o":["changing direction of a counseling session.","challenging a client.","building a relationship.","All of the above"],"a":2,"e":"Checked answer, not from an official key. The textbook lists these as relationship-building responses."},{"q":"__________ is labeling a client’s expressed verbal and nonverbal emotion.","o":["Attending","Paraphrasing","Mirroring","Reflection"],"a":3,"e":"Checked answer, not from an official key. This is the textbook's definition of reflection."},{"q":"When empathizing or reflecting, you should respond to the feelings of _______ and not to the feelings of _______.","o":["your client / others","others / your client"],"a":0,"e":"Checked answer, not from an official key. Respond to your client's feelings, not other people's."},{"q":"Use the following statement to answer questions 7-9:\n\nWhat do you think would work for you to help you lose weight?\n\nWhat type of response is this question?","o":["Attending","Mirroring","Question-closed","Question-open"],"a":3,"e":"Checked answer, not from an official key. It starts with “what” and invites a full answer."},{"q":"Use the following statement to answer questions 7-9:\n\nWhat do you think would work for you to help you lose weight?\n\nWhat is the focus of this question?","o":["Experience","Behaviour","Thoughts"],"a":2,"e":"Checked answer, not from an official key. Less certain: “What do you think…” asks for the client's thoughts, but you could argue it's about behaviour too. Check this one against your graded result."},{"q":"Use the following statement to answer questions 7-9:\n\nWhat do you think would work for you to help you lose weight?\n\nWhat is the counsellor’s intent for selecting this question?","o":["To acknowledge","To explore","To challenge"],"a":1,"e":"Checked answer, not from an official key. An open question like this is asked to explore."},{"q":"Which word would you choose to complete this statement using a soft approach: “You say you want to improve your eating habits _____ you had delivery pizza twice this week.”","o":["but","and"],"a":1,"e":"Checked answer, not from an official key. The textbook suggests stating the observation without “but”."}]},{"n":14,"title":"The Counselling Interview","kicker":"Lesson 14 of your course, built from Chapter 4 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l14-b1","chapter":"The phases of a counselling session","title":"The phases of a counselling session","teach":["A counselling interview moves through phases. In the involving phase you greet the client, build rapport, ask how things have been going and agree on an agenda together.","In the exploration–education phase you work together to understand the problem, look for strengths, assess readiness to change and offer education. In the resolving phase you tailor the plan to the client's motivation level. The closing phase wraps up the session."],"act":{"type":"sort","prompt":"Match each task with its phase.","categories":["Involving","Exploration–education","Resolving"],"items":[{"label":"Agree on an agenda for the session","category":0,"feedback":"Setting the agenda happens early, in the involving phase."},{"label":"Clarify problems and find strengths","category":1,"feedback":"Understanding the problem and strengths is exploration–education."},{"label":"Tailor the plan to the client's motivation","category":2,"feedback":"Tailoring to motivation level is the resolving phase."}]}},{"id":"l14-b2","chapter":"The “typical day” strategy","title":"The “typical day” strategy","teach":["If you have six to eight minutes, ask the client to walk you through a typical day and where eating fits in. Sit back and relax, let them tell their story with as few interruptions as possible, and use simple open questions like “What happened then?”","The biggest mistake is jumping in with your own ideas. Don't investigate problems during the story; save that for later. At the end, review and summarize what you heard."],"act":{"type":"choice","prompt":"Which of these should you NOT do during the typical day strategy?","options":[{"label":"Sit back and relax","correct":false,"feedback":"This is exactly how the textbook says to start."},{"label":"Investigate problems as they come up","correct":true,"feedback":"Right. Hold your questions and ideas until the story is told."},{"label":"Review and summarize at the end","correct":false,"feedback":"Summarizing is part of the strategy."}]}},{"id":"l14-b3","chapter":"Sharing assessment results","title":"Sharing assessment results","teach":["Don't just hand a client their results. Go through them in a neutral way, with clear standards to compare against, such as the Dietary Reference Intakes.","Give the facts and let the client make the first comments about what they mean. This keeps the client in charge of the conversation and avoids sounding like a judgement."],"act":{"type":"choice","prompt":"How should assessment results be shared?","options":[{"label":"Hand over the printout and point out the problems","correct":false,"feedback":"Results should be reviewed together, not just handed over."},{"label":"Go through them neutrally with clear standards, and let the client respond first","correct":true,"feedback":"Yes. Give the facts and invite the client's view."},{"label":"Skip them unless the client asks","correct":false,"feedback":"Results are useful when shared well."}]}},{"id":"l14-b4","chapter":"Three levels of readiness","title":"Three levels of readiness","teach":["In the resolving phase, the approach depends on the client's readiness. Level 1 is not ready (precontemplation). The goal is to raise doubt about current habits, and the best open questions deal with the need to change. Don't push an action plan.","Level 2 is unsure. The focus is on confidence, and the best questions build confidence and address barriers. Level 3 is motivated, confident and ready. Now you help the client choose a goal and make a specific action plan."],"act":{"type":"sort","prompt":"Match each goal with the readiness level.","categories":["Level 1: not ready","Level 2: unsure","Level 3: ready"],"items":[{"label":"Raise doubt about current eating habits","category":0,"feedback":"Level 1 works on why change matters."},{"label":"Build confidence and address barriers","category":1,"feedback":"Level 2 is about confidence."},{"label":"Negotiate a specific action plan","category":2,"feedback":"An action plan fits once the client is ready."}]}}],"flashcards":[{"front":"Involving phase","back":"Greet, build rapport, check in and agree on an agenda."},{"front":"Exploration–education phase","back":"Clarify problems, find strengths, assess readiness and educate."},{"front":"Resolving phase","back":"Tailor the plan to the client's motivation level."},{"front":"Typical day strategy","back":"6–8 minutes. Let the client tell their day. Don't investigate problems. Summarize at the end."},{"front":"Sharing assessment results","back":"Review neutrally with clear standards, and let the client respond first."},{"front":"Level 1 (not ready)","back":"Raise doubt. Ask about the need to change. No action plan yet."},{"front":"Level 2 (unsure)","back":"Build confidence and address barriers."},{"front":"Level 3 (ready)","back":"Choose a goal and make a specific action plan."}],"quiz":[{"q":"What is the goal of the counseling approach for a client who is at Level 1 in the Resolving Phase?","o":["Raise doubt about present dietary behaviour","Build confidence","Increase motivation to change diet","Negotiate a specific plan of action"],"a":0,"e":"Checked answer, not from an official key. Level 1 clients aren't ready, so the aim is to raise doubt about current habits."},{"q":"In which phase of the counseling process would a counsellor clarify problems and identify strengths?","o":["Involving","Exploration-education","Resolving","Closing"],"a":1,"e":"Checked answer, not from an official key. The textbook places understanding problems and finding strengths in the exploration–education phase."},{"q":"In which phase of the counseling process would a counsellor set the agenda?","o":["Involving","Exploration-education","Resolving","Closing"],"a":0,"e":"Checked answer, not from an official key. The agenda is agreed at the start, in the involving phase."},{"q":"In which phase of the counseling process would a counsellor tailor the intervention to the client’s motivational level?","o":["Involving","Exploration-education","Resolving","Closing"],"a":2,"e":"Checked answer, not from an official key. This is the resolving phase."},{"q":"When using a Typical Day Strategy, it is important to do all of the following, EXCEPT","o":["sit back and relax.","ask only open questions.","investigate problems.","review and summarize"],"a":2,"e":"Checked answer, not from an official key. The textbook's guidelines say “Don't investigate problems!”"},{"q":"The most effective open-ended questions for people who are pre-contemplative deal with","o":["building confidence.","the need to change.","addressing barriers.","A and C","All of the above"],"a":1,"e":"Checked answer, not from an official key. Level 1 clients need to see why change matters."},{"q":"For clients at Level 1, the objective is to create an action plan.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Action plans are for Level 3 clients who are ready."},{"q":"The most effective open-ended questions for people who are unsure deal with","o":["building confidence.","the need to change.","addressing barriers.","A and C","All of the above"],"a":3,"e":"Checked answer, not from an official key. Less certain: the textbook says Level 2 is about confidence, and barriers are part of that, so A and C fits best. Check this one against your graded result."},{"q":"Assessment results should be reviewed point by point in a neutral manner.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Less certain: the textbook says to review results in a neutral manner but doesn't say “point by point”. Check this one against your graded result."},{"q":"Approximately how much time in a counseling session should be allotted for a “typical day” strategy?","o":["1 to 3 minutes","3 to 6 minutes","6 to 8 minutes","8 to 10 minutes"],"a":2,"e":"Checked answer, not from an official key. The textbook says six to eight minutes."}]},{"n":15,"title":"Developing a Nutritional Care Plan","kicker":"Lesson 15 of your course, built from Chapter 5 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l15-b1","chapter":"Setting goals","title":"Setting goals","teach":["Goal setting suits clients who are ready to change (Level 3, and sometimes Level 2). It breaks a big change into small steps, and each small success builds confidence. Goal setting is part of the Nutrition Care Process, Social Cognitive Theory and motivational interviewing.","Start with a broad goal, such as eating more fruit, then narrow it down to one specific, measurable, time-bound step. Many clients pick goals that are too ambitious. Help them find the smallest goal that is achievable and worthwhile, rather than asking how much they think they can do."],"act":{"type":"choice","prompt":"A client wants to “eat healthier from now on.” What's the best next step?","options":[{"label":"Ask how much she thinks she can change this week","correct":false,"feedback":"This often leads to over-ambitious goals."},{"label":"Help her find the smallest goal that is achievable and worthwhile","correct":true,"feedback":"Yes. Small wins build confidence."},{"label":"Keep the goal broad so it's flexible","correct":false,"feedback":"Broad goals need to be narrowed to a specific step."}]}},{"id":"l15-b2","chapter":"Dietary assessment tools","title":"Dietary assessment tools","teach":["A 24-hour recall is quick, but people over- or under-report. Ask neutral questions like “What were the first foods or drinks you had after waking up?” rather than “What did you have for breakfast?”, which assumes a meal. A food frequency questionnaire shows how often foods are eaten. In a clinical setting, pairing it with a 24-hour recall gives a better picture.","A food diary (record) is filled in by the client and can also work as an intervention, because writing things down makes people more aware of their habits. Detailed history forms give clues to strengths and barriers, but some clients may find them invasive or culturally uncomfortable."],"act":{"type":"choice","prompt":"Which 24-hour recall question is better?","options":[{"label":"“What did you eat for breakfast?”","correct":false,"feedback":"This assumes the client ate breakfast."},{"label":"“What were the first foods or drinks you had after waking up today?”","correct":true,"feedback":"Yes. It doesn't assume a meal was eaten."}]}},{"id":"l15-b3","chapter":"Estimating portions","title":"Estimating portions","teach":["Everyday objects help clients estimate portions. Half a cup of fruit, vegetables, cooked cereal, pasta or rice is about a small fist. Three ounces of cooked meat, poultry or fish is about a deck of cards. A potato is about the size of a computer mouse.","Using these comparisons in recalls and food records makes estimates more accurate."],"act":{"type":"sort","prompt":"Match each portion with its everyday comparison.","categories":["Small fist","Deck of cards","Computer mouse"],"items":[{"label":"½ cup cooked rice","category":0,"feedback":"Half a cup is about a small fist."},{"label":"3 oz cooked chicken","category":1,"feedback":"Three ounces of meat is about a deck of cards."},{"label":"A small baked potato","category":2,"feedback":"A potato is about the size of a computer mouse."}]}},{"id":"l15-b4","chapter":"Body weight standards","title":"Body weight standards","teach":["Height–weight tables are outdated and no longer seen as a reliable way to find a healthy weight. BMI is used instead, but cut-offs vary by population. The World Health Organization suggests 23 as the overweight cut-off and 27.5 for obesity for most Asians. For Pacific Islanders, the overweight cut-off is 26.","BMI isn't a good guide to body fat in pregnant or breastfeeding women, very muscular people, growing children or adults over 65."],"act":{"type":"choice","prompt":"What BMI does the WHO suggest as the overweight level for Pacific Islanders?","options":[{"label":"23","correct":false,"feedback":"23 is the suggested cut-off for most Asians."},{"label":"26","correct":true,"feedback":"Yes. 26 for Pacific Islanders."},{"label":"27.5","correct":false,"feedback":"27.5 is the obesity cut-off for most Asians."}]}}],"flashcards":[{"front":"Goal setting is part of…","back":"The Nutrition Care Process, Social Cognitive Theory and motivational interviewing."},{"front":"Choosing a goal","back":"Find the smallest goal that is achievable and worthwhile."},{"front":"24-hour recall","back":"Quick, but people over- and under-report."},{"front":"Better first recall question","back":"“What were the first foods or drinks you had after waking up?”"},{"front":"Food diary as an intervention","back":"Writing intake down raises awareness and can change habits."},{"front":"Clinical intake assessment","back":"A food frequency questionnaire plus a 24-hour recall."},{"front":"Portion comparisons","back":"½ cup = small fist. 3 oz meat = deck of cards. Potato = computer mouse."},{"front":"BMI overweight cut-off for Pacific Islanders","back":"26."},{"front":"Height–weight tables","back":"Outdated. Not a reliable guide to healthy weight."}],"quiz":[{"q":"Goal-setting is a key strategy in","o":["the Nutrition Care Process.","Social cognitive theory.","Motivational interviewing.","All of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook ties goal setting to all three."},{"q":"When helping a client choose a goal, it’s best to","o":["focus on identifying the smallest goal that is achievable and worthwhile.","ask the client how much they think they can accomplish.","select a broadly stated goal.","B and C"],"a":0,"e":"Checked answer, not from an official key. The textbook recommends this rather than asking how much the client can do."},{"q":"While providing clues to a client’s strengths and potential barriers, the _________ may seem invasive to some clients and may not be culturally sensitive.","o":["24-hour recall","diet history interview","client assessment questionnaire and historical data form","All of the above"],"a":2,"e":"Checked answer, not from an official key. Less certain: detailed personal history forms are the most likely to feel invasive, but the textbook doesn't tie the wording to one tool. Check this one against your graded result."},{"q":"Which diet assessment tool is quick, but occasionally unreliable, as over and under reporting does occur?","o":["24-hour recall","diet history interview","client assessment questionnaire and historical data form","All of the above"],"a":0,"e":"Checked answer, not from an official key. Less certain: the 24-hour recall is the quick tool, and over- and under-reporting are its known weak points. Check this one against your graded result."},{"q":"One small baked potato can be estimated to be the same size as","o":["a small fist.","a deck of cards.","a baseball.","a computer mouse."],"a":3,"e":"Checked answer, not from an official key. A potato is commonly compared to a computer mouse."},{"q":"Which dietary assessment tool can also be used as an intervention technique to alter food habits?","o":["A food diary","Diet history interview","24-hour recall","All of the above"],"a":0,"e":"Checked answer, not from an official key. Keeping a food diary raises awareness and can change habits."},{"q":"In a clinical setting, you may consider a general food frequency questionnaire and a ___________ to best evaluate your client’s food intake.","o":["food diary","diet history interview","client assessment questionnaire and historical data form","24-hour recall"],"a":3,"e":"Checked answer, not from an official key. The textbook pairs a food frequency questionnaire with a 24-hour recall."},{"q":"Which of the following questions would NOT be recommended for an effective 24-hour recall?","o":["What did you eat for breakfast?","What foods were first consumed after waking up today?","How much butter did you use on your toast?","What foods were consumed during meal preparation?"],"a":0,"e":"Checked answer, not from an official key. The textbook says to avoid this because it assumes a meal was eaten."},{"q":"The World Health Organization suggests using a BMI of _________ as the level indicating overweight for Pacific Islanders.","o":["23","25","26","27.5"],"a":2,"e":"Checked answer, not from an official key. The textbook gives 26 for Pacific Islanders."},{"q":"Height-weight tables are still a reliable tool to determine a healthy weight.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. They are outdated, and BMI is used instead."}]},{"n":16,"title":"Facilitating Self Management","kicker":"Lesson 16 of your course, built from Chapter 6 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l16-b1","chapter":"Self-monitoring","title":"Self-monitoring","teach":["Keeping track of eating and activity (journaling) is one of the most useful self-management tools. Records can include what was eaten, portions, time, place, mood and hunger. Asking for too much detail makes people give up, so keep it simple. Recording gets quicker with practice.","For clients who don't want to write things down, there are alternatives: checking off boxes, using drawings or art, or watching a bowl of tokens slowly empty as goals are met."],"act":{"type":"choice","prompt":"Checking off boxes and gradually emptying a bowl are alternatives to what?","options":[{"label":"Journaling","correct":true,"feedback":"Yes. They're simpler ways to self-monitor."},{"label":"Goal setting","correct":false,"feedback":"These track behaviour, which is what journaling does."},{"label":"Meal planning","correct":false,"feedback":"These are ways to record and track, not to plan meals."}]}},{"id":"l16-b2","chapter":"The ABCs of behaviour","title":"The ABCs of behaviour","teach":["Behaviour can be broken into a chain: the antecedent (the cue that comes before), the behaviour itself, and the consequence that follows. Strategies can target any link.","Cue management (stimulus control) works on the antecedents. The aim is to change the triggering cue or reduce exposure to it. For example, keep healthy foods in a highly visible spot and tempting foods out of sight. Strategies for the behaviour itself include eating more slowly, eating in one place and finding a substitute activity, like a walk."],"act":{"type":"sort","prompt":"Match each strategy with the link in the chain it targets.","categories":["Antecedent (cue)","Behaviour","Consequence"],"items":[{"label":"Keep a bowl of fruit on the counter and chips out of sight","category":0,"feedback":"Changing what you see changes the cue."},{"label":"Put your fork down between bites","category":1,"feedback":"This changes the act of eating itself."},{"label":"Earn a reward after a week of packed lunches","category":2,"feedback":"Rewards are consequences that strengthen a behaviour."}]}},{"id":"l16-b3","chapter":"Contracts, rewards and thinking patterns","title":"Contracts, rewards and thinking patterns","teach":["Rewards are often used with contracting: a written agreement between counsellor and client to work on a goal. Small rewards right after the behaviour work best for short-term goals. Bigger rewards can suit long-term goals.","Thinking patterns matter too. Opportunity thinking sees challenges as chances to grow. Obstacle thinking focuses on why things won't work, and all-or-nothing views make people hard on themselves. Barriers to change include lack of knowledge, lack of skill, fear of taking risks and lack of social support. Many of the most common barriers can be addressed by increasing knowledge."],"act":{"type":"choice","prompt":"What are the two thinking patterns described in the textbook?","options":[{"label":"Opportunity thinking and obstacle thinking","correct":true,"feedback":"Yes. One sees chances to grow, the other sees reasons it won't work."},{"label":"Good thinking and bad thinking","correct":false,"feedback":"The textbook uses opportunity and obstacle thinking."},{"label":"Observational thinking and reward thinking","correct":false,"feedback":"These aren't the terms used."}]}},{"id":"l16-b4","chapter":"Teaching that sticks","title":"Teaching that sticks","teach":["Clients forget about half of what they hear within five minutes, especially when stressed. Keep instructions short and focused, and don't bury clients in handouts.","Use supportive language: steer away from the word “you”, give information neutrally, start with “I” and ask permission. In the Nutrition Care Process, adherence is the term for how well a client follows the plan; it replaces the older word “compliance”."],"act":{"type":"choice","prompt":"Which statement uses supportive language?","options":[{"label":"“You need to stop skipping meals.”","correct":false,"feedback":"Starting with “you” can sound like blame."},{"label":"“I have a few ideas that might help with your blood sugars. Would you like to hear them?”","correct":true,"feedback":"Yes. It starts with “I” and asks permission."},{"label":"“You're not following the plan.”","correct":false,"feedback":"This is judgemental and uses “you”."}]}}],"flashcards":[{"front":"Alternatives to journaling","back":"Checking off boxes, using art, and gradually emptying a bowl."},{"front":"ABCs of behaviour","back":"Antecedent, Behaviour, Consequence."},{"front":"Cue management (stimulus control)","back":"Change the triggering cue or reduce exposure to it."},{"front":"Controlling environmental cues","back":"Put foods you want to eat more of in a highly visible spot."},{"front":"Rewards are often used with…","back":"Contracting."},{"front":"How fast clients forget","back":"About half of the information within five minutes."},{"front":"Supportive language","back":"Avoid the word “you”, stay neutral, start with “I” and ask permission."},{"front":"NCP term for following a plan","back":"Adherence."},{"front":"Two thinking patterns","back":"Opportunity thinking and obstacle thinking."},{"front":"Many common barriers can be addressed by…","back":"Increasing knowledge."}],"quiz":[{"q":"Checking off boxes, using art, and the gradual emptying of a bowl are all alternatives to which of the following?","o":["Journaling","Countering","Goal-setting","Meal-planning"],"a":0,"e":"Checked answer, not from an official key. These are simpler ways to self-monitor instead of writing a journal."},{"q":"In the case of decreasing the occurrence of a detrimental food stimulus, the objective in _______________________ is to alter the triggering stimulus or reduce exposure to it.","o":["countering","contracting","cue management","goal setting"],"a":2,"e":"Checked answer, not from an official key. The textbook says this about cue management."},{"q":"Which of the following is a strategy to control environmental cues?","o":["Placing pennies in a jar each time a particular behaviour is accomplished","Placing foods that should be encouraged in a highly visible spot","Finding an activity to substitute for eating","All of the above"],"a":1,"e":"Checked answer, not from an official key. Changing what's visible changes the cue. Pennies are a reward, and a substitute activity targets the behaviour."},{"q":"What are the ABCs of behaviour?","o":["Action, Behaviour, Cues","Ambivalence, Behaviour, Consequence","Antecedent, Belief, Cues","Antecedent, Behaviour, Consequence"],"a":3,"e":"Checked answer, not from an official key. Antecedent, behaviour, consequence."},{"q":"Rewards are often used in conjunction with ______________________________.","o":["problem-solving","modeling","contracting","countering"],"a":2,"e":"Checked answer, not from an official key. The textbook says rewards are often used with contracting."},{"q":"Studies of patient education have shown that clients typically forget half the information presented to them within _________________________.","o":["five minutes","fifteen minutes","half an hour","an hour"],"a":0,"e":"Checked answer, not from an official key. The textbook says within five minutes."},{"q":"It’s recommended that counsellors use supportive language when providing educational instructions to a client. Supportive language usually means staying away from the word _______.","o":["diet","you","me","no"],"a":1,"e":"Checked answer, not from an official key. The textbook says supportive language usually means avoiding the word “you”."},{"q":"In the Nutrition Care Process, the American Dietetic Association uses the term _______________ to describe the degree to which a client has followed a prescribed regimen.","o":["adherence","compliance","observance","obedience"],"a":0,"e":"Checked answer, not from an official key. The Nutrition Care Process uses “adherence”."},{"q":"Thinking patterns have been categorized as","o":["good thinking and bad thinking.","opportunity thinking and reward thinking.","observational thinking and obstacle thinking.","opportunity thinking and obstacle thinking."],"a":3,"e":"Checked answer, not from an official key. The textbook describes opportunity and obstacle thinking."},{"q":"Some of the most frequently named barriers to behavior change can be addressed by _____________________________.","o":["willpower","an increase in knowledge","risk taking","money"],"a":1,"e":"Checked answer, not from an official key. Less certain: the textbook lists lack of knowledge first among the major barriers, but the sentence that settles this was cut off in what I could read. Check this one against your graded result."}]},{"n":17,"title":"Professional Development","kicker":"Turn learning into observable, ethical practice improvement • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l17-interactive-1","chapter":"Separate attendance from improvement","title":"Separate attendance from improvement","teach":["Professional development is the ongoing work of keeping knowledge, skills, judgment, and conduct fit for the role you actually perform. Reading a new article can help, but development is incomplete if nothing changes in how you assess information, communicate, document, or seek help. Distinguish attendance, learning, and practice improvement. Attendance means being present at an activity.","Learning means acquiring or revising understanding or a skill. Practice improvement means applying that learning in a way that can be observed or evaluated. A certificate usually establishes attendance or completion, not universal competence. An original example: attending a communication workshop is an activity; recognizing that you interrupt clients is learning; deliberately leaving pauses and obtaining feedback is a practice change."],"act":{"type":"sort","prompt":"Classify the strongest evidence each statement actually provides.","categories":["Attendance","Learning","Practice improvement"],"items":[{"label":"“I completed a communication webinar.”","category":0,"feedback":"Completion documents an activity, not automatically competence or a change in practice."},{"label":"“I can explain why I interrupt when I rush into advice.”","category":1,"feedback":"This shows revised understanding; it does not yet demonstrate a changed interaction."},{"label":"“In supervised role-plays I paused and invited correction; feedback showed fewer missed priorities.”","category":2,"feedback":"This links application with observed feedback rather than relying only on a certificate."},{"label":"“My portfolio lists ten courses.”","category":0,"feedback":"A course list records participation. Add what changed and how you reviewed it."}]}},{"id":"l17-interactive-2","chapter":"State a useful boundary","title":"State a useful boundary","teach":["Before offering a service, identify what your education, experience, supervision, employer policies, and applicable legal requirements permit. A course title or personal interest does not by itself authorize diagnosis, prescribing, psychotherapy, or a regulated professional title.","Verify uncertain requirements through the relevant official regulator or authority rather than relying on promotional material. The UK HCPC standards require its registrants to work within their knowledge and skills, maintain relevant development, and refer when needs exceed their scope. These are cited as an example of a professional regulatory framework, not as rules automatically applying to every reader."],"act":{"type":"choice","prompt":"A client asks, “Can you tell me the medical cause of this symptom?” Choose your response as a trainee nutrition counsellor.","options":[{"label":"“This course lets me diagnose anything related to food.”","correct":false,"feedback":"A course title does not authorize diagnosis or regulated practice. Verify actual qualifications, supervision, and applicable requirements."},{"label":"“I can support practical eating routines, but cannot determine the medical cause. Let’s identify the appropriate professional for that question.”","correct":true,"feedback":"This explains the boundary while preserving useful support. Referral is a responsible next step, not an admission that the person should be abandoned."},{"label":"“Professional standards are identical everywhere, so I already know the legal answer.”","correct":false,"feedback":"Requirements depend on location, profession, registration, and setting. Illustrative UK standards do not establish Ontario rules or your eligibility to practise."}]}},{"id":"l17-interactive-3","chapter":"Find the real learning gap","title":"Find the real learning gap","teach":["“I need to learn more about nutrition” is too broad to guide development. Identify a situation, the decision involved, and the knowledge or skill gap. For example: “How can I explain uncertainty in supplement claims without either endorsing them or dismissing the client's experience?” Separate questions about effectiveness from questions about communication or service delivery.","A clinical intervention question may need research evidence and qualified interpretation. A communication question may benefit from observed practice and feedback. A documentation question may require your organization's policy, not a research paper. Write what you currently think, why you think it, and what evidence would change your mind."],"act":{"type":"explore","prompt":"Noor gave meal-variety advice while the client repeatedly raised cost. Predict which development activity addresses the gap before opening each panel.","panels":[{"label":"More facts about food groups","text":"This may increase knowledge but does not directly address missed priorities. Choose learning based on the decision that went wrong, not the easiest course to find."},{"label":"Agenda-setting role-play with feedback","text":"Practise an opening priority question, summarize before advising, and ask an observer where the client’s concern was missed. This targets the communication gap."},{"label":"A vague promise to “be better”","text":"This gives no observable change or review. State a focused gap, a safe application, and the evidence that would show improvement."}]}},{"id":"l17-interactive-4","chapter":"Look past the impressive headline","title":"Look past the impressive headline","teach":["Before using a study, identify its question, design, participants, comparison, outcomes, duration, and limitations. NIH explains that different clinical study designs have different strengths and weaknesses; well-designed randomized trials can help evaluate causal effects, while not every question can be addressed that way. An association is not automatically a cause.","People choosing a particular food may differ in many other ways. A laboratory mechanism is not proof of a meaningful benefit in everyday life. A change in a biomarker is not necessarily equivalent to feeling better, avoiding disease, or living longer. Look for what was actually measured rather than the outcome suggested by the headline."],"act":{"type":"choice","prompt":"A webinar promises a supplement will “transform energy.” It cites a small biomarker study and offers sales commission. What is the sound next step?","options":[{"label":"Declare the study false solely because a commission is offered.","correct":false,"feedback":"A conflict deserves scrutiny and disclosure, but does not by itself prove a claim false. Evaluate the evidence and do not let sales incentives determine advice."},{"label":"Recommend it because the presenter has a polished slide deck.","correct":false,"feedback":"Presentation quality and attendance certificates do not establish clinical benefit or suitability for an individual client."},{"label":"Examine participants, comparison, outcomes, duration, harms, and independent evidence; record uncertainty and seek qualified input where needed.","correct":true,"feedback":"This checks what was actually measured instead of accepting a broad promise. A biomarker change is not automatically an everyday benefit, and commercial interests deserve attention."}]}},{"id":"l17-interactive-5","chapter":"Make records useful and safe","title":"Make records useful and safe","teach":["Documentation should allow an authorized reader to understand what happened, what was agreed, and what needs follow-up. Separate reported information from observations and interpretations. Avoid judgmental labels, unsupported diagnoses, and claims of consent that did not occur.","HCPC's recordkeeping standards for its registrants emphasize clear, accurate, prompt, and secure records. These are useful principles, while specific retention, access, correction, and disclosure requirements must be checked in the reader's own setting. An original note contrast: “Noncompliant again” gives little actionable information. “Client reports the planned food was unavailable during three shifts; chose to explore a workplace storage option” identifies the problem and decision."],"act":{"type":"sort","prompt":"Decide whether each note or action supports a clear record or needs correction.","categories":["Useful documentation","Needs correction"],"items":[{"label":"“Client reports food unavailable during three shifts; chose to explore storage.”","category":0,"feedback":"This separates the report from the decision and describes a practical barrier."},{"label":"“Noncompliant again.”","category":1,"feedback":"A judgmental label omits the circumstances and provides little continuity of care."},{"label":"Paste a distinctive client story into a personal learning tool after removing the name.","category":1,"feedback":"Removing a name may not prevent identification. Use approved systems and proper authorization and safeguards."},{"label":"Document options discussed separately from the action actually agreed.","category":0,"feedback":"This prevents an offered suggestion from being misrepresented as consent."}]}},{"id":"l17-interactive-6","chapter":"Respond to an error without hiding it","title":"Respond to an error without hiding it","teach":["Be clear about appointment arrangements, communication channels, response times, fees where relevant, and the limits of your availability. Warmth does not require becoming a friend, exchanging personal favours, or providing unlimited access. Consider how power and trust affect decisions about gifts, social media, or personal relationships.","If you discover an error, prioritize safety, obtain appropriate guidance, and follow the setting's disclosure and incident procedures. Do not conceal it, fabricate a record, or reassure beyond what is known. Learning from an error includes examining the system that allowed it, not only blaming an individual. Professional development also includes recognizing fatigue, overload, and situations in which you need support."],"act":{"type":"choice","prompt":"You notice an inaccurate note after a supervised session. What is the strongest response?","options":[{"label":"Silently overwrite it so no one can see the mistake.","correct":false,"feedback":"Concealment undermines an accurate record. Follow the setting’s correction and incident procedures rather than hiding the original error."},{"label":"Prioritize any safety issue, seek appropriate guidance, and correct the record through the approved process.","correct":true,"feedback":"This combines immediate responsibility with transparent learning. Review what allowed the error so the improvement addresses the system as well as your own practice."},{"label":"Promise the client there could not be any consequence before checking.","correct":false,"feedback":"Do not reassure beyond what is known. Obtain appropriate guidance and follow applicable disclosure procedures."}]}}],"flashcards":[],"quiz":[]}]};
